window.KMAP_EXTRA.china = {"CN-AH":[{"k":"origin","zh":"簡稱「○」取自春秋時這一帶的古國，境內的天柱山古時也叫「○山」","en":"Its one-character abbreviation comes from an ancient Spring and Autumn state here; Mount Tianzhu was once named after it too.","ja":"略称「○」は春秋時代にこの地にあった国の名に由来し、天柱山もかつて「○山」と呼ばれた"},{"k":"people","zh":"明太祖朱元璋出生在這裡的鳳陽","en":"Zhu Yuanzhang, founding emperor of the Ming dynasty, was born in Fengyang here.","ja":"明の太祖・朱元璋は、ここの鳳陽で生まれた"},{"k":"people","zh":"晚清重臣李鴻章的故鄉","en":"Hometown of Li Hongzhang, the leading statesman of the late Qing dynasty.","ja":"清末の重臣・李鴻章の故郷"},{"k":"work","zh":"李安《臥虎藏龍》有不少場景在這裡的徽派古村宏村拍攝","en":"Scenes of Ang Lee's Crouching Tiger, Hidden Dragon were filmed in the ancient village of Hongcun here.","ja":"アン・リー監督『グリーン・デスティニー』の一部は、ここの古村・宏村で撮影された"},{"k":"life","zh":"傳說豆腐是西漢淮南王劉安在這裡的八公山煉丹時意外發明的","en":"Legend says tofu was invented by accident by Liu An, Prince of Huainan, while making elixirs on Mount Bagong here.","ja":"豆腐は前漢の淮南王・劉安がここの八公山で仙薬作り中に偶然発明したと伝わる"},{"k":"record","zh":"極度瀕危的揚子鱷，野生族群幾乎只剩在本省東南部","en":"The critically endangered Chinese alligator survives in the wild almost only in the southeast of this province.","ja":"絶滅寸前のヨウスコウワニの野生個体は、ほぼこの省の南東部にしか残っていない"},{"k":"life","zh":"伯爵茶等經典調味茶常用的中國名茶「祁門紅茶」產自這裡","en":"Keemun, the Chinese black tea still used in classic blends such as Earl Grey, comes from here.","ja":"アールグレイなどのブレンドに使われる中国紅茶「キームン（祁門紅茶）」の産地"},{"k":"record","zh":"亳州有「中華藥都」之稱，是中國大陸最大的中草藥集散地","en":"Bozhou, nicknamed China's 'Medicine Capital', is mainland China's largest hub for the herbal medicine trade.","ja":"亳州は「中華薬都」と呼ばれ、中国大陸最大の生薬の集散地"},{"k":"history","zh":"383 年淝水之戰，東晉以少勝多擊敗前秦大軍","en":"In the Battle of Fei River in 383, an outnumbered Eastern Jin army crushed the Former Qin here.","ja":"383年の淝水の戦いで、東晋は少ない兵で前秦の大軍を破った"},{"k":"people","zh":"首任臺灣巡撫劉銘傳出生在今省會一帶，任內修了基隆到臺北的鐵路","en":"Liu Mingchuan, Taiwan's first governor, was born near today's capital; he built the Keelung–Taipei railway.","ja":"台湾初代巡撫・劉銘伝は今の省都の出身で、基隆〜台北の鉄道を建設した"},{"k":"people","zh":"1915 年創辦《新青年》雜誌的陳獨秀是這裡人","en":"Chen Duxiu, who founded the magazine New Youth in 1915, was born here.","ja":"1915年に雑誌『新青年』を創刊した陳独秀は、ここの出身だ"},{"k":"legend","zh":"李白 762 年死在當塗，傳說他喝醉後想撈水中月亮而淹死","en":"Li Bai died at Dangtu in 762; legend says he drowned while drunk, reaching for the moon's reflection.","ja":"李白は762年に当塗で没し、酔って水面の月を取ろうとして溺れたと伝わる"},{"k":"food","zh":"以李鴻章命名的「李鴻章雜燴」，用海參、魷魚、火腿等燉成","en":"A rich stew named after statesman Li Hongzhang mixes sea cucumber, squid, ham and more.","ja":"李鴻章の名を冠した煮込み料理には、ナマコやイカ、ハムなどが入る"},{"k":"legend","zh":"傳說臭豆腐是這裡的落第書生王致和在北京謀生時發明的","en":"Legend says stinky tofu was invented in Beijing by Wang Zhihe, a failed exam candidate from here.","ja":"臭豆腐は、科挙に落ちたここ出身の王致和が北京で考案したと伝わる"},{"k":"work","zh":"歐陽修 1046 年在滁州寫下《醉翁亭記》，留下「醉翁之意不在酒」","en":"Ouyang Xiu wrote his 1046 essay on the Old Drunkard's Pavilion while serving in Chuzhou here.","ja":"欧陽脩は1046年に滁州で『酔翁亭記』を書き、「酔翁の意は酒に在らず」の句を残した"},{"k":"work","zh":"漢樂府最長的敘事詩《孔雀東南飛》，其傳說流傳於懷寧、潛山","en":"The legend behind the longest Han yuefu narrative poem, 'Southeast Fly the Peacocks', lives on in Huaining and Qianshan.","ja":"漢代楽府最長の叙事詩『孔雀東南飛』の伝説は、懐寧・潜山に伝わる"},{"k":"work","zh":"民歌《鳳陽花鼓》唱出明初家鄉百姓的苦，暗諷朱元璋","en":"The folk song 'Fengyang Flower Drum' laments early Ming hardship and quietly criticizes the Ming founder.","ja":"民謡『鳳陽花鼓』は明初の苦しい暮らしを歌い、朱元璋をそれとなく批判する"},{"k":"brand","zh":"1997 年在蕪湖成立的奇瑞汽車，第一款車「風雲」是照西雅特 Toledo 造的","en":"Chery, founded in Wuhu in 1997, based its first car, the Fengyun, on the SEAT Toledo.","ja":"1997年に蕪湖で生まれた奇瑞の最初の車「風雲」は、セアト・トレドが元だ"},{"k":"people","zh":"留下「管鮑之交」典故的齊國名相管仲是潁上人","en":"Guan Zhong, the statesman famed for his friendship with Bao Shuya, was born in Yingshang here.","ja":"「管鮑の交わり」で知られる斉の名宰相・管仲は、潁上の出身だ"},{"k":"people","zh":"主導設計中國第一顆原子彈的鄧稼先是懷寧人","en":"Deng Jiaxian, who led the design of China's first atomic bomb, was born in Huaining here.","ja":"中国初の原爆の設計を主導した鄧稼先は、懐寧の出身だ"},{"k":"life","zh":"歙縣棠樾村有七座明清牌坊連成一排，多半是為鮑氏家族而立","en":"Tangyue village in She County has a row of seven Ming–Qing memorial archways, mostly honoring the Bao clan.","ja":"歙県棠樾村には明清の牌坊が7基並び、その多くは鮑氏のために建てられた"},{"k":"history","zh":"中國科學技術大學 1958 年創立於北京，1970 年遷到這裡的省會","en":"The University of Science and Technology of China, founded in Beijing in 1958, moved to the capital here in 1970.","ja":"中国科学技術大学は1958年に北京で創立、1970年にここの省都へ移転した"},{"k":"history","zh":"1941 年新四軍在涇縣茂林遭國軍圍攻，國共合作從此名存實亡","en":"In 1941 the New Fourth Army was attacked by Nationalists at Maolin, ending real KMT–CCP cooperation.","ja":"1941年、新四軍が茂林で国民党軍に包囲され、国共合作は事実上崩れた"},{"k":"history","zh":"三國時張遼率 800 人在今省會的逍遙津突襲孫權大軍","en":"In 215 Zhang Liao led 800 men in a raid on Sun Quan's army at Xiaoyao Ford, near today's capital.","ja":"215年、張遼は800人を率いて今の省都にある逍遥津で孫権軍を急襲した"},{"k":"people","zh":"赤壁之戰的主帥周瑜是舒城人，娶了小喬","en":"Zhou Yu, hero of the Battle of Red Cliffs and husband of Xiao Qiao, was from Shucheng here.","ja":"赤壁の戦いの周瑜は舒城の人で、小喬を妻とした"},{"k":"work","zh":"諷刺小說《儒林外史》的作者吳敬梓是全椒人","en":"Wu Jingzi, author of the satirical novel The Scholars, came from Quanjiao here.","ja":"風刺小説『儒林外史』の作者・呉敬梓は、全椒の出身だ"},{"k":"origin","zh":"清代散文流派「桐城派」，得名自創始人方苞、姚鼐等人的家鄉","en":"The Qing prose 'Tongcheng school' is named for the hometown of its founders, Fang Bao and Yao Nai.","ja":"清代の散文流派「桐城派」の名は、方苞・姚鼐ら創始者の故郷に由来する"},{"k":"history","zh":"1790 年四個來自這裡的戲班進京為乾隆祝壽，催生了京劇","en":"In 1790 four opera troupes from here performed in Beijing for Qianlong's birthday, giving birth to Peking opera.","ja":"1790年、ここの四つの劇団が乾隆帝の誕生祝いに上京し、京劇が生まれた"}],
"CN-BJ":[{"k":"origin","zh":"1928 年到 1949 年間，這裡曾改名為「北平」","en":"From 1928 to 1949 the city was renamed Beiping, 'Northern Peace'.","ja":"1928年から1949年まで「北平」と改名されていた"},{"k":"people","zh":"《駱駝祥子》《茶館》的作家老舍，在這裡的旗人家庭出生","en":"Lao She, author of Rickshaw Boy and Teahouse, was born into a poor Manchu banner family here.","ja":"『駱駝祥子』『茶館』の作家・老舎は、ここの貧しい旗人の家に生まれた"},{"k":"people","zh":"名列四大名旦之首的戲曲大師梅蘭芳，出生在這裡的前門外","en":"Mei Lanfang, foremost of the 'Four Great Dan' opera stars, was born outside Qianmen gate here.","ja":"四大名旦の筆頭・梅蘭芳は、ここの前門外で生まれた"},{"k":"work","zh":"《末代皇帝》是首部獲准在紫禁城實地拍攝的西方電影，拿下 9 座奧斯卡","en":"The Last Emperor was the first Western feature film allowed to shoot inside the Forbidden City; it won nine Oscars.","ja":"『ラストエンペラー』は紫禁城での撮影を許された初の西側映画で、アカデミー賞9部門を受賞"},{"k":"sport","zh":"奧運游泳館「水立方」在 2022 年冬奧改裝成冰壺場地「冰立方」","en":"The Olympic swimming venue, the 'Water Cube', was converted into the 'Ice Cube' curling rink for the 2022 Winter Games.","ja":"五輪水泳会場「水立方」は2022年冬季五輪でカーリング会場「氷立方」に改装された"},{"k":"symbol","zh":"市花是月季和菊花，市樹是國槐和側柏","en":"Its city flowers are the China rose and the chrysanthemum; its city trees are the pagoda tree and the Chinese arborvitae.","ja":"市の花はコウシンバラと菊、市の木はエンジュとコノテガシワ"},{"k":"festival","zh":"中秋節供奉、給孩子玩的泥塑兔子「兔兒爺」，是這座古城的傳統玩具","en":"'Lord Rabbit' (Tu'er Ye), the clay rabbit figure of the Mid-Autumn Festival, is a traditional toy of this old city.","ja":"中秋節に供える泥人形のウサギ「兎児爺」は、この古都の伝統的な玩具"},{"k":"record","zh":"大興國際機場的航廈，號稱世界最大的單體機場航站樓","en":"Daxing International Airport's terminal is billed as the world's largest single-building airport terminal.","ja":"大興国際空港のターミナルは、単一建築として世界最大の空港ターミナルとされる"},{"k":"origin","zh":"元代又稱「汗八里」，意為「可汗之城」，馬可波羅記作 Cambaluc","en":"In Yuan times it was Khanbaliq, 'City of the Khan', which Marco Polo spelled 'Cambaluc'.","ja":"元代には「ハンバリク（ハンの都）」と呼ばれ、マルコ・ポーロはカンバルクと記した"},{"k":"origin","zh":"老城小巷「胡同」一詞始見於元代，源自蒙古語的「水井」","en":"The word 'hutong' for its old alleys dates to the Yuan and comes from Mongolian for 'water well'.","ja":"路地を指す「胡同（フートン）」は元代に現れた語で、モンゴル語の「井戸」に由来する"},{"k":"record","zh":"前門附近的錢市胡同，最窄處只有約40公分寬","en":"Qianshi Hutong near Qianmen narrows to only about 40 cm wide.","ja":"前門近くの銭市胡同は、最も狭い所で幅わずか約40センチ"},{"k":"life","zh":"四合院大門多朝南採光，所以大部分胡同都是東西走向","en":"Most of its hutong alleys run east–west so courtyard houses can face south for sunlight.","ja":"四合院を南向きにするため、胡同の多くは東西方向に走っている"},{"k":"life","zh":"普通話（國語）的標準音，就是以這裡的口音為基礎","en":"Standard Mandarin's pronunciation is based on the native speech of this city.","ja":"中国の標準語「普通話」の発音は、この都市の言葉を基礎にしている"},{"k":"history","zh":"明朝從南京遷都至此，1420年10月28日正式定為首都","en":"On 28 October 1420 the Ming officially made it their capital, moving from Nanjing.","ja":"1420年10月28日、明は南京からここへ正式に都を移した"},{"k":"history","zh":"1860年英法聯軍洗劫並火燒了這裡的圓明園","en":"Anglo-French troops looted and burned the Old Summer Palace here in 1860.","ja":"1860年、英仏連合軍がここの円明園を略奪し焼き払った"},{"k":"history","zh":"1919年5月4日學生在此遊行抗議《凡爾賽和約》，史稱五四運動","en":"On 4 May 1919 students marched here against the Treaty of Versailles: the May Fourth Movement.","ja":"1919年5月4日、学生がベルサイユ条約に抗議してここでデモを行った（五四運動）"},{"k":"history","zh":"明代修築的城牆一直用到1965年才被拆除","en":"Its Ming-era city wall stood until it was pulled down in 1965.","ja":"明代に築かれた城壁は、1965年に取り壊されるまで残っていた"},{"k":"history","zh":"1153年女真人的金朝在此建都，稱為「中都」","en":"In 1153 the Jurchen Jin made it their 'Central Capital', Zhongdu.","ja":"1153年、女真族の金がここを都とし「中都」と呼んだ"},{"k":"legend","zh":"傳說紫禁城有9999間房，實際調查約為8886間","en":"Legend says its imperial palace has 9,999 rooms; surveys count about 8,886.","ja":"紫禁城には9999の部屋があるという伝説があるが、実際は約8886間"},{"k":"legend","zh":"內城西北角缺了一角，民間附會為女媧神話的「天缺西北」","en":"Folk tales link the missing northwest corner of its inner city wall to the Nüwa sky myth.","ja":"内城の北西の角が欠けているのは、女媧神話の「天は北西が欠ける」に結び付けられる"},{"k":"life","zh":"紫禁城的藏書樓文淵閣用黑瓦，象徵水，用來防火","en":"The palace library, Wenyuan Pavilion, has black roof tiles symbolizing water to ward off fire.","ja":"紫禁城の文淵閣は防火を願い、水を象徴する黒い瓦で葺かれている"},{"k":"symbol","zh":"以○○命名的宮廷犬，1860年被英軍帶回獻給維多利亞女王","en":"A palace dog breed named after this city reached Britain in 1860 and was given to Queen Victoria.","ja":"○○の名を持つ宮廷犬は1860年に英国へ渡り、ヴィクトリア女王に献上された"},{"k":"people","zh":"獨力譯完莎士比亞全集的梁實秋，1903年生於這裡","en":"Liang Shiqiu, who alone translated Shakespeare's complete works into Chinese, was born here in 1903.","ja":"シェイクスピア全集を独力で中国語に訳した梁実秋は、1903年にここで生まれた"},{"k":"work","zh":"林海音的《城南舊事》，寫她1920年代在這座城南邊大雜院的童年","en":"Lin Hai-yin's autobiographical stories of her 1920s childhood are set in this city's south side.","ja":"林海音の自伝的小説『城南旧事』は、1920年代のこの街の南側が舞台"},{"k":"work","zh":"陳凱歌《霸王別姬》以這裡的戲班名伶為主角，是首部獲坎城金棕櫚的華語片","en":"Chen Kaige's 'Farewell My Concubine', about opera actors here, was the first Chinese-language Palme d'Or winner.","ja":"この街の役者を描いた陳凱歌『さらば、わが愛／覇王別姫』は中国語映画初のパルムドール作品"},{"k":"sport","zh":"前NBA球星馬布瑞2012年帶領這裡的籃球隊首奪CBA冠軍，還被立了銅像","en":"Ex-NBA star Stephon Marbury led its Ducks to a first CBA title in 2012 and got a statue.","ja":"元NBAのマーブリーは2012年に地元チームを初のCBA優勝へ導き、銅像が建てられた"},{"k":"sport","zh":"主場在工人體育場的國安足球隊，綽號「御林軍」","en":"Its Guoan football club, nicknamed 'The Imperial Guards', plays at the Workers' Stadium.","ja":"工人体育場を本拠とするサッカーの国安は「御林軍（近衛軍）」の愛称を持つ"},{"k":"brand","zh":"中藥老字號同仁堂1669年在此創立，1723年起專供清宮御藥","en":"Tong Ren Tang, founded here in 1669, became sole herbal supplier to the Qing court in 1723.","ja":"1669年創業の漢方老舗・同仁堂は、1723年から清朝宮廷の唯一の御用達となった"},{"k":"brand","zh":"聯想1984年在這裡創立，最初的英文名叫 Legend","en":"Lenovo was founded here in 1984 under the English name Legend.","ja":"レノボは1984年にここで創業し、当初の英語名は「Legend」だった"},{"k":"brand","zh":"傳統工藝掐絲琺瑯「景泰藍」，名稱取自明代景泰年間的藍色","en":"Its cloisonné is called Jingtailan, 'Blue of Jingtai', after a Ming reign era.","ja":"伝統工芸の七宝焼「景泰藍」の名は、明の景泰年間の青に由来する"},{"k":"food","zh":"用銅鍋涮羊肉是這裡的經典吃法，據說源自元代","en":"Instant-boiled mutton in a copper hotpot is a local classic said to date from the Yuan dynasty.","ja":"銅鍋で羊肉をしゃぶしゃぶする「涮羊肉」は名物で、元代に起源があるという"},{"k":"food","zh":"傳統點心「茯苓夾餅」，用中藥材茯苓做餡料夾在薄餅裡","en":"Fuling jiabing is a traditional snack whose filling uses fu ling, a fungus from Chinese medicine.","ja":"伝統菓子「茯苓夾餅」は、漢方の茯苓を使った餡を薄い皮ではさむ"},{"k":"festival","zh":"琉璃廠一帶的廠甸廟會在正月初一到十五舉行，以超長糖葫蘆聞名","en":"The Changdian temple fair near Liulichang runs from the 1st to 15th of the lunar new year.","ja":"琉璃廠周辺の廠甸廟会は旧正月1日から15日まで開かれ、特大の糖葫蘆が名物"},{"k":"nature","zh":"春季常有來自戈壁的沙塵暴，2002年4月一次就落下近5萬噸沙塵","en":"Spring dust storms blow in from the Gobi; one in April 2002 dumped nearly 50,000 tons of dust.","ja":"春はゴビ砂漠から砂嵐が来て、2002年4月には一度に約5万トンの砂塵が降った"},{"k":"nature","zh":"通往杭州的大運河，北端終點就在這裡","en":"It is the northern terminus of the Grand Canal that runs to Hangzhou.","ja":"杭州へ続く大運河の北の終点はここにある"}],
"CN-CQ":[{"k":"people","zh":"偶像團體 TFBOYS 的王俊凱、王源，都在這裡出生","en":"Karry Wang and Roy Wang of the boy band TFBOYS were both born here.","ja":"アイドルグループTFBOYSの王俊凱と王源は、どちらもここの生まれ"},{"k":"people","zh":"元帥劉伯承的故鄉；他堅持不打麻藥動眼睛手術，被德國醫生稱為「軍神」","en":"Home of Marshal Liu Bocheng, hailed as the 'God of War' by a German surgeon after eye surgery without anesthesia.","ja":"劉伯承元帥の故郷。麻酔なしで目の手術に耐え、ドイツ人医師に「軍神」と称えられた"},{"k":"work","zh":"易烊千璽、周冬雨主演的電影《少年的你》在這裡拍攝","en":"The film Better Days, starring Jackson Yee and Zhou Dongyu, was shot here.","ja":"易烊千璽と周冬雨が主演した映画『少年の君』は、ここで撮影された"},{"k":"symbol","zh":"市花是山茶花，市樹是黃桷樹","en":"Its city flower is the camellia, and its city tree is the huangjue fig (Ficus virens).","ja":"市の花はツバキ、市の木は黄桷樹（イチジク属の大木）"},{"k":"record","zh":"皇冠大扶梯長 112 公尺，是中國最長的單段坡地電扶梯","en":"The Huangguan escalator, 112 m long, is China's longest single-run hillside escalator.","ja":"皇冠大エスカレーターは全長112mで、中国最長の一段式の斜面エスカレーター"},{"k":"life","zh":"黃桷灣立交橋疊了 5 層、15 條匝道，連通 8 個方向","en":"The Huangjuewan interchange stacks five levels and 15 ramps, linking roads in eight directions.","ja":"黄桷湾インターチェンジは5層・15本のランプで、8方向をつないでいる"},{"k":"record","zh":"奉節的小寨天坑最深達 662 公尺，是世界最深的天坑","en":"Xiaozhai Tiankeng in Fengjie, up to 662 m deep, is the world's deepest sinkhole.","ja":"奉節の小寨天坑は深さ最大662mで、世界一深い天坑"},{"k":"people","zh":"盧作孚的民生公司主導 1938 年宜昌大撤退，被譽為「中國實業的敦刻爾克」","en":"Lu Zuofu's Minsheng shipping firm led the 1938 Yichang evacuation, called 'the Dunkirk of Chinese industry'.","ja":"盧作孚の民生公司は1938年の宜昌大撤退を担い、「中国産業のダンケルク」と称された"},{"k":"people","zh":"明末女將秦良玉率領「白桿兵」，是二十四史將相列傳中唯一的女性","en":"Ming general Qin Liangyu, of Shizhu, is the only woman with a biography among generals in the official histories.","ja":"明末の女将軍秦良玉は白桿兵を率い、正史の将相列伝に載る唯一の女性"},{"k":"legend","zh":"豐都被稱為「鬼城」，傳說來自仙人陰長生、王方平的姓合成「陰王」","en":"Fengdu's 'Ghost City' legend merges two immortals' surnames, Yin and Wang, into Yinwang, king of the dead.","ja":"豊都が「鬼城」と呼ばれるのは、仙人陰長生と王方平の姓が合わさり「陰王」となった伝説から"},{"k":"life","zh":"豐都鬼城的天子殿前，傳說亡魂要單腳站立三分鐘接受考驗","en":"At Fengdu's Tianzi Palace, the dead are said to be tested by standing on one foot for three minutes.","ja":"豊都鬼城の天子殿の前では、亡者は片足で3分間立つ試練を受けるとされる"},{"k":"brand","zh":"長安汽車的源頭是李鴻章 1862 年設的上海洋炮局，抗戰時遷到這裡","en":"Changan Automobile traces back to Li Hongzhang's 1862 Shanghai gun bureau, moved here during the war with Japan.","ja":"長安汽車の起源は李鴻章が1862年に設けた上海洋砲局で、日中戦争中にここへ移転した"},{"k":"history","zh":"1941 年 6 月 5 日日軍空襲，躲在防空隧道裡的約 4000 人窒息而死","en":"On 5 June 1941, about 4,000 people sheltering in a tunnel suffocated during a Japanese air raid.","ja":"1941年6月5日の日本軍の空襲で、防空トンネルに避難した約4000人が窒息死した"},{"k":"history","zh":"1939 年這裡遭日軍大轟炸後，美國禁止對日出口飛機零件，是首次對日經濟制裁","en":"After the 1939 raids here, the US banned aircraft-part exports to Japan, its first economic sanction on Japan.","ja":"1939年のここへの爆撃の後、米国は対日航空機部品輸出を禁じ、初の対日経済制裁とした"},{"k":"origin","zh":"1189 年宋光宗趙惇先封王、再登帝位，雙喜臨門，便把這塊封地升格改名","en":"In 1189 Zhao Dun, made a prince and then crowned emperor, renamed his fief to mark the double celebration.","ja":"1189年、趙惇が王に封じられた後に皇帝へ即位した「二重の喜び」から、この地は改名された"},{"k":"history","zh":"1891 年成為中國第一個對外國人開放的內陸通商口岸","en":"In 1891 it became the first inland commercial port in China opened to foreigners.","ja":"1891年、外国人に開放された中国初の内陸通商港となった"},{"k":"history","zh":"直到 1907 年，才有輪船不靠縴夫拉縴就自己開到這裡","en":"Not until 1907 did a steamship reach here without being hauled upriver by human trackers.","ja":"1907年になって初めて、人力の綱引きなしで汽船がここまで遡航した"},{"k":"life","zh":"夏天極熱，與武漢、南京並稱長江沿岸的「三大火爐」","en":"With Wuhan and Nanjing, it is one of the Yangtze's 'Three Furnaces' for its scorching summers.","ja":"夏は酷暑で、武漢・南京と並び長江沿いの「三大かまど」と呼ばれる"},{"k":"work","zh":"寧浩 2006 年的低成本電影《瘋狂的石頭》以這裡為舞台，滿口當地方言","en":"Ning Hao's low-budget 2006 hit Crazy Stone is set here and full of the local dialect.","ja":"寧浩監督の低予算映画『クレイジー・ストーン ～翡翠狂騒曲～』（2006）は、ここが舞台で方言満載"},{"k":"people","zh":"江津出身的元帥聶榮臻主持「兩彈一星」，是十大元帥中最後辭世的","en":"Jiangjin-born Marshal Nie Rongzhen led China's bomb and missile programs and was the last surviving PLA marshal.","ja":"江津出身の聶栄臻元帥は「両弾一星」を指揮し、十大元帥で最後まで存命した"},{"k":"history","zh":"江津出身的聶榮臻 1940 年救下日本孤女美穗子，兩人 1980 年在北京重逢","en":"Jiangjin-born Nie Rongzhen saved a Japanese orphan, Mihoko, in 1940; they met again in Beijing in 1980.","ja":"江津出身の聶栄臻は1940年に日本人の孤児美穂子を救い、1980年に北京で再会した"},{"k":"nature","zh":"長江三峽的第一峽瞿塘峽，是三峽中最短也最窄的","en":"Qutang Gorge, first of the Yangtze's Three Gorges, is the shortest and narrowest of the three.","ja":"長江三峡の最初の峡谷・瞿塘峡は、三峡で最も短く最も狭い"},{"k":"history","zh":"瞿塘峽的「粉壁牆」上刻有近千字題刻，最早可追溯到宋代","en":"The Chalk Wall in Qutang Gorge bears nearly 1,000 carved characters, the oldest from the Song dynasty.","ja":"瞿塘峡の「粉壁牆」には千字近い題刻があり、最古のものは宋代"},{"k":"food","zh":"麻辣火鍋一說起源於碼頭工人，用便宜的牛油炒辣椒花椒來煮牛雜","en":"One story says spicy hot pot began with dock workers frying chili in cheap beef tallow to cook offal.","ja":"麻辣火鍋は、港の労働者が安い牛脂で唐辛子と山椒を炒め、牛の内臓を煮たのが始まりとの説がある"},{"k":"life","zh":"山城街頭拿竹棒幫人挑貨的臨時挑夫，被稱為「棒棒」或「棒棒軍」","en":"Porters who carry loads on bamboo poles through the hilly streets here are nicknamed 'bangbang'.","ja":"竹の棒で荷物を担ぐ坂の街の担ぎ屋は「棒棒（バンバン）」と呼ばれる"},{"k":"people","zh":"巴國將軍巴蔓子向楚借兵許下三城，事後自刎以頭代城，墓就在市中心","en":"Ba general Ba Manzi promised Chu three cities for aid, then gave his own head instead; his tomb is downtown.","ja":"巴国の将軍巴蔓子は楚に3城を約束したが、城の代わりに自らの首を差し出した。墓は市中心にある"},{"k":"life","zh":"1987 年通車的長江索道長約 1166 公尺，一個車廂可載 81 人","en":"The Yangtze River Cableway, opened in 1987, runs about 1,166 m across the river; each cabin holds 81.","ja":"1987年開業の長江ロープウェイは全長約1166m、1両に81人が乗れる"},{"k":"history","zh":"1945 年國共雙方在這裡談判 42 天，10 月 10 日簽下《雙十協定》","en":"In 1945 Nationalists and Communists negotiated here for 42 days, signing the Double Tenth Agreement on Oct 10.","ja":"1945年、国共両党がここで42日間交渉し、10月10日に双十協定に調印した"},{"k":"people","zh":"二戰期間，美國將領史迪威以這裡為駐地","en":"During WWII, US general Joseph Stilwell was based here.","ja":"第二次世界大戦中、米国のスティルウェル将軍はここを拠点とした"}],
"CN-FJ":[{"k":"origin","zh":"唐朝 733 年在這裡設「○○經略使」，是這個省名第一次出現","en":"The province's name first appeared in 733, when the Tang set up a military governor's office named after two local prefectures.","ja":"省名は733年、唐が二つの州名を合わせた経略使を置いたのが初出"},{"k":"people","zh":"作家林語堂出生在漳州平和縣的坂仔","en":"Writer Lin Yutang was born in Banzai, Pinghe County, Zhangzhou.","ja":"作家・林語堂は漳州平和県の坂仔で生まれた"},{"k":"sport","zh":"羽球名將林丹出生在上杭縣，是第一位衛冕奧運男單金牌的選手","en":"Badminton star Lin Dan, the first man to retain an Olympic singles title, was born in Shanghang County here.","ja":"バドミントンの林丹はここの上杭県生まれ。五輪男子シングルスで初の連覇を達成"},{"k":"festival","zh":"廈門人中秋擲骰子「博餅」贏月餅，相傳是鄭成功部將為解士兵鄉愁所創","en":"In Xiamen, Mid-Autumn means 'Bo Bing' dice games for mooncakes, said to be invented for Koxinga's homesick troops.","ja":"廈門の中秋は月餅を賭けるサイコロ遊び「博餅」。鄭成功の兵の郷愁を慰めるため考案されたという"},{"k":"symbol","zh":"廈門的市花是三角梅、市樹是鳳凰木、市鳥是白鷺","en":"Xiamen's city flower is the bougainvillea, its tree the flame tree, and its bird the egret.","ja":"廈門の市の花はブーゲンビリア、市の木はホウオウボク、市の鳥はシラサギ"},{"k":"record","zh":"泉州的洛陽橋 1059 年完工，被稱為中國第一座跨海石橋","en":"Quanzhou's Luoyang Bridge, finished in 1059, is called China's first stone bridge across the sea.","ja":"泉州の洛陽橋は1059年の完成で、中国初の海を渡る石橋とされる"},{"k":"record","zh":"全球最大的電動車電池廠「寧德時代」，總部就在寧德","en":"CATL, the world's biggest EV battery maker, is headquartered in Ningde here.","ja":"世界最大のEV電池メーカーCATL（寧徳時代）は、ここの寧徳に本社を置く"},{"k":"life","zh":"鼓浪嶼人均鋼琴擁有率全國最高，有「鋼琴之島」之稱","en":"Gulangyu has China's highest per-capita piano ownership, earning it the name 'Piano Island'.","ja":"鼓浪嶼は一人当たりのピアノ保有率が全国一で、「ピアノの島」と呼ばれる"},{"k":"people","zh":"翻譯《天演論》、提出翻譯要「信、達、雅」的嚴復，出生於○○的省會","en":"Yan Fu, who translated Huxley's Evolution and Ethics and named faithfulness, expressiveness, elegance, was born here.","ja":"『天演論』を訳し、翻訳の「信・達・雅」を唱えた厳復は○○の省都の生まれ。"},{"k":"people","zh":"集理學大成的朱熹，1130 年出生在這裡的尤溪","en":"Zhu Xi, the great synthesizer of Neo-Confucianism, was born in Youxi here in 1130.","ja":"朱子学を大成した朱熹は、1130年に○○の尤渓で生まれた。"},{"k":"people","zh":"1683 年率清軍攻下臺灣、迫使鄭克塽投降的施琅，是泉州晉江人","en":"Shi Lang, the admiral who took Taiwan for the Qing in 1683, was born in Jinjiang, Quanzhou.","ja":"1683年に清軍を率いて台湾を攻略した施琅は、泉州晋江の出身。"},{"k":"people","zh":"寫下詩集《繁星》《春水》的女作家冰心，出生在○○省會","en":"Bing Xin, the writer known for the poetry collections A Maze of Stars and Spring Water, was born in the capital here.","ja":"詩集『繁星』『春水』で知られる女性作家・冰心は○○の省都生まれ。"},{"k":"history","zh":"五代十國時，王審知在這裡建立一個王國，後來被南唐所滅","en":"In the Five Dynasties era, Wang Shenzhi founded a kingdom here that was later conquered by Southern Tang.","ja":"五代十国時代、王審知がここに国を建てたが、のちに南唐に滅ぼされた。"},{"k":"sport","zh":"永春的白鶴拳相傳由方七娘觀察白鶴所創，影響了沖繩的剛柔流空手道","en":"White Crane kung fu from Yongchun, said to be created by Fang Qiniang, shaped Okinawa's Goju-ryu karate.","ja":"永春の白鶴拳は方七娘が鶴を見て創ったとされ、沖縄の剛柔流空手に影響を与えた。"},{"k":"work","zh":"金庸《笑傲江湖》裡林平之家的鏢局，就開在○○的省會","en":"In Jin Yong's The Smiling, Proud Wanderer, Lin Pingzhi's family escort agency is based in this province's capital.","ja":"金庸『秘曲 笑傲江湖』で林平之の実家の鏢局があるのは、○○の省都。"},{"k":"work","zh":"奧斯卡最佳紀錄片《美國工廠》拍的中國汽車玻璃大廠，總部就在這裡","en":"The Chinese auto-glass maker filmed in the Oscar-winning documentary American Factory is headquartered here.","ja":"アカデミー賞受賞作『アメリカン・ファクトリー』に登場する中国の自動車ガラス大手は、○○に本社がある。"},{"k":"festival","zh":"農曆正月廿九的「拗九節」，省會一帶出嫁的女兒會送甜粥回娘家孝敬父母","en":"On the 29th of the first lunar month, married daughters around the capital bring sweet porridge to their parents.","ja":"旧暦1月29日の「拗九節」には、省都一帯で嫁いだ娘が甘い粥を実家の親に届ける。"},{"k":"festival","zh":"沿海的「送王船」儀式，2020 年由中國與馬來西亞聯合列入人類非物質文化遺產","en":"The Ong Chun boat-sending rite of this coast was inscribed by UNESCO in 2020, jointly with Malaysia.","ja":"沿岸部の「送王船」の儀式は、2020年に中国とマレーシアの共同で無形文化遺産に登録された。"},{"k":"origin","zh":"省名是從唐代境內兩個州名各取首字組成，其中一個州就是今天的省會","en":"The province's name joins the first characters of two Tang-era prefectures, one of them today's capital.","ja":"省名は唐代の二つの州名から一字ずつ取ったもので、そのうち一つは現在の省都。"},{"k":"origin","zh":"泉州因遍植刺桐樹而被稱為「刺桐城」，阿拉伯商人把它記作 Zayton","en":"Quanzhou was called the Coral-Tree City for its planted Erythrina trees; Arab traders knew it as Zayton.","ja":"泉州は植えられたデイゴにちなみ「刺桐城」と呼ばれ、アラブ商人はザイトンと記した。"},{"k":"symbol","zh":"漳州以水仙花聞名，水仙也是漳州的市花","en":"Zhangzhou here is famed for narcissus, which is also its city flower.","ja":"○○の漳州はスイセンの名産地で、スイセンは市の花でもある。"},{"k":"record","zh":"南宋建成、長約 2 公里的安平橋，直到 1905 年都是中國最長的橋","en":"The Song-era Anping Bridge, about 2 km long, was China's longest bridge until 1905.","ja":"南宋に完成した全長約2キロの安平橋は、1905年まで中国最長の橋だった。"},{"k":"record","zh":"晉江草庵有一尊 1339 年刻在岩壁上的摩尼光佛，是罕見的摩尼教遺跡","en":"Cao'an in Jinjiang holds a 1339 rock carving of Mani, a rare surviving Manichaean temple.","ja":"晋江の草庵には1339年に岩壁へ彫られたマニ像があり、珍しいマニ教の遺跡だ。"},{"k":"record","zh":"平潭被視為中國大陸距離臺灣本島最近的地方","en":"Pingtan here is considered the closest place in mainland China to the island of Taiwan.","ja":"○○の平潭は、中国大陸で台湾本島に最も近い場所とされる。"},{"k":"life","zh":"惠安女的傳統服飾包頭又露出腰身，被戲稱「封建頭、民主肚」","en":"Hui'an women's traditional dress covers the head but bares the midriff: feudal head, democratic belly.","ja":"恵安女の伝統衣装は頭を覆いお腹を見せ、「封建の頭、民主の腹」と冗談で言われる。"},{"k":"food","zh":"省會的「扁肉燕」外皮不是麵粉，而是把豬肉捶打成薄片做成的","en":"The capital's rouyan dumplings use a wrapper made not of flour but of pork pounded paper-thin.","ja":"省都の「扁肉燕」の皮は小麦粉ではなく、豚肉を叩いて薄くのばして作る。"},{"k":"food","zh":"省會被視為茉莉花茶製法的發源地，2014 年列為全球重要農業文化遺產","en":"The capital is seen as the birthplace of jasmine tea making, a FAO agricultural heritage system since 2014.","ja":"省都はジャスミン茶製法の発祥地とされ、2014年に世界農業遺産に認定された。"},{"k":"history","zh":"1884 年中法戰爭，法國艦隊在馬江擊沉了這裡水師 11 艘船中的 9 艘","en":"In 1884 a French squadron sank 9 of the 11 ships of the local Chinese fleet on the Min River here.","ja":"1884年の清仏戦争で、フランス艦隊が馬江でこの地の艦隊11隻中9隻を沈めた。"},{"k":"history","zh":"1842 年《南京條約》開放的五個通商口岸中，有兩個在這裡","en":"Two of the five treaty ports opened by the 1842 Treaty of Nanking were in this province.","ja":"1842年の南京条約で開港した五つの港のうち、二つが○○にある。"},{"k":"history","zh":"1292 年馬可・波羅護送蒙古公主前往波斯，就是從泉州出海","en":"In 1292 Marco Polo set sail from Quanzhou here, escorting a Mongol princess to Persia.","ja":"1292年、マルコ・ポーロはモンゴルの姫をペルシアへ送るため泉州から船出した。"},{"k":"nature","zh":"全省九成是山地丘陵，有「八山一水一分田」的說法","en":"About 90% of the province is mountains and hills: eight parts mountain, one part water, one part field.","ja":"省の約9割が山地・丘陵で、「八山一水一分田」と言われる。"},{"k":"brand","zh":"運動品牌安踏 1991 年在晉江創立，晉江也被稱為中國「鞋都」","en":"Sportswear brand Anta was founded in Jinjiang here in 1991; Jinjiang is called China's footwear capital.","ja":"スポーツブランドの安踏は1991年に晋江で創業し、晋江は中国の「靴の都」と呼ばれる。"},{"k":"brand","zh":"以修圖 App「美圖秀秀」聞名的美圖公司，總部在廈門","en":"Meitu, the photo-editing app company, is headquartered in Xiamen.","ja":"写真加工アプリで知られる美図（Meitu）は、廈門に本社を置く。"},{"k":"legend","zh":"守護婦女生產的女神臨水夫人陳靖姑，傳說生於省會，臺灣有上百座廟供奉她","en":"Chen Jinggu, goddess protecting childbirth, is said to be born in the capital; Taiwan has over 130 temples to her.","ja":"安産を守る女神・臨水夫人陳靖姑は省都生まれとされ、台湾にも130以上の廟がある。"}],
"CN-GD":[{"k":"people","zh":"戊戌變法的梁啟超，出生在新會的茶坑村","en":"Liang Qichao of the 1898 Hundred Days' Reform was born in Chakeng village, Xinhui.","ja":"戊戌変法の梁啓超は、新会の茶坑村で生まれた"},{"k":"people","zh":"武術宗師黃飛鴻生於南海縣佛山鎮，以他為主角的電影超過百部","en":"Martial arts master Wong Fei-hung was born in Foshan, Nanhai; more than 100 films have been made about him.","ja":"武術家・黄飛鴻は南海県仏山鎮の生まれ。彼を描いた映画は100本を超える"},{"k":"work","zh":"姜文《讓子彈飛》的「鵝城」在江門台山拍攝，黃四郎宅邸則在開平碉樓","en":"Jiang Wen's Let the Bullets Fly shot its 'Goose Town' in Taishan, and Huang's mansion among the Kaiping towers.","ja":"姜文監督『さらば復讐の狼たちよ』の「鵝城」は台山で、黄四郎の屋敷は開平の望楼で撮影"},{"k":"sport","zh":"足球隊「恒大」在 2013 年成為第一支奪得亞冠冠軍的中國球隊","en":"Evergrande FC became the first Chinese club to win the AFC Champions League, in 2013.","ja":"サッカーの「恒大」は2013年、中国のクラブとして初めてACLを制した"},{"k":"festival","zh":"潮汕的「英歌舞」，舞者把臉畫成梁山好漢，揮著短棍踏步變陣","en":"In Chaoshan's Yingge dance, performers paint their faces as Water Margin heroes and march in formation clacking short sticks.","ja":"潮汕の「英歌舞」では、踊り手が水滸伝の好漢の隈取りをし、短い棒を打ち鳴らして隊列を組む"},{"k":"symbol","zh":"省會從 1982 年起以木棉為市花","en":"The provincial capital has had the kapok as its city flower since 1982.","ja":"省都は1982年からキワタ（木棉）を市の花にしている"},{"k":"life","zh":"傳說五位仙人騎五色羊、帶著稻穗降臨，省會因此別稱「羊城」","en":"Legend says five immortals rode in on five rams bearing rice ears, so the capital is nicknamed 'Goat City'.","ja":"五人の仙人が五色の羊に乗って稲穂を授けた伝説から、省都は「羊城」と呼ばれる"},{"k":"history","zh":"1839 年林則徐在虎門海灘挖池，用鹽與石灰銷毀鴉片，前後 23 天","en":"In 1839 Lin Zexu destroyed seized opium at Humen over 23 days, dissolving it in pits with salt and lime.","ja":"1839年、林則徐は虎門の浜に池を掘り、塩と石灰でアヘンを23日かけて処分した"},{"k":"history","zh":"1757 到 1842 年清廷只准西洋商船在省會一港通商，外商住在珠江邊的十三行","en":"From 1757 to 1842 Qing China let Western ships trade only at this province's capital, in the Thirteen Factories.","ja":"1757〜1842年、清は西洋との貿易をここの省都1港に限り、外国商人は珠江沿いの十三行に住んだ"},{"k":"history","zh":"1279 年崖門海戰，陸秀夫背著幼帝趙昺跳海，南宋就此滅亡","en":"At the 1279 Battle of Yamen, minister Lu Xiufu leapt into the sea with the boy emperor, ending the Song dynasty.","ja":"1279年の崖山の戦いで陸秀夫が幼帝を背負って海に身を投げ、南宋は滅んだ"},{"k":"history","zh":"1911 年黃花崗起義失敗，72 位烈士合葬，臺灣把 3 月 29 日定為青年節紀念","en":"The failed 1911 Huanghuagang Uprising here left 72 martyrs; Taiwan marks March 29 as Youth Day in their memory.","ja":"1911年の黄花崗起義で倒れた72烈士を記念し、台湾は3月29日を青年節としている"},{"k":"people","zh":"戊戌變法的領袖康有為，出生在南海縣（今佛山南海區）","en":"Kang Youwei, leader of the 1898 Hundred Days' Reform, was born in Nanhai County, now part of Foshan.","ja":"戊戌変法を主導した康有為は、南海県（現在の仏山市南海区）の生まれ"},{"k":"people","zh":"太平天國的洪秀全是花縣客家人，屢試不第後自稱是耶穌的弟弟","en":"Taiping leader Hong Xiuquan, a Hakka from Hua County, failed the imperial exams, then claimed to be Jesus's brother.","ja":"太平天国の洪秀全は花県の客家出身。科挙に落ち続けた末、自らをイエスの弟と称した"},{"k":"legend","zh":"韓愈被貶到潮州時寫〈祭鱷魚文〉驅逐鱷魚，當地的江因此叫韓江","en":"Exiled to Chaozhou in 819, Han Yu wrote an essay ordering the crocodiles away; the local river is named after him.","ja":"潮州に左遷された韓愈は「祭鰐魚文」でワニを追い払い、地元の川は韓江と名付けられた"},{"k":"symbol","zh":"2022 年命名的滅絕鱷類「韓愈鱷」，被認為就是韓愈在潮州驅趕的那種鱷魚","en":"Hanyusuchus, an extinct crocodilian named in 2022, is thought to be the beast Han Yu banished from Chaozhou.","ja":"2022年に命名された絶滅ワニ「ハンユスクス」は、韓愈が潮州から追い払ったワニとみられる"},{"k":"history","zh":"1094 年蘇軾被貶到惠州，帶頭捐錢在西湖築堤，後人稱為蘇堤","en":"Exiled to Huizhou in 1094, poet Su Shi funded a causeway on its West Lake, later named the Su Causeway.","ja":"1094年に恵州へ流された蘇軾は西湖の堤づくりに寄付し、のちに蘇堤と呼ばれた"},{"k":"brand","zh":"華為 1987 年在深圳創立，創辦人任正非是解放軍退伍軍官","en":"Huawei was founded in Shenzhen in 1987 by Ren Zhengfei, a former People's Liberation Army officer.","ja":"ファーウェイ（華為）は1987年に深圳で創業。創業者の任正非は人民解放軍の元将校"},{"k":"brand","zh":"總部在深圳的騰訊，1999 年推出通訊軟體 OICQ，後來改名 QQ","en":"Shenzhen-based Tencent launched the messenger OICQ in 1999; it was soon renamed QQ.","ja":"深圳に本社を置くテンセントは1999年にOICQを公開し、のちにQQへ改名した"},{"k":"brand","zh":"順德是美的、格蘭仕等家電巨頭的總部所在，以家具與家電製造聞名","en":"Shunde hosts the headquarters of appliance giants Midea and Galanz and is known for furniture and appliances.","ja":"順徳には美的（マイディア）やギャランツの本社があり、家具と家電の製造で知られる"},{"k":"food","zh":"順德在 2014 年獲聯合國教科文組織選為「美食之都」","en":"Shunde District here was named a UNESCO Creative City of Gastronomy in 2014.","ja":"順徳は2014年、ユネスコの食文化創造都市に選ばれた"},{"k":"life","zh":"普通話的「檸檬」一詞，是從這個省的方言借來的","en":"The Mandarin word for lemon, ningmeng, was borrowed from this province's local language.","ja":"中国語の「檸檬（ニンモン）」という言葉は、この省の方言から借用された"},{"k":"work","zh":"電影《葉問》（2008）的故事舞台在佛山，實際卻是在上海搭景拍攝","en":"Ip Man (2008) is set in Foshan, but it was shot in Shanghai because the real city looked too modern.","ja":"映画『イップ・マン 序章』（2008）の舞台は仏山だが、実際には上海で撮影された"},{"k":"sport","zh":"2010 年亞運開幕式在珠江的海心沙島舉行，選手搭船入場，首次不在體育場開幕","en":"The 2010 Asian Games opened on an island in the Pearl River, with athletes arriving by boat, not in a stadium.","ja":"2010年アジア大会の開会式は珠江の海心沙で行われ、選手は船で入場。競技場外での開催は初"},{"k":"festival","zh":"省會每年除夕前辦迎春花市，市民習慣去「行花街」買年花","en":"Before Lunar New Year the provincial capital holds flower fairs, where locals 'walk the flower street' to buy blooms.","ja":"省都では旧正月前に花市が開かれ、人々は「行花街」と呼んで正月の花を買いに行く"},{"k":"record","zh":"德慶縣的金林隕石坑，是已知全新世規模最大的撞擊坑","en":"The Jinlin crater in Deqing County is the largest known impact crater of the Holocene epoch.","ja":"徳慶県の金林クレーターは、完新世で最大とされる衝突クレーター"},{"k":"nature","zh":"西江、北江、東江在這裡匯流，形成珠江三角洲","en":"The West, North and East rivers converge here to form the Pearl River Delta.","ja":"西江・北江・東江がここで合流し、珠江デルタをつくる"},{"k":"nature","zh":"西南端的雷州半島是中國第三大半島，南面隔海峽與一座大島相望","en":"Its Leizhou Peninsula is China's third-largest peninsula, facing a big island across a strait to the south.","ja":"雷州半島は中国で3番目に大きな半島で、南は海峡を挟んで大きな島と向き合う"},{"k":"people","zh":"李小龍的祖籍在順德均安，祖居開放參觀，村裡還有以他命名的街","en":"Bruce Lee's ancestral home is in Jun'an, Shunde, where the family house is open to visitors and a street bears his name.","ja":"ブルース・リーの祖籍は順徳の均安で、祖先の家が公開され、彼の名を冠した通りもある"},{"k":"life","zh":"順德有「自梳女」傳統：女子自己盤起頭髮、終身不嫁，始於明末清初","en":"Shunde is known for 'comb sisters', women who put up their own hair and vowed never to marry, from the late Ming.","ja":"順徳には、自ら髪を結い上げて生涯結婚しない「自梳女」の伝統が明末清初からあった"},{"k":"history","zh":"鴉片戰爭後，今天的湛江一帶被法國租借為殖民地","en":"After the Opium Wars, the area of present-day Zhanjiang became a French leased territory.","ja":"アヘン戦争後、現在の湛江一帯はフランスの租借地となった"}],
"CN-GS":[{"k":"origin","zh":"名字取自古代兩個州的首字，兩州就是今天的張掖和酒泉","en":"Its name joins the first characters of two old prefectures, today's Zhangye and Jiuquan.","ja":"名は古い二つの州の頭文字から。その二州とは今の張掖と酒泉"},{"k":"people","zh":"讓匈奴聞風喪膽的西漢「飛將軍」李廣，故鄉在這裡","en":"Li Guang, the Han dynasty 'Flying General' feared by the Xiongnu, came from here.","ja":"匈奴に恐れられた前漢の「飛将軍」李広の故郷"},{"k":"work","zh":"井上靖西域小說的代表作《敦煌》，1988 年改編成電影","en":"Yasushi Inoue's novel Tun-huang, the best known of his Western Regions stories, was filmed in 1988.","ja":"井上靖の西域小説の代表作『敦煌』は、1988年に映画化された"},{"k":"work","zh":"舞劇《絲路花雨》以莫高窟壁畫為靈感，招牌畫面是「反彈琵琶」","en":"The dance drama Tales of the Silk Road draws on Mogao cave murals; its signature pose is playing the pipa behind the back.","ja":"舞踊劇『絲路花雨』は莫高窟の壁画が題材で、背中で琵琶を弾く姿が見どころ"},{"k":"record","zh":"1909 年建成的中山橋，是黃河上最早的永久性公路橋","en":"Zhongshan Bridge, completed in 1909, was the earliest permanent road bridge on the Yellow River.","ja":"1909年完成の中山橋は、黄河で最も早い恒久的な道路橋"},{"k":"record","zh":"夏河的拉卜楞寺，是藏傳佛教格魯派六大寺之一","en":"Labrang Monastery in Xiahe is one of the six great monasteries of the Gelug school of Tibetan Buddhism.","ja":"夏河のラプラン寺は、チベット仏教ゲルク派の六大寺院の一つ"},{"k":"life","zh":"定西被命名為「中國馬鈴薯之鄉」，產的馬鈴薯澱粉含量高、耐儲存","en":"Dingxi is officially 'China's Hometown of Potatoes', known for high-starch spuds that store well.","ja":"定西は「中国ジャガイモの里」と命名され、でんぷん質が多く日持ちするイモで有名"},{"k":"life","zh":"岷縣是「中國當歸之鄉」，渭源縣是「中國黨參之鄉」","en":"Min County is 'China's Hometown of Angelica (danggui)', and Weiyuan County the hometown of codonopsis.","ja":"岷県は「中国当帰の里」、渭源県は「中国党参の里」と呼ばれる"},{"k":"origin","zh":"簡稱「隴」，來自省境東邊的隴山（六盤山）","en":"Its abbreviation 'Long' refers to Mount Liupan (Longshan) on its eastern edge.","ja":"略称「隴」は、東部の隴山（六盤山）に由来する"},{"k":"history","zh":"秦安大地灣遺址有一座約290平方公尺的史前大房子，被認為是議事大廳","en":"Dadiwan in Qin'an has a prehistoric 290 m² building thought to be a communal meeting hall.","ja":"秦安の大地湾遺跡には、集会所とされる約290㎡の先史時代の大型建物がある"},{"k":"record","zh":"大地灣的狗骨顯示牠們全年吃小米，是東亞最早的農業證據之一","en":"Dog bones at Dadiwan show they ate millet year-round, among East Asia's earliest evidence of farming.","ja":"大地湾の犬の骨から一年中アワを食べていたとわかり、東アジア最古級の農耕の証拠とされる"},{"k":"record","zh":"中國最古老的青銅器，是東鄉出土的馬家窯文化青銅刀","en":"China's oldest bronze object is a Majiayao-culture knife found in Dongxiang, dated 2900-2740 BC.","ja":"中国最古の青銅器は、東郷で出土した馬家窯文化の青銅の刀"},{"k":"history","zh":"1900年道士王圓籙順著菸霧的飄動，發現了封存的藏經洞","en":"In 1900 Taoist Wang Yuanlu found the sealed Library Cave by following the drift of cigarette smoke.","ja":"1900年、道士の王円籙はたばこの煙の流れをたどり、封印された蔵経洞を見つけた"},{"k":"record","zh":"藏經洞出土的868年《金剛經》，是世界最早有明確紀年的印刷書","en":"The Diamond Sutra of 868 from the Library Cave is the earliest dated printed book.","ja":"蔵経洞から出た868年の『金剛般若経』は、年代の明らかな世界最古の印刷本"},{"k":"people","zh":"三國蜀漢大將姜維出身天水冀縣，原為魏臣，後來投降諸葛亮","en":"Shu Han general Jiang Wei came from Ji County, Tianshui, and joined Zhuge Liang after leaving Wei.","ja":"蜀漢の将軍・姜維は天水冀県の出身で、もとは魏の役人だったが諸葛亮に降った"},{"k":"brand","zh":"雜誌《讀者》1981年在省會創刊，原名《讀者文摘》，1993年改名","en":"The magazine Duzhe began in the capital in 1981 as 'Duzhe Wenzhai', renamed in 1993 over a Reader's Digest clash.","ja":"雑誌『読者』は1981年に省都で『読者文摘』として創刊し、1993年に改名した"},{"k":"history","zh":"秦國從天水一帶興起，「秦」這個名稱也被認為部分源自此地","en":"The state of Qin grew out of the Tianshui area, and the name Qin is thought to come partly from here.","ja":"秦は天水一帯から興り、「秦」の名もこの地に由来するとされる"},{"k":"record","zh":"2006年在玉門關附近發現約西元前8年的早期紙張","en":"Early paper dated to around 8 BC was found near the Yumen Pass in 2006.","ja":"2006年、玉門関の近くで紀元前8年ごろの初期の紙が見つかった"},{"k":"history","zh":"西元前121年霍去病擊退匈奴後，漢朝在此設武威、張掖、酒泉、敦煌四郡","en":"After Huo Qubing drove out the Xiongnu in 121 BC, the Han set up the four Hexi commanderies here.","ja":"紀元前121年に霍去病が匈奴を退けた後、漢は武威・張掖・酒泉・敦煌の河西四郡を置いた"},{"k":"life","zh":"黃河邊的炳靈寺石窟約420年開鑿，至今只能在夏秋搭船前往","en":"Bingling Temple's grottoes, begun around 420, can still be reached only by boat in summer and fall.","ja":"炳霊寺石窟は420年ごろに開かれ、今も夏と秋に船でしか行けない"},{"k":"record","zh":"武威的西夏碑刻於1094年，是唯一西夏文、漢文並存的西夏石碑","en":"Wuwei's Western Xia Stele of 1094 is the only known Xia stele with both Tangut and Chinese text.","ja":"武威の西夏碑（1094年）は、西夏文字と漢文が併記された唯一の西夏の石碑"},{"k":"record","zh":"張掖大佛寺的臥佛長34.5公尺，是中國現存最大的室內臥佛","en":"The reclining Buddha in Zhangye's Great Buddha Temple, 34.5 m long, is China's largest indoors.","ja":"張掖大仏寺の涅槃仏は全長34.5mで、中国最大の屋内の涅槃仏"},{"k":"work","zh":"王之渙《涼州詞》「羌笛何須怨楊柳，春風不度玉門關」寫的就是這一帶","en":"Wang Zhihuan's 'Liangzhou Ci', about the spring wind never passing Yumen Pass, is set here.","ja":"王之渙の「涼州詞」の「春風度らず玉門関」はこの地を詠んだ"},{"k":"legend","zh":"平涼的崆峒山是道教名山，傳說黃帝曾在此向廣成子問道","en":"Kongtong Mountain in Pingliang is where the Yellow Emperor is said to have met Guangchengzi to ask about the Dao.","ja":"平涼の崆峒山は道教の名山で、黄帝が広成子に道を問うた地と伝わる"},{"k":"people","zh":"平涼人皇甫謐編成《針灸甲乙經》，是最早的系統性針灸專著之一","en":"Huangfu Mi of Pingliang compiled one of the earliest systematic works on acupuncture.","ja":"平涼出身の皇甫謐は、最古級の体系的な鍼灸書『鍼灸甲乙経』を編んだ"},{"k":"life","zh":"黃河上的羊皮筏子曾是省會唯一的水上交通工具，只能順流而下","en":"Rafts of inflated skins were once the capital's only way to travel the Yellow River, and only downstream.","ja":"羊の皮のいかだはかつて省都で黄河を行き来する唯一の手段で、下流にしか進めなかった"},{"k":"history","zh":"1936年10月紅軍在會寧會師，宣告長征結束","en":"In October 1936 the Red Army met at Huining to celebrate the end of the Long March.","ja":"1936年10月、紅軍は会寧で合流し長征の終わりを祝った"},{"k":"work","zh":"王維「西出陽關無故人」的陽關，位於敦煌西南約70公里","en":"Yang Pass of Wang Wei's 'west of Yang Pass no old friends' lies about 70 km southwest of Dunhuang.","ja":"王維の「西のかた陽関を出づれば故人無からん」の陽関は、敦煌の南西約70km"},{"k":"life","zh":"臨夏有八十多座清真寺，被稱為「中國的小麥加」","en":"Linxia, with over 80 mosques, is known as 'China's Little Mecca'.","ja":"臨夏には80以上のモスクがあり、「中国の小メッカ」と呼ばれる"},{"k":"record","zh":"齊家文化出土了中國最早的一批青銅鏡與銅鏡","en":"The Qijia culture produced some of the earliest bronze and copper mirrors found in China.","ja":"斉家文化からは中国最古級の青銅鏡・銅鏡が出土している"},{"k":"legend","zh":"傳說霍去病把御酒倒進泉裡與將士共飲，酒泉因此得名","en":"Legend says Huo Qubing poured the emperor's wine into a spring to share with his troops, naming Jiuquan.","ja":"霍去病が御酒を泉に注いで兵士と分かち合ったことから、酒泉の名がついたと伝わる"},{"k":"record","zh":"全國九成以上的鎳礦儲量都集中在這裡","en":"It holds over 90% of China's nickel reserves, the country's largest deposits.","ja":"中国のニッケル埋蔵量の9割以上がここに集中している"}],
"CN-GX":[{"k":"origin","zh":"宋代把「廣南路」拆成東、西兩路，這裡就是西邊那一路","en":"The Song dynasty split the Guangnan circuit into east and west; this region grew out of the western half.","ja":"宋代に広南路が東西に分けられ、その西側がこの地の名の由来"},{"k":"work","zh":"1960 年的電影《劉三姐》講壯族傳說中的歌仙，在漓江沿岸取景","en":"The 1960 film Third Sister Liu, about a legendary Zhuang folk singer, was shot along the Li River.","ja":"1960年の映画『劉三姐』はチワン族伝説の歌仙の物語で、漓江沿いで撮影された"},{"k":"life","zh":"人民幣 20 元鈔票背面的山水，畫的是陽朔的桂林山水","en":"The landscape on the back of the 20-yuan banknote shows Guilin scenery at Yangshuo here.","ja":"人民元20元札の裏の山水は、ここの陽朔の桂林山水"},{"k":"people","zh":"作家白先勇出生在桂林，父親是將領白崇禧","en":"Writer Pai Hsien-yung was born in Guilin; his father was the general Bai Chongxi.","ja":"作家・白先勇は桂林の生まれで、父は将軍の白崇禧"},{"k":"festival","zh":"住在東興「京族三島」的京族，每年舉行以唱歌為主的「哈節」","en":"The Gin people of Dongxing's 'Three Gin Islands' hold the Ha Festival, a festival of folk songs.","ja":"東興の「京族三島」に暮らすキン族は、歌を中心とした「哈節」を祝う"},{"k":"symbol","zh":"桂林的市花是桂花，市樹是榕樹和桂樹","en":"Guilin's city flower is the osmanthus; its city trees are the banyan and the osmanthus tree.","ja":"桂林の市の花はキンモクセイ、市の木はガジュマルとモクセイ"},{"k":"life","zh":"羅漢果的三大產地永福、融安、臨桂都在這裡，佔全球產量九成","en":"Yongfu, Rong'an and Lingui here grow about 90% of the world's monk fruit (luo han guo).","ja":"羅漢果の三大産地、永福・融安・臨桂はすべてここにあり、世界の生産量の9割を占める"},{"k":"life","zh":"中國最暢銷的電動車「宏光 MINI EV」，由柳州的上汽通用五菱生產","en":"China's best-selling electric car, the Wuling Hongguang Mini EV, is built by SGMW in Liuzhou.","ja":"中国で最も売れたEV「宏光MINI EV」は、柳州の上汽通用五菱が生産している"},{"k":"history","zh":"1851 年 1 月 11 日洪秀全生日當天，在桂平金田村起事，宣告太平天國","en":"On 11 January 1851, Hong Xiuquan's birthday, the Taiping Rebellion began at Jintian village here.","ja":"1851年1月11日、洪秀全の誕生日に金田村で蜂起し、太平天国の建国が宣言された"},{"k":"history","zh":"1885 年中法戰爭的鎮南關之役，清軍在邊境關口擊退法軍","en":"At Zhennan Pass on the border in March 1885, Chinese forces repulsed the French in the Sino-French War.","ja":"1885年3月、清仏戦争の鎮南関の戦いで清軍が国境の関でフランス軍を撃退した"},{"k":"history","zh":"1939 年底的崑崙關戰役，國軍唯一的戰車部隊參戰，日軍少將中村正雄戰死","en":"In the 1939–40 Battle of Kunlun Pass, China's only tank-equipped corps fought and Japan's Maj. Gen. Nakamura was killed.","ja":"1939〜40年の崑崙関の戦いで中国軍唯一の戦車部隊が戦い、日本の中村正雄少将が戦死した"},{"k":"record","zh":"北部灣的潿洲島被稱為中國最年輕的火山島","en":"Weizhou Island in the Beibu Gulf is called China's youngest volcanic island.","ja":"北部湾の潿洲島は「中国で最も若い火山島」と呼ばれる"},{"k":"symbol","zh":"極度瀕危的白頭葉猴，全世界只住在這裡的石灰岩山區","en":"The critically endangered white-headed langur lives only on karst hills here, nowhere else on Earth.","ja":"絶滅寸前のシロガシラリーフモンキー（白頭葉猴）は、世界でここの石灰岩の丘にしかいない"},{"k":"symbol","zh":"開黃花的「金花茶」是罕見的黃色山茶，在中國只產於這裡，防城設有保護區","en":"The golden camellia, a rare yellow-flowered camellia, is endemic in China only here, with a reserve at Fangcheng.","ja":"黄色い花の珍しいツバキ「金花茶」は中国ではここにだけ自生し、防城に保護区がある"},{"k":"legend","zh":"比喻失物復得的成語「合浦珠還」，典故出自這裡合浦的珍珠","en":"The idiom 'pearls return to Hepu', meaning lost things coming back, comes from the pearls of Hepu here.","ja":"失ったものが戻る意の成語「合浦珠還」は、ここ合浦の真珠の故事に由来する"},{"k":"record","zh":"合浦在 1958 年建立了中國第一個海水珍珠人工養殖基地","en":"Hepu set up China's first marine pearl farming base in 1958.","ja":"合浦には1958年、中国初の海水真珠の養殖基地がつくられた"},{"k":"sport","zh":"「體操王子」李寧生於柳州，1984 年奧運拿下 3 金，後來創立運動品牌","en":"'Prince of Gymnastics' Li Ning, born in Liuzhou, won three golds at the 1984 Olympics, then founded his own brand.","ja":"「体操の王子」李寧は柳州生まれ。1984年五輪で金3個を獲り、のちにスポーツブランドを創業"},{"k":"people","zh":"台兒莊大捷的指揮官、1949 年任代理總統的李宗仁，出生在桂林附近","en":"Li Zongren, victor of Tai'erzhuang and acting ROC president in 1949, was born near Guilin.","ja":"台児荘の戦いを指揮し、1949年に中華民国の代理総統となった李宗仁は桂林近郊の生まれ"},{"k":"work","zh":"張藝謀 2004 年推出的實景演出，以約 2 公里的漓江水面為舞台、12 座山峰為背景","en":"Zhang Yimou's open-air show, launched in 2004, uses 2 km of the Li River as its stage and 12 peaks as backdrop.","ja":"張芸謀演出の野外ショーは2004年に始まり、漓江の水面約2kmを舞台に12の峰を背景とする"},{"k":"legend","zh":"壯族的創世始祖「布洛陀」，壯語意思是「知道很多事的老公公」","en":"Baeuqloegdoz, the Zhuang creator-ancestor, has a name meaning 'the old man who knows a lot'.","ja":"チワン族の創世神「布洛陀」は、チワン語で「物知りのおじいさん」という意味"},{"k":"life","zh":"三江的程陽風雨橋長 64.4 公尺，是集橋、廊、亭於一身的侗族木造廊橋","en":"Chengyang Bridge in Sanjiang, 64.4 m long, is a Dong wooden covered bridge with corridors and pavilions.","ja":"三江の程陽風雨橋は全長64.4m、橋・回廊・あずまやを兼ねたトン族の木造屋根付き橋"},{"k":"record","zh":"全球約八成五的八角產自這裡，八角也是克流感的原料","en":"About 85% of the world's star anise grows here; it is a key ingredient of the flu drug Tamiflu.","ja":"世界の八角の約85%がここで栽培され、八角はタミフルの原料になる"},{"k":"history","zh":"1952 年從鄰省劃入一段海岸，從此成為唯一有出海口的自治區","en":"Coast transferred from a neighbor in 1952 made it China's only autonomous region with a sea coast.","ja":"1952年に隣の省から海岸の一部が移され、中国で唯一海に面した自治区となった"},{"k":"history","zh":"1856 年法國神父馬賴在西林縣被處死，法國以此為由加入第二次鴉片戰爭","en":"The 1856 execution of French priest Auguste Chapdelaine in Xilin County gave France a pretext for the Second Opium War.","ja":"1856年、西林県で仏人神父シャプドレーヌが処刑され、フランスの第二次アヘン戦争参戦の口実となった"},{"k":"history","zh":"壯族首領儂智高 1052 年起兵反宋，建立「大南國」並自稱皇帝","en":"Zhuang chieftain Nong Zhigao rose against the Song in 1052, founding the 'Great South' kingdom as its emperor.","ja":"チワン族の首長儂智高は1052年に宋に反旗を翻し、「大南国」を建てて皇帝を名乗った"},{"k":"history","zh":"1929 年鄧小平參與領導百色起義，這場共產黨起事最後失敗","en":"In 1929 Deng Xiaoping helped lead the Baise Uprising here, a failed Communist revolt.","ja":"1929年、鄧小平は百色蜂起の指導に加わったが、この共産党の蜂起は失敗した"},{"k":"nature","zh":"2022 年探險隊在樂業縣發現一個巨大天坑，裡面藏著一片森林","en":"In 2022 cavers found a giant sinkhole in Leye County with a hidden forest inside.","ja":"2022年、楽業県で中に森を隠した巨大な天坑（陥没穴）が見つかった"},{"k":"nature","zh":"最高峰是越城嶺的貓兒山，海拔 2141 公尺","en":"The highest point is Mao'er ('Kitten') Mountain in the Yuecheng range, 2,141 m tall.","ja":"最高峰は越城嶺の猫児山で、標高2141m"},{"k":"food","zh":"三月三與清明，壯族人用植物汁把糯米染成黑紅黃紫白五色再蒸","en":"For Sanyuesan and Qingming, Zhuang families dye glutinous rice five colors with plant juices and steam it.","ja":"三月三や清明節に、チワン族は植物の汁でもち米を黒・赤・黄・紫・白に染めて蒸す"},{"k":"people","zh":"唐代文豪柳宗元晚年任柳州刺史，819 年死在任上，當地有紀念他的公園與祠廟","en":"Tang writer Liu Zongyuan governed Liuzhou in exile and died there in 819; a park and temple honor him.","ja":"唐の文人柳宗元は柳州の長官を務め819年に同地で没した。記念の公園と廟がある"},{"k":"people","zh":"黑旗軍首領劉永福生於欽州，1895 年在臺灣抗日，臺南的永福路以他命名","en":"Black Flag Army chief Liu Yongfu was born in Qinzhou; Tainan's Yongfu Road honors his 1895 stand against Japan.","ja":"黒旗軍の劉永福は欽州生まれ。1895年に台湾で日本に抵抗し、台南の永福路は彼にちなむ"}],
"CN-GZ":[{"k":"origin","zh":"唐代這裡叫「矩州」，元代把「矩」換成更雅的字，成了今天的名字","en":"In the Tang it was Juzhou; the Yuan swapped 'ju' (carpenter's square) for a more refined character.","ja":"唐代は「矩州」と呼ばれ、元代に「矩」をより雅な字に替えて今の名になった"},{"k":"people","zh":"「宮保雞丁」的宮保指清朝官員丁寶楨，他的故鄉在這裡的織金","en":"The 'Kung Pao' in Kung Pao chicken refers to Qing official Ding Baozhen, a native of Zhijin here.","ja":"宮保鶏丁の「宮保」は清の官僚・丁宝楨のこと。彼の故郷はここの織金"},{"k":"sport","zh":"榕江的鄉村足球聯賽「村超」2023 年在網路爆紅，獎品是當地農產品","en":"Rongjiang's village football league, the 'Village Super League', went viral in 2023; prizes are local farm goods.","ja":"榕江の村サッカーリーグ「村超」は2023年にネットで大人気に。賞品は地元の農産物"},{"k":"festival","zh":"台江的苗族在農曆三月中過「姊妹節」，吃染成五顏六色的「姊妹飯」","en":"The Miao of Taijiang celebrate the Sisters' Festival in the third lunar month, eating rainbow-dyed 'sisters' rice'.","ja":"台江のミャオ族は旧暦3月に「姉妹節」を祝い、色とりどりの「姉妹飯」を食べる"},{"k":"work","zh":"導演畢贛生於凱里，《路邊野餐》《地球最後的夜晚》都以本省為背景","en":"Director Bi Gan, born in Kaili, set both Kaili Blues and Long Day's Journey into Night in this province.","ja":"畢贛監督は凱里生まれ。『凱里ブルース』『ロングデイズ・ジャーニー』の舞台はこの省"},{"k":"record","zh":"2025 年通車的花江峽谷大橋，橋面離江面 625 公尺，成為世界最高的橋","en":"Huajiang Grand Canyon Bridge, opened in 2025 with its deck 625 m above the river, is the world's highest bridge.","ja":"2025年開通の花江峡谷大橋は水面から橋面まで625mで、世界一高い橋"},{"k":"record","zh":"中國第一個國家級大數據綜合試驗區設在這裡","en":"It became China's first national-level comprehensive pilot zone for big data.","ja":"中国初の国家級ビッグデータ総合試験区がここに置かれた"},{"k":"life","zh":"安順一帶的「屯堡人」是明代屯兵的後代，至今保留戴面具演的「地戲」","en":"The Tunpu people around Anshun descend from Ming garrison soldiers and still perform masked 'Dixi' opera.","ja":"安順一帯の「屯堡人」は明代の屯田兵の子孫で、仮面劇「地戯」を今も伝える"},{"k":"people","zh":"1945年在南京主持中國戰區日軍受降的何應欽，生於興義","en":"He Yingqin, who accepted Japan's surrender in China at Nanjing in 1945, was born in Xingyi here.","ja":"1945年に南京で日本軍の降伏を受けた何応欽は、興義の生まれ"},{"k":"people","zh":"倡導「中學為體，西學為用」的晚清重臣張之洞，生於興義府","en":"Late-Qing statesman Zhang Zhidong, champion of 'Chinese learning as the base', was born in Xingyi.","ja":"「中体西用」を唱えた清末の重臣・張之洞は、興義府で生まれた"},{"k":"history","zh":"抗戰時浙江大學西遷遵義、湄潭，被李約瑟譽為「東方劍橋」","en":"Zhejiang University moved to Zunyi and Meitan in wartime; Joseph Needham called it 'the Cambridge of the East'.","ja":"抗日戦争中、浙江大学は遵義・湄潭に移り、ニーダムに「東洋のケンブリッジ」と称えられた"},{"k":"legend","zh":"傳說夜郎國始祖是從漂來的大竹中剖出的男嬰，後稱「竹王」","en":"Legend says Yelang's first ruler was a baby found inside a floating bamboo, later called the Bamboo King.","ja":"夜郎国の始祖は流れてきた大竹の中から見つかった男の子で、「竹王」と呼ばれたと伝わる"},{"k":"people","zh":"明初彝族女土司奢香入京面見朱元璋，回鄉開闢「龍場九驛」","en":"Yi chieftess She Xiang met the Hongwu Emperor in 1384, then built nine relay stations from Longchang.","ja":"彝族の女性土司・奢香は1384年に洪武帝に謁見し、帰郷後「龍場九駅」を開いた"},{"k":"history","zh":"1935年紅軍四度渡過赤水河突圍，毛澤東稱這是他的「得意之筆」","en":"In 1935 the Red Army crossed the Chishui River four times to escape; Mao called it his finest move.","ja":"1935年、紅軍は赤水河を4度渡って包囲を脱し、毛沢東は自らの「会心の作」と呼んだ"},{"k":"record","zh":"綏陽的雙河洞是亞洲最長的洞穴，也是世界最長的白雲岩洞穴","en":"Shuanghe Cave in Suiyang is the longest cave in Asia and the world's longest dolomite cave.","ja":"綏陽の双河洞はアジア最長の洞窟で、世界最長のドロマイト洞窟でもある"},{"k":"record","zh":"大方縣的百里杜鵑，擁有世界最大的原始杜鵑林帶","en":"Baili Dujuan in Dafang has the world's largest belt of wild rhododendron forest.","ja":"大方県の百里杜鵑には世界最大の天然ツツジ林が広がる"},{"k":"brand","zh":"辣椒醬「老乾媽」源自陶華碧在省會開的麵館，後來改專賣辣醬","en":"Lao Gan Ma chili sauce began at Tao Huabi's noodle shop in the provincial capital.","ja":"ラー油「老干媽」は、陶華碧が省都で開いた麺屋から生まれた"},{"k":"life","zh":"三都一帶水族的古文字「水書」約有1400字，只有少數巫師看得懂","en":"The Shui script of the Shui people around Sandu has about 1,400 characters, read only by a few shamans.","ja":"三都一帯の水族の古文字「水書」は約1400字あり、読めるのは一部の祭司だけ"},{"k":"festival","zh":"全國唯一的水族自治縣三都，水族新年「端節」在亥日過，還要賽馬","en":"In Sandu, China's only Shui autonomous county, the Shui New Year 'Duan Festival' features horse racing.","ja":"中国唯一の水族自治県・三都では、水族の正月「端節」に競馬が行われる"},{"k":"history","zh":"明朝永樂年間的1413年，這裡才正式建省","en":"This area only became a province in 1413, under the Ming dynasty.","ja":"ここが正式に省となったのは明代の1413年"},{"k":"history","zh":"遵義的海龍屯是播州土司楊應龍的山城，1600年被明軍攻破","en":"Hailongtun in Zunyi, mountain fortress of Bozhou chief Yang Yinglong, fell to Ming forces in 1600.","ja":"遵義の海龍屯は播州の土司・楊応龍の山城で、1600年に明軍に攻め落とされた"},{"k":"symbol","zh":"赤水有四萬多株桫欏，保護區被稱為「中國侏羅紀公園」","en":"Chishui's reserve holds over 40,000 tree ferns and is nicknamed 'China's Jurassic Park'.","ja":"赤水には4万株以上のヘゴ（桫欏）が茂り、「中国のジュラシックパーク」と呼ばれる"},{"k":"people","zh":"東漢的尹珍遠赴洛陽拜許慎為師，學成後回鄉設館教學","en":"Eastern Han scholar Yin Zhen studied under Xu Shen in Luoyang, then returned home to teach.","ja":"後漢の尹珍は洛陽で許慎に学び、故郷に戻って学問を広めた"},{"k":"nature","zh":"1980年才被發現的織金洞，屬於世界地質公園","en":"Zhijin Cave, discovered only in 1980, is the centerpiece of a UNESCO Global Geopark.","ja":"1980年に発見された織金洞は世界ジオパークに認定されている"},{"k":"origin","zh":"簡稱「黔」，源自唐代此地屬於黔中道","en":"Its one-character abbreviation 'Qian' comes from the Tang-era Qianzhong Circuit.","ja":"略称「黔」は、唐代にこの地が黔中道に属したことに由来する"},{"k":"sport","zh":"台江台盤村的「村BA」籃球賽源於吃新節，2022年在網路爆紅","en":"The 'Village BA' basketball games of Taipan village, Taijiang, went viral online in 2022.","ja":"台江県台盤村の村のバスケ大会「村BA」は、2022年にネットで大人気となった"},{"k":"record","zh":"妥樂村是世界古銀杏生長密度最高、保存最完好的地方","en":"Tuole village is said to have the world's densest and best-preserved stand of ancient ginkgo trees.","ja":"妥楽村は古いイチョウの密度が世界一高く、最もよく保存された場所とされる"},{"k":"nature","zh":"全省最高點是赫章縣的韭菜坪，海拔2900.6公尺","en":"The highest point is Jiucaiping in Hezhang County, at 2,900.6 m.","ja":"最高地点は赫章県の韮菜坪で、標高2900.6m"},{"k":"life","zh":"省會夏天涼爽，有「中國避暑之都」的美譽","en":"Its cool summers earned the provincial capital the title 'China's summer resort capital'.","ja":"夏が涼しい省都は「中国の避暑の都」と呼ばれる"},{"k":"record","zh":"西部地區第一個實現每個縣都通高速公路的省份","en":"It was the first province in western China to link every county by expressway.","ja":"中国西部で初めて全ての県に高速道路が通じた省"},{"k":"life","zh":"黃平、安順的苗族彩色蠟染，是代代相傳的民間藝術","en":"Colorful Miao batik from Huangping and Anshun is a traditional folk craft here.","ja":"黄平や安順のミャオ族の色鮮やかなろうけつ染めは伝統の民芸"}],
"CN-HA":[{"k":"origin","zh":"簡稱取自上古九州正中央的「○州」，含有安逸的意思","en":"Its abbreviation comes from the ancient province at the very center of the Nine Provinces, meaning 'at ease'.","ja":"略称は古代九州の中央にあった「○州」に由来し、安らかという意味を含む"},{"k":"people","zh":"詩聖杜甫的籍貫是鞏縣，就是今天的鞏義","en":"Du Fu, the 'Poet Sage', had his family home in Gong County, today's Gongyi.","ja":"詩聖・杜甫の本籍は鞏県、今の鞏義"},{"k":"people","zh":"發明候風地動儀的東漢科學家張衡，出生在南陽","en":"Eastern Han scientist Zhang Heng, inventor of the first seismoscope, was born in Nanyang here.","ja":"地動儀を発明した後漢の科学者・張衡は、南陽の生まれ"},{"k":"work","zh":"張擇端名畫《清明上河圖》描繪的，是北宋都城汴京（今開封）","en":"Zhang Zeduan's scroll Along the River During the Qingming Festival depicts the Northern Song capital, today's Kaifeng.","ja":"張択端の名画『清明上河図』は、北宋の都・汴京（今の開封）を描いたもの"},{"k":"festival","zh":"洛陽牡丹花會從 1983 年起每年四月舉辦，2011 年升格為牡丹文化節","en":"Luoyang's Peony Fair has been held every April since 1983 and became a national culture festival in 2011.","ja":"洛陽牡丹花会は1983年から毎年4月に開かれ、2011年に牡丹文化節へ格上げされた"},{"k":"record","zh":"東漢 68 年建的白馬寺，被視為中國佛教的發源地，人稱「釋源」","en":"White Horse Temple, built in AD 68, is regarded as the birthplace of Chinese Buddhism.","ja":"68年創建の白馬寺は中国仏教の発祥地とされ、「釈源」と呼ばれる"},{"k":"life","zh":"省會的富士康園區是全球最大的手機生產基地，被稱為「iPhone 城」","en":"The capital's Foxconn complex is the world's largest smartphone production site, dubbed 'iPhone City'.","ja":"省都のフォックスコン工場は世界最大のスマホ生産拠点で、「iPhoneシティ」と呼ばれる"},{"k":"record","zh":"五嶽中的「中嶽」嵩山就在這裡","en":"Mount Song, the 'Central Peak' of China's Five Great Mountains, is here.","ja":"五岳のうち「中岳」の嵩山がここにある"},{"k":"people","zh":"《西遊記》唐三藏的原型玄奘，602 年生於洛陽附近的緱氏","en":"Xuanzang, the model for Tang Sanzang in Journey to the West, was born near Luoyang in 602.","ja":"『西遊記』三蔵法師のモデル玄奘は、602年に洛陽近郊の緱氏で生まれた。"},{"k":"people","zh":"唐宋八大家之首韓愈，出生在今天的孟州","en":"Han Yu, ranked first of the Eight Great Prose Masters of Tang and Song, was born in today's Mengzhou here.","ja":"唐宋八大家の筆頭・韓愈は、今の孟州の生まれ。"},{"k":"people","zh":"畫聖吳道子出身陽翟，就是今天的禹州","en":"Wu Daozi, revered as the Sage of Painting, came from Yangdi, today's Yuzhou here.","ja":"「画聖」呉道子は陽翟、今の禹州の出身。"},{"k":"people","zh":"寫下「春蠶到死絲方盡」的晚唐詩人李商隱，是這裡人","en":"Late Tang poet Li Shangyin, master of elusive love poems, came from this province.","ja":"「春蚕死に到りて糸方に尽く」を詠んだ晩唐の詩人・李商隠は○○の人。"},{"k":"work","zh":"包青天故事裡斷案的開封府就在這裡，包拯 1057 年起擔任開封知府","en":"Justice Bao's famous court sat in Kaifeng here; Bao Zheng became its prefect in 1057.","ja":"包青天の物語の舞台・開封府はここにあり、包拯は1057年に開封の知府となった。"},{"k":"festival","zh":"寶豐縣每年農曆正月十三的「馬街書會」，各地說書藝人聚集說唱","en":"Every 13th of the first lunar month, storytellers gather at Majie in Baofeng County for a folk-art fair.","ja":"宝豊県で毎年旧暦1月13日に開く「馬街書会」には、各地の語り芸人が集まる。"},{"k":"festival","zh":"淮陽太昊陵祭祀伏羲，二月二到三月三的廟會曾單日湧入 82 萬人次","en":"Huaiyang's temple fair for Fuxi runs about a month in spring; one day in 2008 drew over 820,000 visits.","ja":"淮陽の太昊陵は伏羲を祀り、春の廟会には2008年に1日82万人が訪れた。"},{"k":"festival","zh":"開封的市花是菊花，每年秋天舉辦菊花文化節","en":"Kaifeng's city flower is the chrysanthemum, celebrated each autumn with a chrysanthemum festival.","ja":"開封の市花は菊で、毎年秋に菊花文化祭が開かれる。"},{"k":"origin","zh":"洛陽因位於洛水北岸而得名，古人稱河的北岸為「陽」","en":"Luoyang is named for lying north of the Luo River, as a river's north bank was called 'yang'.","ja":"洛陽の名は洛水の北岸にあることから。川の北岸を「陽」と呼んだ。"},{"k":"record","zh":"舞陽賈湖遺址出土約九千年前、用丹頂鶴翅骨做的骨笛，是世界最古老可吹奏的樂器之一","en":"Jiahu yielded ~9,000-year-old flutes of red-crowned crane bone, among the oldest playable instruments.","ja":"舞陽の賈湖遺跡からタンチョウの骨で作った約9千年前の笛が出土し、世界最古級の楽器とされる。"},{"k":"record","zh":"523 年建的嵩嶽寺塔是中國最早的磚塔，平面是罕見的十二邊形","en":"The Songyue Pagoda of 523 is China's earliest surviving brick pagoda, with a unique 12-sided plan.","ja":"523年建立の嵩岳寺塔は中国最古の磚塔で、珍しい十二角形をしている。"},{"k":"record","zh":"郭守敬參與設計、1276 年建的登封觀星台，量出一年長 365 天 5 時 49 分 20 秒","en":"Dengfeng's 1276 observatory, co-designed by Guo Shoujing, measured the year as 365 d 5 h 49 m 20 s.","ja":"郭守敬らが設計し1276年に建てた登封観星台は、1年を365日5時間49分20秒と測った。"},{"k":"record","zh":"北宋時，開封被認為在 1013～1127 年間是世界最大的城市","en":"As the Northern Song capital, Kaifeng is believed to have been the world's largest city from 1013 to 1127.","ja":"北宋の都・開封は、1013～1127年に世界最大の都市だったと考えられている。"},{"k":"life","zh":"這裡的方言說「好、可以」，常常只講一個字「中」","en":"In the local dialect, people say just 'zhong' to mean 'OK' or 'fine'.","ja":"ここの方言では「よし・いいよ」を一字「中」で表す。"},{"k":"life","zh":"開封曾有猶太人社群，1163 年就建了猶太會堂","en":"Kaifeng once had a Jewish community, whose synagogue was founded in 1163.","ja":"開封にはかつてユダヤ人社会があり、1163年にシナゴーグが建てられた。"},{"k":"life","zh":"輝縣郭亮村的村民，1970 年代徒手在太行山崖壁鑿出約 1.2 公里的掛壁隧道","en":"Villagers of Guoliang chiseled a 1.2-km tunnel road through a Taihang cliff face in the 1970s.","ja":"郭亮村の村人は1970年代、太行山の断崖に約1.2キロのトンネル道路を手で掘った。"},{"k":"history","zh":"200 年曹操以少勝多擊敗袁紹的官渡之戰，戰場在今中牟縣","en":"At Guandu in today's Zhongmu County, Cao Cao beat Yuan Shao's larger army in 200 AD.","ja":"200年、曹操が袁紹の大軍を破った官渡の戦いの戦場は、今の中牟県。"},{"k":"history","zh":"偃師二里頭遺址出土中國最早的青銅鼎，常被認為與夏朝有關","en":"Erlitou in Yanshi has China's earliest recovered bronze ding vessels and is often linked to the Xia dynasty.","ja":"偃師の二里頭遺跡は中国最古の青銅鼎が出土し、夏王朝と結びつけられることが多い。"},{"k":"history","zh":"1938 年國軍炸開花園口黃河大堤阻擋日軍，造成數十萬人死亡","en":"In 1938 Nationalist troops breached the Yellow River dike at Huayuankou to stop Japan, killing hundreds of thousands.","ja":"1938年、国民党軍は日本軍を阻むため花園口の黄河の堤防を壊し、数十万人が死んだ。"},{"k":"history","zh":"1127 年金軍攻破北宋都城開封、擄走徽欽二帝，史稱靖康之變","en":"In 1127 Jin forces took Kaifeng and seized two Song emperors: the Jingkang Incident.","ja":"1127年、金軍が北宋の都・開封を落とし二人の皇帝を連れ去った（靖康の変）。"},{"k":"history","zh":"2009 年在安陽發現的西高穴大墓，被認定為曹操的陵墓","en":"A tomb found at Xigaoxue near Anyang in 2009 was identified as the mausoleum of Cao Cao.","ja":"2009年に安陽の西高穴で見つかった大墓は、曹操の陵墓とされた。"},{"k":"brand","zh":"1958 年在漯河創立的肉品大廠雙匯，2013 年收購了美國豬肉大廠 Smithfield","en":"Shuanghui, founded in Luohe in 1958, bought the US pork giant Smithfield Foods in 2013.","ja":"1958年に漯河で創業した双匯は、2013年に米国の豚肉大手スミスフィールドを買収した。"},{"k":"legend","zh":"《列子》愚公移山故事裡的王屋山，就在今天的濟源市","en":"Mount Wangwu, one of the mountains in the fable of the Foolish Old Man, is in today's Jiyuan here.","ja":"『列子』の「愚公山を移す」に出てくる王屋山は、今の済源市にある。"}],
"CN-HB":[{"k":"people","zh":"出塞和親的王昭君，故里在興山縣","en":"Wang Zhaojun, the Han beauty married off to the Xiongnu, came from Xingshan County here.","ja":"匈奴に嫁いだ王昭君の故郷は、ここの興山県"},{"k":"sport","zh":"網球名將李娜在這裡出生，2011 年法網奪冠，成為首位亞洲出生的大滿貫單打冠軍","en":"Tennis star Li Na was born here; her 2011 French Open title made her the first Asian-born Grand Slam singles champion.","ja":"テニスの李娜はここの生まれ。2011年全仏で優勝し、アジア出身初の四大大会シングルス王者に"},{"k":"work","zh":"金庸《倚天屠龍記》裡張三丰開創武當派的武當山，就在這裡","en":"Wudang Mountain, where Zhang Sanfeng founds the Wudang school in Jin Yong's The Heaven Sword and Dragon Saber, is here.","ja":"金庸『倚天屠龍記』で張三豊が武当派を開いた武当山は、ここにある"},{"k":"festival","zh":"恩施土家族的「女兒會」，年輕人以對歌自由選擇對象","en":"At the Enshi Tujia 'Daughters' Fair', young people choose their partners through singing duets.","ja":"恩施のトゥチャ族の「女児会」では、若者が歌の掛け合いで相手を選ぶ"},{"k":"record","zh":"宜昌的葛洲壩，是長江幹流上第一座大型水利樞紐","en":"Gezhouba in Yichang was the first large water-control project on the main stream of the Yangtze.","ja":"宜昌の葛洲壩は、長江本流で初めての大型水利施設"},{"k":"life","zh":"神農架流傳「野人」傳說，1974 年以來有 360 多人說自己親眼見過","en":"Shennongjia has its own 'wild man' legend; over 360 people have claimed sightings since 1974.","ja":"神農架には「野人」伝説があり、1974年以来360人以上が目撃を証言している"},{"k":"record","zh":"1965 年在江陵出土的「越王勾踐劍」，兩千多年後依然鋒利無比","en":"The Sword of Goujian, unearthed at Jiangling in 1965, was still razor-sharp after more than 2,000 years.","ja":"1965年に江陵で出土した「越王勾践剣」は、2000年以上たっても鋭いままだった"},{"k":"people","zh":"寫下《茶經》、被尊為「茶聖」的陸羽，出生在天門","en":"Lu Yu, the 'Sage of Tea' who wrote The Classic of Tea, was born in Tianmen here.","ja":"『茶経』を著し「茶聖」と仰がれる陸羽は、○○の天門の生まれ。"},{"k":"people","zh":"發明膠泥活字印刷的北宋工匠畢昇，墓碑 1990 年在這裡被找到","en":"The gravestone of Bi Sheng, Song inventor of movable type, was found in this province in 1990.","ja":"活字印刷を発明した北宋の畢昇の墓碑は、1990年に○○で見つかった。"},{"k":"people","zh":"寫下「春眠不覺曉」的山水田園詩人孟浩然，是襄陽人","en":"Meng Haoran, the Tang poet of 'Spring Dawn', was a native of Xiangyang here.","ja":"「春眠暁を覚えず」の詩人・孟浩然は○○の襄陽の人。"},{"k":"people","zh":"推行「一條鞭法」改革的明朝首輔張居正，是江陵人","en":"Zhang Juzheng, the Ming grand secretary behind the Single Whip tax reform, was from Jiangling here.","ja":"一条鞭法を進めた明の首輔・張居正は○○の江陵の人。"},{"k":"people","zh":"李白在安陸娶了前宰相的孫女，在這裡住了將近十年","en":"Li Bai married a former chancellor's granddaughter in Anlu here and lived there for about ten years.","ja":"李白は○○の安陸で元宰相の孫娘と結婚し、約10年暮らした。"},{"k":"sport","zh":"跳水名將伏明霞生於省會，1991 年 12 歲就奪得世界冠軍","en":"Diver Fu Mingxia, born in the capital, became world champion at just 12 in 1991.","ja":"飛び込みの伏明霞は省都の生まれで、1991年にわずか12歳で世界王者になった。"},{"k":"work","zh":"金庸《神鵰俠侶》中郭靖、黃蓉死守對抗蒙古大軍的襄陽城，就在這裡","en":"Xiangyang, the city Guo Jing and Huang Rong defend against the Mongols in The Return of the Condor Heroes, is here.","ja":"金庸『神鵰剣俠』で郭靖と黄蓉がモンゴル軍から守り抜く襄陽城は、○○にある。"},{"k":"history","zh":"元軍圍攻襄陽、樊城長達五年，最後動用西域工匠造的回回砲才攻破","en":"The Mongols besieged Xiangyang and Fancheng for about five years, finally breaking them with counterweight trebuchets.","ja":"元軍は襄陽・樊城を約5年包囲し、西域の技術者が造った回回砲でついに攻め落とした。"},{"k":"origin","zh":"省會是 1927 年由武昌、漢口、漢陽三鎮合併而成","en":"The capital was formed in 1927 by merging three towns: Wuchang, Hankou and Hanyang.","ja":"省都は1927年に武昌・漢口・漢陽の三鎮が合併してできた。"},{"k":"life","zh":"省會位居交通要衝，自古被稱為「九省通衢」","en":"The capital is a transport hub long nicknamed the 'Thoroughfare of Nine Provinces'.","ja":"省都は交通の要衝で、昔から「九省通衢」と呼ばれる。"},{"k":"origin","zh":"神農架的「架」是梯子，相傳神農氏在此搭藤梯上山採藥","en":"Shennongjia means 'Shennong's ladder', after the legend that he climbed here on a rattan ladder.","ja":"神農架の「架」ははしごのことで、神農が藤のはしごで山に登ったという伝説による。"},{"k":"symbol","zh":"被認為早已滅絕的「活化石」水杉，1940 年代在利川重新被發現","en":"The dawn redwood, a 'living fossil' thought extinct, was rediscovered in Lichuan here in the 1940s.","ja":"絶滅したと思われていた「生きた化石」メタセコイアは、1940年代に利川で再発見された。"},{"k":"record","zh":"1993 年荊門郭店出土的楚簡，是現存最早的《道德經》抄本","en":"Bamboo slips found at Guodian, Jingmen, in 1993 are the earliest manuscripts of the Tao Te Ching.","ja":"1993年に荊門の郭店で出土した楚簡は、現存最古の『老子』の写本だ。"},{"k":"record","zh":"1975 年雲夢睡虎地出土上千枚秦簡，記載了秦朝的法律條文","en":"Over 1,000 Qin bamboo slips recording Qin laws were unearthed at Shuihudi, Yunmeng, in 1975.","ja":"1975年に雲夢の睡虎地で秦の法律を記した千枚以上の竹簡が出土した。"},{"k":"history","zh":"張之洞在漢陽設立兵工廠，所造步槍被稱為「漢陽造」","en":"Zhang Zhidong founded the Hanyang Arsenal here, whose rifles were famous as 'Hanyang-made'.","ja":"張之洞が漢陽に兵器工場を設け、そこで造られた小銃は「漢陽造」と呼ばれた。"},{"k":"brand","zh":"東風汽車的前身「第二汽車製造廠」1969 年在十堰創立，當時那裡只是個百人小村","en":"Dongfeng Motor began in 1969 as the Second Automobile Works in a tiny village that became Shiyan.","ja":"東風汽車の前身「第二汽車製造廠」は1969年、人口百人ほどの村（今の十堰）で創立された。"},{"k":"food","zh":"省會早餐名物「三鮮豆皮」，是 1931 年老通城的廚師改良出的","en":"The capital's breakfast favorite sanxian doupi was refined in 1931 by a chef of Laotongcheng.","ja":"省都の朝食名物「三鮮豆皮」は、1931年に老通城の料理人が改良したもの。"},{"k":"record","zh":"以小龍蝦聞名的潛江，有金氏世界紀錄最大的甲殼類雕塑","en":"Qianjiang, famed for crayfish, holds the Guinness record for the largest crustacean sculpture.","ja":"ザリガニで有名な潜江には、ギネス認定の世界最大の甲殻類の彫刻がある。"},{"k":"history","zh":"222 年夷陵之戰，陸遜火燒連營大敗劉備，地點在今宜昌一帶","en":"At Yiling near today's Yichang in 222, Lu Xun burned Liu Bei's camps and routed his army.","ja":"222年の夷陵の戦いで陸遜が劉備の陣を焼き払った。場所は今の宜昌付近。"},{"k":"history","zh":"鍾祥的明顯陵葬著嘉靖皇帝的父母，2000 年列入世界遺產","en":"Ming Xianling in Zhongxiang, tomb of the Jiajing Emperor's parents, became a World Heritage Site in 2000.","ja":"鍾祥の明顕陵には嘉靖帝の両親が眠り、2000年に世界遺産となった。"},{"k":"history","zh":"戰國時楚國的都城郢，就在今天的荊州一帶","en":"Ying, capital of the Warring States kingdom of Chu, lay near today's Jingzhou here.","ja":"戦国時代の楚の都・郢は、今の荊州付近にあった。"},{"k":"legend","zh":"省會漢陽的古琴台，相傳是俞伯牙彈〈高山流水〉遇見知音鍾子期的地方","en":"Guqin Terrace in Hanyang is where Yu Boya is said to have met his soulmate listener Zhong Ziqi.","ja":"漢陽の古琴台は、伯牙が「高山流水」を弾き知音の鍾子期と出会った場所と伝わる。"},{"k":"legend","zh":"俗語「天上九頭鳥」說的就是這裡的人，九頭鳥原是古楚人的圖騰","en":"Locals are nicknamed 'nine-headed birds', after a mythical bird once a totem of the Chu people.","ja":"ここの人は「九頭鳥」とあだ名される。九頭鳥はもとは楚人のトーテムだった。"}],
"CN-HE":[{"k":"origin","zh":"簡稱「○」取自古書《禹貢》九州裡的「○州」","en":"Its abbreviation comes from one of the Nine Provinces described in the ancient text Yu Gong.","ja":"略称「○」は古書『禹貢』の九州の一つ「○州」に由来"},{"k":"people","zh":"三國的劉備是涿郡涿縣人，就是今天的涿州","en":"Liu Bei of the Three Kingdoms came from Zhuo County, today's Zhuozhou.","ja":"三国志の劉備は涿郡涿県、今の涿州の出身"},{"k":"people","zh":"三國名將趙雲（趙子龍）生於常山真定，就是今天的正定縣","en":"Three Kingdoms general Zhao Yun (Zilong) was born in Zhending, today's Zhengding County.","ja":"三国志の名将・趙雲（子龍）は常山真定、今の正定県の生まれ"},{"k":"sport","zh":"2022 年冬奧的跳台滑雪、單板滑雪等雪上項目，在張家口崇禮舉行","en":"Ski jumping, snowboarding and other snow events of the 2022 Winter Olympics were held in Chongli, Zhangjiakou.","ja":"2022年冬季五輪のジャンプやスノーボードなどの雪上競技は、張家口の崇礼で行われた"},{"k":"festival","zh":"蔚縣暖泉的「打樹花」，元宵節時把上千度的鐵水潑上古堡城牆，火花四濺","en":"In Nuanquan, Yu County, 'tree flowers' bloom at the Lantern Festival as molten iron is flung against old fortress walls.","ja":"蔚県暖泉の「打樹花」は、元宵節に溶けた鉄を古い城壁に打ちつけて火花を咲かせる"},{"k":"record","zh":"1881 年通車的唐胥鐵路，被視為中國自建鐵路的起點","en":"The Tangxu Railway, opened in 1881, is seen as the starting point of China's self-built railways.","ja":"1881年開通の唐胥鉄道は、中国が自ら建設した鉄道の起点とされる"},{"k":"record","zh":"滄州的鐵獅子鑄於後周 953 年，重約 32 噸","en":"The Iron Lion of Cangzhou was cast in 953 under the Later Zhou and weighs about 32 tonnes.","ja":"滄州の鉄獅子は後周の953年に鋳造され、重さ約32トン"},{"k":"life","zh":"衡水中學以封閉式、準軍事化管理和亮眼的高考成績出名","en":"Hengshui High School is famous for its closed, quasi-military regime and stellar gaokao results.","ja":"衡水中学は全寮制の軍隊式管理と、大学入試の好成績で有名"},{"k":"origin","zh":"明清時稱「直隸」，意思是直屬京師，1928年才改成現名","en":"It was long called Zhili, 'directly ruled', until it got its present name in 1928.","ja":"かつては都に直属する意の「直隷」と呼ばれ、1928年に現在の名に改められた"},{"k":"origin","zh":"別稱「燕趙」，取自春秋戰國時控制這裡的燕、趙兩國","en":"Its nickname Yanzhao comes from the Yan and Zhao states that ruled here in ancient times.","ja":"別称「燕趙」は、春秋戦国時代にこの地を治めた燕と趙の二国に由来する"},{"k":"history","zh":"趙國在前386年遷都邯鄲，此後158年都以此為都","en":"In 386 BC the state of Zhao moved its capital to Handan, where it stayed 158 years.","ja":"趙は紀元前386年に邯鄲へ遷都し、158年間都とした"},{"k":"life","zh":"邯鄲號稱「成語之都」，「邯鄲學步」等1500多則成語出自當地","en":"Handan, the 'capital of Chinese idioms', is linked to 1,500+ idioms like 'learning to walk in Handan'.","ja":"邯鄲は「成語の都」と呼ばれ、「邯鄲の歩み」など1500以上の成語が生まれた"},{"k":"history","zh":"前227年荊軻刺秦前，燕太子丹一身白衣在易水邊為他送行","en":"In 227 BC, Prince Dan of Yan, dressed in white, saw the assassin Jing Ke off at the Yi River.","ja":"紀元前227年、燕の太子丹は白装束で易水のほとりから荊軻を見送った"},{"k":"legend","zh":"傳說黃帝與蚩尤的涿鹿之戰，發生在張家口一帶","en":"Legend places the Battle of Zhuolu, the Yellow Emperor against Chiyou, near Zhangjiakou.","ja":"黄帝と蚩尤が戦った涿鹿の戦いは、張家口一帯で起きたと伝わる"},{"k":"legend","zh":"傳說三皇之一的伏羲，曾住在今天的邢台","en":"Fuxi, one of the legendary Three Sovereigns, is said to have lived in present-day Xingtai.","ja":"伝説の三皇の一人・伏羲は、今の邢台に住んでいたとされる"},{"k":"legend","zh":"哭倒長城的孟姜女，在這裡的秦皇島有座孟姜女廟","en":"A temple to Lady Meng Jiang, whose weeping toppled the Great Wall, stands in Qinhuangdao.","ja":"涙で長城を崩した孟姜女を祀る廟が、秦皇島にある"},{"k":"people","zh":"《四庫全書》總纂官紀曉嵐生於獻縣，也寫了鬼怪故事集《閱微草堂筆記》","en":"Ji Yun, chief editor of the Siku Quanshu and a collector of ghost tales, was born in Xian County.","ja":"『四庫全書』の総編集官で怪異譚集も著した紀暁嵐は献県の生まれ"},{"k":"people","zh":"元代天文學家郭守敬生於邢台，算出一年為365.2425天","en":"Yuan astronomer Guo Shoujing, born in Xingtai, calculated the year as 365.2425 days.","ja":"一年を365.2425日と算出した元の天文学者・郭守敬は邢台の生まれ"},{"k":"people","zh":"中共創黨人之一李大釗生於樂亭，曾是毛澤東在北大圖書館的上司","en":"Li Dazhao, CCP co-founder and Mao's boss at the Peking University library, was born in Laoting.","ja":"中国共産党創設者の一人・李大釗は楽亭生まれで、北京大学図書館で毛沢東の上司だった"},{"k":"record","zh":"中國唯一同時擁有高原、山地、丘陵、海岸、平原與湖泊的省份","en":"It is China's only province with plateaus, mountains, hills, shoreline, plains and lakes all together.","ja":"高原・山地・丘陵・海岸・平野・湖のすべてを持つ中国唯一の省"},{"k":"life","zh":"全中國天主教徒人數最多的省份","en":"It has the largest Catholic population of any province in China.","ja":"中国で最もカトリック信者が多い省"},{"k":"history","zh":"正定隆興寺的千手觀音銅像高21.3公尺，鑄於北宋971年","en":"Longxing Temple's 21.3 m bronze thousand-armed Guanyin was cast in 971 under the Song.","ja":"正定・隆興寺の高さ21.3mの千手観音銅像は、北宋の971年に鋳造された"},{"k":"nature","zh":"最高峰是蔚縣的小五台山，海拔2882公尺","en":"Its highest peak is Mount Xiaowutai in Yu County, at 2,882 m.","ja":"最高峰は蔚県の小五台山で、標高2882m"},{"k":"nature","zh":"1048到1128年間，黃河曾改道直接流過這個省","en":"From 1048 to 1128 the Yellow River flowed straight through this province.","ja":"1048〜1128年、黄河は流れを変えてこの省を貫いて流れていた"},{"k":"nature","zh":"塞罕壩從1962年起在沙地邊緣造林，2017年獲聯合國「地球衛士獎」","en":"Saihanba, afforested since 1962 at a sandland's edge, won the UN Champions of the Earth award in 2017.","ja":"1962年から砂地の縁で植林を続ける塞罕壩は、2017年に国連の「地球大賞」を受けた"},{"k":"brand","zh":"長城汽車總部在保定，2003年成為中國首家上市的民營車廠","en":"Great Wall Motor, based in Baoding, became China's first publicly listed private automaker in 2003.","ja":"保定に本社を置く長城汽車は2003年、中国初の上場民営自動車メーカーとなった"},{"k":"brand","zh":"唐山的開灤煤礦，歷史可追溯到1878年","en":"The Kailuan coal mines in Tangshan trace their founding to 1878.","ja":"唐山の開灤炭鉱の起源は1878年にさかのぼる"},{"k":"brand","zh":"曲陽一帶從唐代起就燒製白瓷「定窯」","en":"Ding ware, a fine white porcelain, has been made around Quyang since the Tang dynasty.","ja":"曲陽一帯では唐代から白磁「定窯」が焼かれてきた"},{"k":"brand","zh":"磁州窯以白色化妝土上畫黑、褐色花紋的陶瓷聞名","en":"Cizhou ware is known for white-slipped stoneware painted in black or brown.","ja":"磁州窯は、白い化粧土に黒や茶で絵付けした陶器で知られる"},{"k":"life","zh":"握在手中轉動健身的「保定鐵球」，出自保定","en":"Baoding balls, rolled in the hand for exercise and meditation, come from Baoding.","ja":"手の中で回す健康球「保定鉄球」は保定の名物"},{"k":"sport","zh":"楊氏太極拳創始人楊露禪，出身永年的廣府","en":"Yang-style tai chi is tied to its founder Yang Luchan of Guangfu in Yongnian.","ja":"楊式太極拳の祖・楊露禅は永年の広府の出身"},{"k":"sport","zh":"2018年女子班迪球世界錦標賽，在承德的天然冰場舉行","en":"Chengde hosted the 2018 Women's Bandy World Championship on natural ice.","ja":"2018年の女子バンディ世界選手権は、承徳の天然リンクで開かれた"},{"k":"life","zh":"地方戲曲「評劇」在19世紀末起源於唐山一帶","en":"Pingju opera originated around Tangshan in the late 19th century.","ja":"地方劇「評劇」は19世紀末に唐山一帯で生まれた"}],
"CN-HI":[{"k":"origin","zh":"簡稱「○」來自唐太宗在 631 年增設的「○州」","en":"Its abbreviation comes from a prefecture added by Tang Emperor Taizong in 631.","ja":"略称「○」は唐の太宗が631年に設けた「○州」に由来"},{"k":"people","zh":"明代以清廉剛直聞名的海瑞，就是這裡人","en":"Hai Rui, the Ming official famed for his honesty and integrity, was a native of here.","ja":"清廉剛直で知られる明の官僚・海瑞は、ここの出身"},{"k":"people","zh":"宋氏三姊妹的父親宋耀如，出生在文昌","en":"Charlie Soong, father of the three Soong sisters, was born in Wenchang here.","ja":"宋家三姉妹の父・宋耀如は、文昌で生まれた"},{"k":"symbol","zh":"省花是三角梅，省樹是椰子樹","en":"Its provincial flower is the bougainvillea, and its provincial tree the coconut palm.","ja":"省の花はブーゲンビリア、省の木はココヤシ"},{"k":"record","zh":"這裡特有的黑冠長臂猿是最瀕危的猿類之一，只剩約 22 隻，全在霸王嶺","en":"A gibbon found only here is among the world's most endangered apes: about 22 remain, all in Bawangling reserve.","ja":"ここ固有のテナガザルは最も絶滅が危ぶまれる類人猿の一つで、約22頭が覇王嶺にいるだけ"},{"k":"life","zh":"旅客離島時可以買免稅品，2020 年起每人每年額度 10 萬人民幣","en":"Travellers leaving the island can shop duty-free, up to RMB 100,000 per person per year since 2020.","ja":"島を離れる旅行者は免税で買い物ができ、2020年から一人年10万元まで"},{"k":"life","zh":"明式家具最主要的名貴木料「黃花梨」，原產地就在這座島上","en":"Huanghuali, the prized main wood of Ming-style furniture, is native to this island.","ja":"明式家具の主な高級材「黄花梨」は、この島が原産地"},{"k":"work","zh":"馮小剛電影《非誠勿擾 2》裡，男女主角到三亞的山間別墅「試婚」","en":"In Feng Xiaogang's If You Are the One 2, the couple try out married life in a hillside villa in Sanya.","ja":"馮小剛監督の映画『非誠勿擾2』では、主人公たちが三亜の山の別荘で「試し婚」をする"},{"k":"history","zh":"西元前 110 年西漢將軍路博德到來，在這座島上設置駐軍","en":"Chinese records date to 110 BC, when Han general Lu Bode arrived and a garrison was set up on the island.","ja":"前110年、前漢の将軍路博徳が到来し、島に駐屯軍が置かれた"},{"k":"people","zh":"元代黃道婆在崖州向黎族學會紡織，回到松江後推廣棉紡技術","en":"In the Yuan era Huang Daopo learned cotton weaving from the Li people at Yazhou here, then spread it in Songjiang.","ja":"元代の黄道婆は崖州で黎族から紡織を学び、松江に戻って綿織物の技術を広めた"},{"k":"history","zh":"鑑真第五次東渡日本時遇風漂流，748 年被吹到這座島上","en":"On his fifth attempt to reach Japan in 748, the monk Jianzhen was blown off course to this island.","ja":"鑑真は748年、5度目の渡日の途中で嵐に遭い、この島に漂着した"},{"k":"history","zh":"1950 年春解放軍渡海登陸，5 月 1 日控制全島","en":"In spring 1950 the PLA crossed the strait and had the whole island under control by May 1.","ja":"1950年春、人民解放軍が海を渡って上陸し、5月1日に全島を掌握した"},{"k":"history","zh":"1939 年日軍攻島，黎族與共產黨游擊隊奮起抵抗","en":"Japan attacked the island in 1939, and Li and Communist guerrillas fought back.","ja":"1939年に日本軍が島へ侵攻し、黎族と共産党のゲリラが抵抗した"},{"k":"record","zh":"中國唯一沒有高速公路收費站的省","en":"It is the only Chinese province with no highway toll stations.","ja":"中国で唯一、高速道路の料金所がない省"},{"k":"record","zh":"全中國約 95% 的檳榔產自這裡","en":"About 95% of China's areca (betel) nuts are grown here.","ja":"中国のビンロウの約95%がここで生産される"},{"k":"history","zh":"20 世紀初，從英屬馬來亞回鄉的華僑把橡膠樹引進島上","en":"Overseas Chinese returning from British Malaya introduced rubber trees to the island in the early 1900s.","ja":"20世紀初め、英領マラヤから帰国した華僑がゴムの木を島に持ち込んだ"},{"k":"sport","zh":"2006 年起舉辦國際公路自行車賽，分九個賽段在島上競騎","en":"Since 2006 an international road cycling race has toured this island in nine stages.","ja":"2006年から、島を9ステージで巡る国際自転車ロードレースが開かれている"},{"k":"sport","zh":"萬寧的日月灣每年舉辦國際衝浪節","en":"Riyue Bay in Wanning hosts an international surfing festival every year.","ja":"万寧の日月湾では毎年、国際サーフィンフェスティバルが開かれる"},{"k":"festival","zh":"世界小姐選美的總決賽，多次在三亞舉行","en":"The Miss World pageant final has been held in Sanya many times.","ja":"ミス・ワールドの世界大会は、何度も三亜で開かれている"},{"k":"history","zh":"1990 年代初這裡的房地產泡沫破裂，被稱為中國現代史上最大的一次","en":"Its property bust around 1990 is described as the biggest in modern Chinese history.","ja":"1990年代初めの不動産バブル崩壊は、中国近代史上最大と言われる"},{"k":"record","zh":"三亞南山的海上觀音連基座高 108 公尺，一面朝島內、兩面朝南海","en":"The Guanyin statue at Nanshan in Sanya is 108 m tall with its base; one face looks inland, two face the sea.","ja":"三亜南山の海上観音は台座込みで高さ108m。一面は島の内側、二面は南シナ海を向く"},{"k":"nature","zh":"島的北半部位在古老火山區上，土壤裡常見帶氣孔的火山岩碎塊","en":"The island's north sits on an old volcanic field, and its soil is full of bits of porous volcanic rock.","ja":"島の北半分は古い火山地帯の上にあり、土には気泡の多い火山岩のかけらが混じる"},{"k":"nature","zh":"面積是世界第 42 大島，北邊隔著海峽與雷州半島相望","en":"The world's 42nd-largest island, it lies across a strait from the Leizhou Peninsula.","ja":"世界で42番目に大きな島で、北は海峡を挟んで雷州半島と向き合う"},{"k":"life","zh":"三亞的回輝人是占婆難民的後裔，信奉伊斯蘭教，說回輝話","en":"Sanya's Utsul people descend from Cham refugees from Champa; mostly Muslim, they speak the Tsat language.","ja":"三亜の回輝人はチャンパ王国から逃れた人々の子孫で、イスラム教を信じ回輝語を話す"},{"k":"legend","zh":"黎族傳說獵人追鹿到海邊，鹿回頭變成少女，三亞因此別稱「鹿城」","en":"In a Li legend a deer chased by a hunter turned back and became a girl; Sanya is nicknamed 'Deer City'.","ja":"猟師に追われた鹿が振り返って娘に変わった黎族の伝説から、三亜は「鹿城」と呼ばれる"},{"k":"history","zh":"島上最早的居民黎族，據推估約 4000 年前從雷州半島渡海而來","en":"The Li, the island's first people, are thought to have crossed from the Leizhou Peninsula about 4,000 years ago.","ja":"島の先住民黎族は、約4000年前に雷州半島から海を渡ってきたと推定される"},{"k":"festival","zh":"黎族的「牛節」在農曆三月初八，這天不殺牛也不讓牛工作","en":"On the Li people's Oxen's Festival, the 8th day of the 3rd lunar month, oxen are neither killed nor worked.","ja":"黎族の「牛節」は旧暦3月8日で、この日は牛を殺さず働かせもしない"},{"k":"life","zh":"傳統的黎族女子到一定年紀，會在手臂和背上刺青","en":"Traditionally, Li women tattooed their arms and backs after reaching a certain age.","ja":"伝統的に黎族の女性は、ある年齢になると腕や背中に入れ墨をした"},{"k":"symbol","zh":"坡鹿在這裡的野外幾乎絕跡，靠大型圍欄保育了數百隻","en":"Eld's deer nearly vanished from the wild here; a few hundred are protected in a large enclosure on the island.","ja":"エルドジカはここで野生ではほぼ絶滅し、大きな囲いの中で数百頭が保護されている"}],
"CN-HK":[{"k":"origin","zh":"名字相傳來自明代萬曆年間，在這裡轉運東莞產的香木","en":"The name is said to come from Ming-era shipments of fragrant wood from Dongguan that passed through here.","ja":"名前は明の万暦年間、東莞産の香木をここで積み替えたことに由来するとされる"},{"k":"people","zh":"成龍出生在這裡的太平山","en":"Jackie Chan was born on Victoria Peak here.","ja":"ジャッキー・チェンは、ここのビクトリア・ピークで生まれた"},{"k":"work","zh":"押井守《攻殼機動隊》（1995）的未來都市，以這裡的街景為原型","en":"The future city in Mamoru Oshii's Ghost in the Shell (1995) was modeled on the streets here.","ja":"押井守『攻殻機動隊』（1995）の未来都市は、ここの街並みがモデル"},{"k":"work","zh":"王家衛《重慶森林》片名的「重慶」，指的是尖沙咀的重慶大廈","en":"The 'Chungking' in Wong Kar-wai's Chungking Express refers to Chungking Mansions in Tsim Sha Tsui.","ja":"王家衛『恋する惑星』の原題「重慶森林」の重慶とは、尖沙咀の重慶大厦のこと"},{"k":"symbol","zh":"區花是洋紫荊，也畫在區旗上","en":"Its floral emblem is the Bauhinia blakeana, which also appears on its flag.","ja":"区の花はバウヒニア（洋紫荊）で、旗にも描かれている"},{"k":"festival","zh":"中秋夜大坑舞火龍，龍身插滿約 1.2 萬支香，長達 67 公尺","en":"On Mid-Autumn night, Tai Hang parades a 67 m fire dragon studded with about 12,000 incense sticks.","ja":"中秋の夜、大坑では約1万2千本の線香を挿した長さ67mの火龍が練り歩く"},{"k":"sport","zh":"1845 年興建的跑馬地馬場，通常在星期三晚上舉行夜賽","en":"Happy Valley Racecourse, built in 1845, usually holds its races on Wednesday nights.","ja":"1845年建設のハッピーバレー競馬場は、ふだん水曜の夜にレースを行う"},{"k":"life","zh":"1997 年啟用的交通卡「八達通」，是全球第二套非接觸式智慧卡系統","en":"The Octopus card, launched in 1997, was the world's second contactless smart card system.","ja":"1997年導入の交通カード「オクトパス」は、世界で2番目の非接触ICカードシステム"},{"k":"origin","zh":"「九龍」指八座山，再加上南宋末帝趙昺——皇帝也算一條龍","en":"Kowloon, 'Nine Dragons', refers to eight hills plus Song emperor Bing, counted as the ninth dragon.","ja":"九龍の名は8つの山と南宋の皇帝趙昺を合わせたもので、皇帝も龍に数えられた"},{"k":"symbol","zh":"1952 年在南丫島山洞首次發現的盧氏小樹蛙，體長只有 1.5～2.5 公分","en":"Romer's tree frog, first found in a Lamma Island cave in 1952, is only 1.5–2.5 cm long.","ja":"1952年に南丫島の洞窟で見つかった盧氏小樹蛙は、体長わずか1.5〜2.5cm"},{"k":"symbol","zh":"興建新機場前，200 多隻盧氏小樹蛙從赤鱲角被救出，繁殖後野放各地","en":"Before the new airport was built, over 200 Romer's tree frogs were rescued from Chek Lap Kok and bred for release.","ja":"新空港建設前、赤鱲角から200匹以上の盧氏小樹蛙が救出され、繁殖後に各地へ放された"},{"k":"record","zh":"1997 年由柴契爾夫人主持啟用的青馬大橋，上層走汽車、下層走鐵路","en":"Opened by Margaret Thatcher in 1997, Tsing Ma Bridge carries cars on its upper deck and trains below.","ja":"1997年にサッチャー元首相が開通式を行った青馬大橋は、上段が道路、下段が鉄道"},{"k":"history","zh":"九龍寨城人口密度一度達每平方公里約 120 萬人，1993 年起拆除","en":"Kowloon Walled City once packed about 1.2 million people per km² before demolition began in 1993.","ja":"九龍城砦の人口密度は1平方キロあたり約120万人に達し、1993年から取り壊された"},{"k":"legend","zh":"沙田山上的望夫石，傳說是背著兒子天天等丈夫歸來的漁婦所化","en":"Amah Rock above Sha Tin is said to be a fisherman's wife, turned to stone while waiting with her son.","ja":"沙田の山上の望夫石は、子を連れて夫の帰りを待ち続けた漁師の妻が石になったものと伝わる"},{"k":"food","zh":"「鴛鴦」是咖啡加奶茶，約三分咖啡、七分奶茶","en":"Yuenyeung mixes coffee with milk tea, roughly three parts coffee to seven parts tea.","ja":"「鴛鴦（ユンヨン）」はコーヒーとミルクティーをおよそ3対7で混ぜた飲み物"},{"k":"food","zh":"路邊攤「大牌檔」得名於牌照特別大，1956 年起就不再發新牌","en":"Dai pai dong street stalls are named for their oversized licences; no new ones have been issued since 1956.","ja":"屋台「大牌檔」は許可証が大きかったことが名の由来で、1956年以降は新規発行がない"},{"k":"brand","zh":"滙豐銀行 1865 年在這裡創立，創辦人是 P&O 航運公司的蘇石蘭","en":"HSBC was founded here in 1865 by Thomas Sutherland, founder of the P&O shipping line.","ja":"HSBCは1865年にここで創業。創業者はP&O汽船を興したトマス・サザーランド"},{"k":"life","zh":"每逢驚蟄，鵝頸橋底就有人用鞋子拍打紙人，替人「打小人」","en":"On Jingzhe, people under the Canal Road Flyover beat paper effigies with shoes in 'villain hitting' rites.","ja":"啓蟄の日、鵝頸橋の高架下では紙人形を靴で叩く「打小人」の儀式が行われる"},{"k":"sport","zh":"1976 年開辦的國際七人欖球賽，南看台以觀眾變裝狂歡聞名","en":"Its international rugby sevens began in 1976; the South Stand is famous for costumed, partying fans.","ja":"1976年に始まった国際7人制ラグビー大会は、仮装して騒ぐ南スタンドで有名"},{"k":"people","zh":"長洲出身的滑浪風帆選手李麗珊，1996 年奪下這裡第一面奧運獎牌（金牌）","en":"Windsurfer Lee Lai-shan of Cheung Chau won its first-ever Olympic medal, a gold, in 1996.","ja":"長洲出身のウインドサーフィン選手李麗珊は、1996年にここ初の五輪メダル（金）を獲得"},{"k":"nature","zh":"西貢糧船灣一帶有大片火山岩柱，2011 年列入聯合國教科文組織世界地質公園","en":"High Island in Sai Kung has vast columns of volcanic tuff; the area joined UNESCO's Global Geoparks in 2011.","ja":"西貢の糧船湾には火山岩の柱状節理が広がり、2011年にユネスコ世界ジオパークに加盟"},{"k":"work","zh":"1979 年羅文唱的電視劇主題曲〈獅子山下〉，被視為非官方的區歌","en":"'Below the Lion Rock', the 1979 TV theme sung by Roman Tam, is seen as an unofficial anthem here.","ja":"1979年にロマン・タムが歌ったドラマ主題歌「獅子山下」は、非公式の地元の歌とされる"},{"k":"work","zh":"《黑暗騎士》（2008）中蝙蝠俠追到這裡抓人，劇組在國際金融中心頂樓空拍","en":"In The Dark Knight (2008), Batman flies here to seize Lau; aerial shots were filmed atop the IFC tower.","ja":"『ダークナイト』（2008）でバットマンはラウを捕らえにここへ。IFCの屋上から空撮した"},{"k":"work","zh":"電影《環太平洋》（2013）中，對抗怪獸的最後機甲基地就設在這裡","en":"In Pacific Rim (2013), the last Jaeger base, the Shatterdome, is located here.","ja":"映画『パシフィック・リム』（2013）で、イェーガーの最後の基地はここに置かれている"},{"k":"history","zh":"1941 年日軍進攻，守軍苦戰 18 天後在聖誕節投降，史稱「黑色聖誕」","en":"Japan's 1941 invasion ended after 18 days with surrender on Christmas Day, remembered as 'Black Christmas'.","ja":"1941年の日本軍侵攻で守備隊は18日後のクリスマスに降伏し、「ブラック・クリスマス」と呼ばれる"},{"k":"history","zh":"九龍半島南部 1860 年割讓英國，新界則在 1898 年租借 99 年","en":"Southern Kowloon was ceded to Britain in 1860; the New Territories were leased for 99 years in 1898.","ja":"九龍半島南部は1860年に英国へ割譲、新界は1898年に99年間租借された"},{"k":"people","zh":"孫中山曾就讀 1887 年創辦的西醫書院，該校後來成為大學醫學院","en":"Sun Yat-sen studied at the College of Medicine for Chinese, founded here in 1887 and later part of the university.","ja":"孫文は1887年創立の西医書院で学んだ。同校はのちに大学の医学部となった"},{"k":"people","zh":"武俠小說家金庸 1959 年在這裡創辦《明報》","en":"Wuxia novelist Jin Yong (Louis Cha) founded the newspaper Ming Pao here in 1959.","ja":"武侠小説家の金庸は1959年、ここで新聞『明報』を創刊した"},{"k":"brand","zh":"維他奶 1940 年創立，最初挨家挨戶送豆漿，給喝不了牛奶的人補充蛋白質","en":"Vitasoy began in 1940 delivering soy milk door to door as protein for people who can't digest milk.","ja":"ビタソイは1940年創業。牛乳が苦手な人向けに豆乳を戸別配達したのが始まり"},{"k":"life","zh":"九龍與對岸的島之間只靠隧道相連，一座橋也沒有","en":"Kowloon and the island across the harbour are linked only by tunnels, with no bridges at all.","ja":"九龍と対岸の島の間はトンネルだけで結ばれ、橋は1本もない"},{"k":"legend","zh":"長洲有個「張保仔洞」，傳說海盜張保仔把寶藏藏在裡面","en":"Cheung Chau has a cave where legend says pirate Cheung Po Tsai hid his treasure.","ja":"長洲の「張保仔洞」には、海賊張保仔が財宝を隠したという伝説がある"},{"k":"life","zh":"在茶餐廳，客人常用先送上的清茶涮洗餐具，人多時還要「搭枱」","en":"At cha chaan teng cafés, diners rinse cutlery in the free weak tea and share tables when busy.","ja":"茶餐廳では最初に出る薄いお茶で食器をすすぎ、混雑時は相席（搭枱）が当たり前"},{"k":"food","zh":"茶餐廳點單有暗號：「0T」是檸檬茶，「茶走」是加煉奶的奶茶","en":"Café order slang: '0T' means lemon tea, and 'caa zau' is milk tea made with condensed milk.","ja":"茶餐廳の符丁では「0T」がレモンティー、「茶走」は練乳入りのミルクティー"}],
"CN-HL":[{"k":"origin","zh":"名字來自北方的界河，因為河水黝黑、蜿蜒得像遊龍","en":"It is named after the border river, whose dark waters wind like a swimming dragon.","ja":"名は北の国境の川から。川の水が黒く、竜のようにうねることに由来"},{"k":"people","zh":"女作家蕭紅出生在呼蘭，代表作有《呼蘭河傳》《生死場》","en":"Writer Xiao Hong, author of Tales of Hulan River and The Field of Life and Death, was born in Hulan.","ja":"『呼蘭河伝』『生死場』の作家・蕭紅は、呼蘭の生まれ"},{"k":"work","zh":"2014 年奪得柏林金熊獎的《白日焰火》，在零下 30 度的省會拍攝","en":"Black Coal, Thin Ice, winner of the 2014 Berlin Golden Bear, was shot in the capital at below -30°C.","ja":"2014年ベルリン金熊賞の『薄氷の殺人』は、氷点下30度の省都で撮影された"},{"k":"sport","zh":"七台河出身的短道速滑選手拿下中國三分之二的冬奧短道金牌，人稱「冠軍之城」","en":"Short-track skaters from Qitaihe have won two-thirds of China's Olympic short-track golds, hence 'City of Champions'.","ja":"七台河出身のショートトラック選手が中国の五輪金の3分の2を獲得し「チャンピオンの町」と呼ばれる"},{"k":"sport","zh":"2025 年第九屆亞洲冬季運動會，在省會舉行","en":"The 9th Asian Winter Games were held in the provincial capital in 2025.","ja":"2025年の第9回アジア冬季競技大会は、省都で開かれた"},{"k":"festival","zh":"省會的國際冰雪節源自 1963 年的冰燈遊園會，與札幌雪祭齊名","en":"The capital's ice and snow festival grew from a 1963 ice-lantern show and ranks alongside the Sapporo Snow Festival.","ja":"省都の国際氷雪祭は1963年の氷灯遊園会が起源で、さっぽろ雪まつりと並び称される"},{"k":"symbol","zh":"省會的市花是丁香，市樹是榆樹","en":"The capital's city flower is the lilac, and its city tree the elm.","ja":"省都の市の花はライラック、市の木はニレ"},{"k":"record","zh":"劃分中國人口疏密的「胡煥庸線」，北端就在本省","en":"The Hu Line, which divides China's crowded southeast from its sparse northwest, has its northern end here.","ja":"中国の人口の疎密を分ける「胡煥庸線」は、北端がこの省にある"},{"k":"history","zh":"1115 年女真人建立金朝，第一個都城上京會寧府在今省會的阿城區","en":"In 1115 the Jurchens founded the Jin dynasty, with its first capital at Acheng in today's provincial capital.","ja":"1115年に女真族が金を建国し、最初の都・上京会寧府は今の省都の阿城区にあった"},{"k":"history","zh":"1858 年清朝在璦琿與俄國簽約，把北方界河以北 60 多萬平方公里割給俄國","en":"In 1858 the Qing signed the Treaty of Aigun here, ceding over 600,000 km² of land to Russia.","ja":"1858年、清はここ璦琿でロシアと条約を結び、60万平方キロ以上を割譲した"},{"k":"history","zh":"1909 年韓國志士安重根在省會火車站槍殺日本前首相伊藤博文","en":"In 1909 Korean activist An Jung-geun shot former Japanese PM Itō Hirobumi at the capital's railway station.","ja":"1909年、安重根が省都の駅で元首相・伊藤博文を射殺した"},{"k":"history","zh":"日軍進行細菌戰的 731 部隊，總部就設在省會的平房區","en":"Japan's germ-warfare Unit 731 had its main facility in the Pingfang district of the capital.","ja":"旧日本軍の細菌戦部隊・731部隊の本部は、省都の平房区にあった"},{"k":"people","zh":"1910 年伍連德到省會撲滅鼠疫，他設計的口罩被視為 N95 的先驅","en":"In 1910 Dr. Wu Lien-teh fought a plague outbreak in the capital; his mask is seen as a forerunner of the N95.","ja":"1910年、伍連徳は省都でペストを抑え込み、彼のマスクはN95の先駆けとされる"},{"k":"history","zh":"1969 年中蘇兩軍在烏蘇里江的珍寶島爆發武裝衝突","en":"In 1969 Chinese and Soviet troops clashed over Zhenbao Island on the Ussuri River here.","ja":"1969年、ウスリー川の珍宝島で中ソ両軍が武力衝突した"},{"k":"nature","zh":"兩條界江交會處的黑瞎子島（意為黑熊島），2008 年由中俄兩國瓜分","en":"Heixiazi ('Black Bear') Island, where two border rivers meet, was split between China and Russia in 2008.","ja":"二つの国境の川が合流する黒瞎子島（黒熊の島）は、2008年に中露で分割された"},{"k":"nature","zh":"中俄界湖興凱湖，以總面積計算是中國第二大湖","en":"Lake Khanka, shared with Russia, ranks as China's second-largest lake by total area.","ja":"中露国境の興凱湖は、総面積で数えると中国第2の湖だ"},{"k":"record","zh":"鏡泊湖是中國最大的火山熔岩堰塞湖，出口有吊水樓瀑布","en":"Jingpo Lake is China's largest lava-dammed lake, with Diaoshuilou Falls at its outlet.","ja":"鏡泊湖は中国最大の溶岩堰止湖で、出口には吊水楼瀑布がある"},{"k":"history","zh":"1987 年大興安嶺森林大火延燒近一個月，是中國死傷最慘重的森林火災","en":"The 1987 Greater Khingan fire burned for nearly a month and is China's deadliest forest fire.","ja":"1987年の大興安嶺の森林火災は約1か月燃え続け、中国で最も死者の多い森林火災となった"},{"k":"origin","zh":"相傳因省的輪廓像天鵝，省會被稱為「天鵝項下的珍珠」","en":"Said to be shaped like a swan, the province has a capital nicknamed 'the pearl on the swan's neck'.","ja":"省の形が白鳥に似ているとされ、省都は「白鳥の首の真珠」と呼ばれる"},{"k":"sport","zh":"湯原出身的楊揚，2002 年奪下中國第一面冬奧金牌","en":"Speed skater Yang Yang from Tangyuan won China's first-ever Winter Olympic gold in 2002.","ja":"湯原出身の楊揚は2002年、中国初の冬季五輪金メダルを獲得した"},{"k":"sport","zh":"省會出身的申雪與搭檔趙宏博，2010 年奪下中國第一面冬奧花式滑冰金牌","en":"Capital-born Shen Xue and partner Zhao Hongbo won China's first Olympic figure skating gold in 2010.","ja":"省都出身の申雪と趙宏博は2010年、中国初のフィギュアスケート五輪金メダルを獲得した"},{"k":"sport","zh":"省會辦過 1996 年亞洲冬季運動會與 2009 年世界大學生冬季運動會","en":"The capital hosted the 1996 Asian Winter Games and the 2009 Winter Universiade.","ja":"省都は1996年のアジア冬季大会と2009年の冬季ユニバーシアードを開催した"},{"k":"work","zh":"1962 年寫成的民歌《烏蘇里船歌》，主旋律改編自赫哲族的民歌曲調","en":"A famous 1962 folk song about boating on the Ussuri River was adapted from tunes of the Hezhe people here.","ja":"ウスリー川の舟歌として知られる1962年の民謡は、ホジェン族の旋律をもとに作られた"},{"k":"work","zh":"曲波小說《林海雪原》取材自牡丹江一帶剿匪，「智取威虎山」就出自這本書","en":"Qu Bo's novel Tracks in the Snowy Forest, source of Taking Tiger Mountain by Strategy, is set around Mudanjiang.","ja":"曲波の小説『林海雪原』は牡丹江一帯の匪賊討伐が題材で、「智取威虎山」の原作だ"},{"k":"life","zh":"赫哲族把鰱魚、鯉魚的魚皮捶軟縫成衣服，是他們獨有的民族服裝","en":"The Hezhe people here traditionally made clothing from fish skin, pounded soft and sewn together.","ja":"ホジェン族は魚の皮を叩いて柔らかくし、衣服に仕立てる独特の伝統を持つ"},{"k":"festival","zh":"赫哲族每兩年舉辦一次「烏日貢」大會，這個節日 1985 年才誕生","en":"The Hezhe hold their Wurigong festival every two years, a tradition that only began in 1985.","ja":"ホジェン族は1985年に始まった祭り「ウリゴン」を2年に1度開く"},{"k":"food","zh":"赫哲族有生吃魚的習慣，招牌菜「他勒卡」是拌了蔬菜的涼拌生魚","en":"The Hezhe eat fish raw; their signature dish talaka is raw fish tossed with vegetables.","ja":"ホジェン族には魚を生で食べる習慣があり、名物「タラカ」は野菜と和えた生魚だ"},{"k":"life","zh":"二十世紀初省會的猶太社區，曾是遠東最大的猶太人社群","en":"In the early 20th century, the capital had the largest Jewish community in the Far East.","ja":"20世紀初め、省都には極東最大のユダヤ人社会があった"},{"k":"brand","zh":"省會的老牌啤酒廠，是一位波蘭人在 1900 年創立的","en":"The capital's famous brewery was founded in 1900 by a Pole, Jan Wróblewski.","ja":"省都の老舗ビール会社は、1900年にポーランド人が創業した"},{"k":"nature","zh":"與省同名的界河，由額爾古納河和石勒喀河在漠河附近匯合而成","en":"The border river that shares the province's name forms where the Argun and Shilka meet near Mohe.","ja":"省と同じ名の国境の川は、漠河付近でアルグン川とシルカ川が合流してできる"},{"k":"history","zh":"富錦以東原是大片沼澤，開墾成農田後人稱「北大荒」","en":"The vast swamps east of Fujin, known as the 'Great Northern Wilderness', were reclaimed as farmland.","ja":"富錦以東の大湿地は「北大荒」と呼ばれ、開墾されて農地になった"}],
"CN-HN":[{"k":"origin","zh":"五代詩人譚用之寫下「秋風萬里芙蓉國」，這裡從此別稱「芙蓉國」","en":"A line by poet Tan Yongzhi, 'autumn wind over ten thousand li of hibiscus land', gave it the nickname 'Hibiscus Land'.","ja":"詩人・譚用之の句「秋風万里芙蓉国」から、「芙蓉の国」とも呼ばれる"},{"k":"people","zh":"寫下小說《邊城》的作家沈從文，是鳳凰人","en":"Shen Congwen, author of the novel Border Town, came from Fenghuang.","ja":"小説『辺城』の作家・沈従文は、鳳凰の出身"},{"k":"people","zh":"組織地方軍隊對抗太平天國的晚清名臣曾國藩，是這裡人","en":"Zeng Guofan, the late-Qing statesman who raised an army against the Taiping rebels, was a native here.","ja":"太平天国と戦う軍を組織した清末の重臣・曽国藩は、ここの出身"},{"k":"work","zh":"《阿凡達》的懸浮山參考了張家界，園內一根石柱 2010 年改名「哈利路亞山」","en":"Avatar's floating mountains drew on Zhangjiajie; a pillar there was renamed 'Avatar Hallelujah Mountain' in 2010.","ja":"『アバター』の浮遊する山は張家界が参考で、園内の石柱は2010年に「ハレルヤ山」と改名"},{"k":"life","zh":"以《快樂大本營》聞名的省級衛視，因台標像芒果而被叫作「芒果台」","en":"The provincial TV channel behind Happy Camp is nicknamed 'Mango TV' because its logo looks like a mango.","ja":"『快楽大本営』で知られる省の衛星テレビは、ロゴがマンゴーに似て「マンゴー台」と呼ばれる"},{"k":"life","zh":"瀏陽被視為煙花爆竹的發源地，一直是中國煙花生產的中心","en":"Liuyang is considered the birthplace of fireworks and has always been the center of China's fireworks production.","ja":"瀏陽は花火・爆竹の発祥地とされ、ずっと中国の花火生産の中心"},{"k":"record","zh":"張家界大峽谷玻璃橋 2016 年開放時，是世界最長、最高的玻璃橋","en":"Zhangjiajie's glass bridge was the world's longest and highest glass-bottomed bridge when it opened in 2016.","ja":"張家界の大峡谷ガラス橋は2016年の開通時、世界最長・最高のガラス橋だった"},{"k":"people","zh":"105 年改良造紙術的東漢宦官蔡倫，出生在今天的耒陽","en":"Cai Lun, who improved papermaking in 105 AD, was born in today's Leiyang here.","ja":"105年に製紙法を改良した後漢の蔡倫は、今の耒陽の生まれ。"},{"k":"people","zh":"戊戌變法失敗後拒絕逃亡、從容就義的譚嗣同，祖籍瀏陽","en":"Tan Sitong, who refused to flee after the 1898 reform failed and was executed, was from Liuyang here.","ja":"戊戌変法の失敗後も逃げずに処刑された譚嗣同は、瀏陽の出身。"},{"k":"people","zh":"寫〈愛蓮說〉、被視為理學開山祖師的周敦頤，是道州（今道縣）人","en":"Zhou Dunyi, author of 'On Loving the Lotus' and a founder of Neo-Confucianism, was from Daozhou here.","ja":"「愛蓮説」を書き宋学の祖とされる周敦頤は、道州（今の道県）の人。"},{"k":"people","zh":"寫《海國圖志》、主張「師夷長技以制夷」的魏源，是邵陽人","en":"Wei Yuan, who wrote the Illustrated Treatise on the Maritime Kingdoms, was from Shaoyang here.","ja":"『海国図志』を著し「夷の長技を師とし夷を制す」を説いた魏源は邵陽の人。"},{"k":"people","zh":"與孫中山並稱「孫黃」的辛亥革命領袖黃興，是省會人","en":"Huang Xing, Sun Yat-sen's partner in the 1911 Revolution, was a native of this province's capital.","ja":"孫文と並び「孫黄」と称された辛亥革命の指導者・黄興は、省都の出身。"},{"k":"people","zh":"1915 年起兵反對袁世凱稱帝、發動護國戰爭的蔡鍔，是邵陽人","en":"Cai E, who led the 1915 National Protection War against Yuan Shikai's monarchy, was from Shaoyang here.","ja":"1915年に袁世凱の帝政に反対し護国戦争を起こした蔡鍔は、邵陽の人。"},{"k":"work","zh":"謝晉電影《芙蓉鎮》在這裡的王村拍攝，2007 年王村因此改名為芙蓉鎮","en":"Xie Jin's Hibiscus Town was filmed in Wangcun here, which renamed itself Furong Town in 2007.","ja":"謝晋の映画『芙蓉鎮』は○○の王村で撮影され、王村は2007年に芙蓉鎮へ改名した。"},{"k":"work","zh":"北宋宋迪描繪這裡兩條河一帶的山水畫題「八景」，日本的「近江八景」即由此而來","en":"The 'Eight Views' painting theme of two rivers here, begun by Song Di, inspired Japan's Eight Views of Ōmi.","ja":"北宋の宋迪がこの地の二つの川を描いた画題「八景」は、日本の「近江八景」の元になった。"},{"k":"food","zh":"美式中餐名菜「左宗棠雞」，借用的是這裡清末名臣的名字","en":"General Tso's chicken, a US Chinese-food classic, is named after a Qing statesman from here.","ja":"アメリカの中華料理「左宗棠鶏」は、この地出身の清末の名臣の名を借りている。"},{"k":"life","zh":"這裡雖不產檳榔，卻流傳約 400 年的嚼檳榔習慣，原料多從海南運來加工","en":"Though none grows here, chewing betel nut is a 400-year-old habit, with raw nuts shipped from Hainan.","ja":"ビンロウは採れないのに、噛む習慣が約400年続き、原料は海南から運んで加工する。"},{"k":"origin","zh":"省會的名字早在西周就出現，當時有人向周成王進貢當地產的鱉","en":"The capital's name dates to the Western Zhou, when a lord sent King Cheng a softshell turtle from there.","ja":"省都の名は西周に遡り、周の成王にその地のスッポンが献上された記録がある。"},{"k":"origin","zh":"以奇峰聞名的張家界，原名大庸，1994 年才改成現在的名字","en":"Zhangjiajie, famed for its stone pillars, was called Dayong until it was renamed in 1994.","ja":"奇峰で知られる張家界は、1994年までは大庸という名だった。"},{"k":"record","zh":"龍山縣里耶古井出土三萬多枚秦簡，其中一枚被認為是中國現存最早的郵寄信件","en":"Over 36,000 Qin slips were found in a well at Liye; one is thought to be China's oldest surviving mailed letter.","ja":"龍山県里耶の古井戸から秦簡3万6千枚余りが出土し、その一枚は中国最古の郵便とされる。"},{"k":"nature","zh":"天門山有高約 131 公尺的天然穿山洞，登山公路「通天大道」有 99 道彎","en":"Tianmen Mountain has a 131-m-high natural arch, reached by an 11-km road with 99 bends.","ja":"天門山には高さ約131メートルの天然の穴があり、登山道路「通天大道」は99のカーブがある。"},{"k":"history","zh":"抗戰期間日軍四度進攻省會，前三次都被薛岳擊退","en":"Japan attacked the capital four times in WWII; Xue Yue's forces repelled the first three.","ja":"日中戦争で日本軍は省都を4回攻め、最初の3回は薛岳の軍に撃退された。"},{"k":"history","zh":"1938 年國民黨軍怕省會落入日軍手中，下令放火焚城，史稱文夕大火","en":"In 1938 Nationalist commanders, fearing Japanese capture, set the capital ablaze in the Wenxi Fire.","ja":"1938年、国民党軍は省都が日本軍の手に落ちるのを恐れて火を放った（文夕大火）。"},{"k":"history","zh":"1945 年 8 月 21 日，日軍在芷江舉行在中國的第一場大型投降儀式","en":"On 21 August 1945, Zhijiang here hosted the first major Japanese surrender ceremony in China.","ja":"1945年8月21日、芷江で中国における最初の大規模な日本軍降伏式が行われた。"},{"k":"legend","zh":"西部山區流傳「趕屍」：道士帶客死異鄉的人連夜跳著回故鄉，是殭屍片的靈感來源","en":"Western mountains here tell of corpse-driving: escorts leading the dead home by night, inspiring jiangshi films.","ja":"西部山地には、客死者を夜通し故郷へ連れ帰る「趕屍」の伝承があり、キョンシー映画の元となった。"},{"k":"legend","zh":"屈原投水自盡的汨羅江，在這裡注入洞庭湖","en":"The Miluo River, where the poet Qu Yuan drowned himself, flows into Dongting Lake here.","ja":"屈原が身を投げた汨羅江は、○○で洞庭湖に注ぐ。"},{"k":"legend","zh":"唐傳奇《柳毅傳》中，柳毅替受虐的龍女送信，回到的是洞庭湖龍宮","en":"In the Tang tale of Liu Yi, he carries a mistreated dragon princess's letter home to the Dongting Lake palace.","ja":"唐の伝奇『柳毅伝』で柳毅が虐げられた龍女の手紙を届けた先は、洞庭湖の龍宮。"},{"k":"brand","zh":"省會號稱「世界工程機械之都」，挖土機、起重機產業集中在這裡","en":"The capital calls itself the construction machinery capital of the world.","ja":"省都は「世界の建設機械の都」を名乗り、建機産業が集まっている。"},{"k":"brand","zh":"醴陵以瓷器聞名，當地燒的「主席瓷」常被拿來當國禮","en":"Liling here is famed for porcelain; its 'Chairman Mao' ware has been given as state gifts.","ja":"醴陵は磁器で名高く、当地の「主席磁」は国賓への贈り物に使われる。"},{"k":"brand","zh":"中國四大名繡之一的「○繡」，就產自這裡","en":"One of China's Four Great Embroideries is named after and made in this province.","ja":"中国四大刺繍の一つ「○繍」は、ここで生まれた。"}],
"CN-JL":[{"k":"origin","zh":"名字來自滿語「○○烏拉」，意思是「沿著江邊」","en":"The name comes from a Manchu phrase meaning 'along the river'.","ja":"名は「川沿い」を意味する満州語に由来"},{"k":"sport","zh":"2007 年亞洲冬季運動會在省會舉行","en":"The 2007 Asian Winter Games were held in the provincial capital.","ja":"2007年のアジア冬季競技大会は、省都で開かれた"},{"k":"symbol","zh":"省會的市花是君子蘭，1980 年代曾被炒到一盆幾十萬人民幣","en":"The capital's city flower is the clivia; in the 1980s a single pot could fetch hundreds of thousands of yuan.","ja":"省都の市の花はクンシラン。1980年代には一鉢数十万元まで高騰した"},{"k":"record","zh":"1976 年 3 月的隕石雨，最大一塊重 1770 公斤，是已知最重的石隕石","en":"A meteorite shower in March 1976 dropped a 1,770 kg stone, the heaviest stony meteorite known.","ja":"1976年3月の隕石雨で落ちた最大の石は1770kgで、知られる限り最も重い石質隕石"},{"k":"record","zh":"長白山約 946 年的「千年大噴發」，是近五千年地球最強的火山噴發之一","en":"Changbai Mountain's 'Millennium Eruption' around 946 was among the most powerful on Earth in 5,000 years.","ja":"長白山の946年頃の「千年大噴火」は、過去5000年で最大級の噴火の一つ"},{"k":"work","zh":"《盜墓筆記》裡張起靈守護「終極」的雲頂天宮青銅門，就在長白山","en":"In The Lost Tomb novels, the bronze gate Zhang Qiling guards lies in the Cloud Palace on Changbai Mountain.","ja":"『盗墓筆記』で張起霊が守る雲頂天宮の青銅の門は、長白山にある"},{"k":"festival","zh":"1992 年在省會創辦的國家級電影節，是中國最早的電影節之一","en":"The national film festival founded in the capital in 1992 is one of China's earliest film festivals.","ja":"1992年に省都で始まった国家級映画祭は、中国で最も早い映画祭の一つ"},{"k":"record","zh":"中國第一列國產「和諧號」電力動車組，2007 年在省會的長客廠造出","en":"China's first domestically built Hexie electric multiple-unit train was produced in the capital in 2007.","ja":"中国初の国産「和諧号」電車は、2007年に省都の車両工場で造られた"},{"k":"record","zh":"省內有一座城市與省同名，是中國唯一省、市同名的例子","en":"It contains the only city in China that shares its name with its province.","ja":"省内に省と同じ名前の市があり、中国で唯一の例だ"},{"k":"history","zh":"與省同名的城市清代舊稱「船廠」，1661 年起在松花江畔造戰船、設水師營","en":"Its namesake city was once called 'Shipyard': from 1661 the Qing built warships and a navy camp there.","ja":"省と同名の市は清代に「船廠」と呼ばれ、1661年から松花江畔で軍船が造られた"},{"k":"history","zh":"清廷在此設打牲烏拉總管衙門，專替皇室採集東珠、鱘魚、貂皮與人參","en":"The Qing set up a special office here to gather freshwater pearls, sturgeon, sable and ginseng for the court.","ja":"清朝はここに役所を置き、宮廷に献上する東珠やチョウザメ、貂皮を集めさせた"},{"k":"nature","zh":"東南部的長白山，是松花江、圖們江、鴨綠江三條江的源頭","en":"Its Changbai Mountains are the source of three rivers: the Songhua, the Tumen and the Yalu.","ja":"長白山は松花江・図們江・鴨緑江という三つの川の源流だ"},{"k":"record","zh":"長白山中國側的白雲峰海拔 2691 公尺，是中國東北第一高峰","en":"Baiyun Peak (2,691 m) on the Chinese side of Changbai Mountain is the highest peak in Northeast China.","ja":"長白山の中国側にある白雲峰（2691m）は、中国東北地方の最高峰だ"},{"k":"nature","zh":"長白山真正的最高峰「將軍峰」，其實在北韓那一側","en":"Changbai Mountain's true summit, Janggun Peak, actually lies on the North Korean side.","ja":"長白山の本当の最高峰「将軍峰」は、実は北朝鮮側にある"},{"k":"legend","zh":"清朝皇室愛新覺羅氏宣稱，始祖是長白山的仙女所生","en":"The Qing imperial Aisin Gioro clan claimed their founding ancestor was conceived near Changbai Mountain.","ja":"清の皇室・愛新覚羅氏は、始祖が長白山の天女から生まれたと称した"},{"k":"history","zh":"康熙年間派人拜謁長白山後，清朝把它封為山神，每年春秋兩次祭祀","en":"After Kangxi sent envoys in 1677, the Qing deified Changbai Mountain and held rites every spring and autumn.","ja":"康熙帝が使者を送った後、清は長白山を神として封じ、毎年春秋に祭った"},{"k":"history","zh":"698 年大祚榮在今敦化一帶的東牟山建國，這就是後來的渤海國","en":"In 698 Dae Jo-yeong founded the kingdom later known as Balhae at Mount Dongmou near today's Dunhua.","ja":"698年、大祚栄が今の敦化付近の東牟山で国を建て、これがのちの渤海国になった"},{"k":"history","zh":"集安的高句麗「將軍墳」是七層階梯狀石墓，有「東方金字塔」之稱","en":"Ji'an's Goguryeo 'General's Tomb', a seven-tier stepped stone tomb, is nicknamed the 'Pyramid of the East'.","ja":"集安にある高句麗の「将軍塚」は七段の階段状石墓で、「東方のピラミッド」と呼ばれる"},{"k":"people","zh":"抗日將領楊靖宇 1940 年在此犧牲，胃裡只有草根和棉絮，當地縣名後來改為紀念他","en":"General Yang Jingyu died fighting Japan here in 1940 with only grass roots in his stomach; a county now bears his name.","ja":"抗日将軍・楊靖宇は1940年にここで戦死、胃には草の根と綿しかなく、県名に名が残る"},{"k":"people","zh":"韓國詩人尹東柱 1917 年生於延邊龍井，1945 年死在福岡監獄","en":"Korean poet Yun Dong-ju was born in Longjing here in 1917 and died in Fukuoka Prison in 1945.","ja":"韓国の詩人・尹東柱は1917年に龍井で生まれ、1945年に福岡刑務所で亡くなった"},{"k":"people","zh":"北韓建國領導人金日成，少年時曾在省內的毓文中學就讀","en":"North Korea's founding leader Kim Il-sung studied at Yuwen Middle School here as a youth.","ja":"北朝鮮の建国指導者・金日成は、少年時代にここの毓文中学で学んだ"},{"k":"origin","zh":"延邊舊稱「間島」，原指朝鮮移民渡圖們江時當作地標的一塊沙洲","en":"Yanbian's old name 'Jiandao' (Gando) first meant a Tumen River sandbar that Korean migrants used as a landmark.","ja":"延辺の旧称「間島」は、朝鮮移民が目印にした図們江の中州の名に由来する"},{"k":"history","zh":"1909 年日清簽訂協約，日本承認圖們江北岸的間島屬於中國","en":"In the 1909 Gando Convention, Japan recognized the Gando region north of the Tumen as Chinese territory.","ja":"1909年の間島協約で、日本は図們江北岸の間島を清の領土と認めた"},{"k":"history","zh":"1948 年國共內戰中省會被圍困約 150 天，估計十幾萬平民餓死","en":"In 1948 the capital was besieged for about 150 days in the Civil War; an estimated 150,000 civilians starved.","ja":"1948年の国共内戦で省都は約150日包囲され、十数万人の市民が餓死したとされる"},{"k":"history","zh":"1946 到 1948 年國共兩軍在四平反覆爭奪，前後打了四次戰役","en":"Between 1946 and 1948, Nationalist and Communist forces fought four separate battles for Siping here.","ja":"1946〜48年、国共両軍は四平をめぐって4度も戦った"},{"k":"brand","zh":"總部在省會的車廠 1958 年推出第一輛「紅旗」轎車，次年就用在國慶閱兵","en":"The first Hongqi limousine came out in 1958 from a carmaker based in the capital and was used in national parades.","ja":"省都に本社を置く工場が1958年に初の高級車「紅旗」を造り、国慶節の閲兵に使われた"},{"k":"festival","zh":"省內朝鮮族的「農樂舞」，2009 年由中國申報列入聯合國非物質文化遺產","en":"The farmers' dance (Nongak) of the Korean-Chinese here was inscribed on UNESCO's list by China in 2009.","ja":"朝鮮族の「農楽舞」は2009年、中国の申請でユネスコ無形文化遺産に登録された"},{"k":"life","zh":"省會的路面電車 1941 年開通，是中國少數保存至今的老電車系統","en":"The capital's tram system, opened in 1941, is one of the few historic tram networks preserved in China.","ja":"省都の路面電車は1941年開業で、中国でも数少ない現存する古い路線だ"},{"k":"origin","zh":"省會的名字源自 1800 年嘉慶帝在伊通河東岸設的「○○廳」","en":"The capital's name dates to 1800, when the Jiaqing Emperor set up a sub-prefecture on the Yitong River.","ja":"省都の名は、1800年に嘉慶帝が伊通河東岸に置いた「○○庁」に由来する"}],
"CN-JS":[{"k":"origin","zh":"名字取自清初兩個府的首字：一個是省會，另一個以古典園林聞名","en":"Its name joins the first characters of two Qing prefectures: the capital's, and one famed for classical gardens.","ja":"名は清初の二つの府の頭文字から。一つは省都、もう一つは古典庭園で名高い町"},{"k":"people","zh":"《西遊記》的作者吳承恩是淮安人","en":"Wu Cheng'en, author of Journey to the West, was a native of Huai'an.","ja":"『西遊記』の作者・呉承恩は淮安の人"},{"k":"work","zh":"連雲港的花果山，被公認為《西遊記》孫悟空老家花果山的原型","en":"Huaguo Mountain in Lianyungang is widely accepted as the model for Sun Wukong's home in Journey to the West.","ja":"連雲港の花果山は、『西遊記』で孫悟空が生まれた花果山のモデルとされる"},{"k":"sport","zh":"13 個市各組一隊的業餘城市足球聯賽在 2025 年爆紅，單場湧入 6 萬多人","en":"An amateur league with one team from each of 13 cities went viral in 2025, drawing crowds of over 60,000.","ja":"13市が1チームずつ出すアマチュア都市サッカーリーグが2025年に大ブーム、観客6万人超も"},{"k":"festival","zh":"秦淮燈會從除夕一路辦到正月十八，號稱「天下第一燈會」","en":"The Qinhuai Lantern Fair runs from New Year's Eve to the 18th of the first lunar month, billed as the best under heaven.","ja":"秦淮灯会は大晦日から正月18日まで続き、「天下第一の灯会」と称される"},{"k":"symbol","zh":"揚州的市花是瓊花，傳說隋煬帝開大運河就是為了去看它","en":"Yangzhou's city flower is the qionghua; legend says Emperor Yang of Sui dug the Grand Canal to go and see it.","ja":"揚州の市の花は瓊花。隋の煬帝は瓊花を見たくて大運河を開いたという伝説がある"},{"k":"life","zh":"紫砂壺用的紫砂泥產自宜興丁蜀鎮，這種泥礦十分罕見","en":"The purple clay for zisha teapots is mined around Dingshu in Yixing, a very rare kind of deposit.","ja":"紫砂急須に使う紫砂泥は宜興の丁蜀鎮で採れる、非常に珍しい粘土"},{"k":"record","zh":"鄭和七下西洋，都是從太倉的劉家港出發","en":"Zheng He set out on all seven of his great voyages from Liujiagang in Taicang.","ja":"鄭和の七度の大航海は、太倉の劉家港から出発した"},{"k":"record","zh":"中國地勢最低平的省份，全省最高點海拔只有約 624 公尺","en":"It is China's flattest province; its highest point is only about 624 m above sea level.","ja":"中国で最も平坦な省で、最高地点は標高約624メートルしかない"},{"k":"record","zh":"張謇 1905 年在南通創辦博物苑，是第一座由中國人自辦的公共博物館","en":"Nantong Museum, founded by Zhang Jian in 1905, was the first public museum set up by a Chinese founder.","ja":"張謇が1905年に南通に創設した博物苑は、中国人が独自に作った初の公共博物館だ"},{"k":"people","zh":"失明後仍東渡日本、建立唐招提寺的鑑真和尚是揚州人","en":"Jianzhen, the blind monk who reached Japan in 753 and founded Tōshōdai-ji, came from Yangzhou.","ja":"失明しながら753年に来日し、唐招提寺を開いた鑑真は揚州の出身だ"},{"k":"work","zh":"張繼名詩《楓橋夜泊》裡「夜半鐘聲到客船」，鐘聲來自寒山寺","en":"The midnight bell in Zhang Ji's famous Tang poem about mooring at Maple Bridge rings from Hanshan Temple here.","ja":"張継の詩『楓橋夜泊』の「夜半の鐘声」は、ここの寒山寺の鐘だ"},{"k":"legend","zh":"相傳寒山寺的唐代古鐘流落日本，1906 年另鑄了新鐘補上","en":"Legend says Hanshan Temple's Tang-era bell ended up in Japan; a replacement was cast in 1906.","ja":"寒山寺の唐代の鐘は日本に渡ったと伝わり、1906年に新しい鐘が鋳造された"},{"k":"symbol","zh":"1986 年從倫敦 7 家動物園引進 39 頭麋鹿到大豐，重建族群","en":"In 1986, 39 Père David's deer from seven London zoos were brought to Dafeng here to rebuild the herd.","ja":"1986年、ロンドンの7つの動物園から39頭のシフゾウが大豊に移された"},{"k":"food","zh":"1949 年中華人民共和國的「開國第一宴」，端出的是淮揚菜","en":"The 1949 founding banquet of the People's Republic served Huaiyang cuisine from this province.","ja":"1949年の建国祝賀の宴「開国第一宴」では、淮揚料理が出された"},{"k":"food","zh":"淮揚菜講究刀工，名菜「文思豆腐」要把嫩豆腐切成細絲","en":"Huaiyang cooking prizes knife skills: Wensi tofu is soft tofu cut into fine threads.","ja":"淮揚料理は包丁さばきを重んじ、「文思豆腐」は柔らかい豆腐を細切りにする"},{"k":"legend","zh":"《白蛇傳》中白娘子「水漫金山」的金山寺，在鎮江","en":"In the Legend of the White Snake, Lady White floods Jinshan Temple — which stands in Zhenjiang.","ja":"『白蛇伝』で白娘子が水を溢れさせた金山寺は、鎮江にある"},{"k":"nature","zh":"鎮江的金山原本是長江中的島，清末泥沙淤積才和南岸連在一起","en":"Zhenjiang's Jinshan hill was once an island in the Yangtze, joined to the south bank by silt in the late Qing.","ja":"鎮江の金山はもと長江の中の島で、清末に土砂がたまり南岸とつながった"},{"k":"legend","zh":"宜興人周處殺了南山猛虎、長橋蛟龍，最後改掉自己這「第三害」","en":"Zhou Chu of Yixing slew a tiger and a river dragon, then reformed himself — the third 'scourge'.","ja":"宜興の周処は虎と蛟を退治し、最後に「三害」の一つだった自分を改めた"},{"k":"people","zh":"瞎子阿炳是無錫人，名曲《二泉映月》到 1950 年才錄音留存","en":"Blind musician Abing came from Wuxi; his famous erhu piece was only recorded in 1950.","ja":"盲目の音楽家・阿炳は無錫の人で、名曲『二泉映月』は1950年に録音された"},{"k":"sport","zh":"2014 年第二屆夏季青年奧運在省會舉行，是中國首次舉辦青奧","en":"The capital hosted the 2014 Summer Youth Olympics, the first Youth Olympic Games held in China.","ja":"2014年、第2回夏季ユース五輪が省都で開かれた。中国初のユース五輪だ"},{"k":"people","zh":"西楚霸王項羽出生在下相，也就是今天的宿遷","en":"Xiang Yu, the Hegemon-King of Western Chu, was born in Xiaxiang, today's Suqian.","ja":"西楚の覇王・項羽は下相、今の宿遷の出身だ"},{"k":"people","zh":"受過「胯下之辱」、留下「一飯千金」典故的韓信是淮陰人","en":"Han Xin, who once crawled between a bully's legs and later repaid a meal a thousandfold, was from Huaiyin.","ja":"「股くぐり」の屈辱で知られる名将・韓信は淮陰の出身だ"},{"k":"work","zh":"張藝謀電影《金陵十三釵》以 1937 年省會的大屠殺為背景","en":"Zhang Yimou's The Flowers of War (2011), starring Christian Bale, is set during the 1937 massacre in the capital.","ja":"クリスチャン・ベール主演の張芸謀監督作（2011年）は、1937年の省都での大虐殺が舞台だ"},{"k":"record","zh":"1934 年建成的紫金山天文台，1955 到 1983 年間發現了 149 顆小行星","en":"Purple Mountain Observatory, founded in 1934, discovered 149 minor planets between 1955 and 1983.","ja":"1934年設立の紫金山天文台は、1955〜83年に149個の小惑星を発見した"},{"k":"people","zh":"留下約 40 萬字遊記的明代旅行家徐霞客，就出生在這裡","en":"Ming travel writer Xu Xiake, whose diaries run to about 404,000 characters, was born here.","ja":"約40万字の旅行記を残した明代の旅行家・徐霞客は、ここの出身だ"},{"k":"history","zh":"太平天國 1853 年攻下省會，改名「天京」當首都直到 1864 年","en":"The Taiping rebels took the capital in 1853 and made it their 'Heavenly Capital' until 1864.","ja":"太平天国は1853年に省都を占領し、1864年まで「天京」として首都にした"},{"k":"history","zh":"1912 年元旦，孫中山在省會宣誓就任中華民國臨時大總統","en":"On 1 January 1912, Sun Yat-sen was sworn in here as provisional president of the Republic of China.","ja":"1912年元日、孫文は省都で中華民国臨時大総統に就任した"},{"k":"history","zh":"1842 年鴉片戰爭的和約，在省會江面上的英艦「康華麗號」上簽訂","en":"The treaty ending the First Opium War was signed in 1842 aboard HMS Cornwallis, anchored off the capital.","ja":"1842年、アヘン戦争の講和条約は省都沖の英艦コーンウォリス号で調印された"},{"k":"people","zh":"《紅樓夢》作者曹雪芹生在省會，家族三代主管當地的皇家織造","en":"Cao Xueqin, author of Dream of the Red Chamber, was born in the capital, where his family ran the imperial textiles.","ja":"『紅楼夢』の作者・曹雪芹は省都で生まれ、一族は三代にわたり皇室の織物を監督した"},{"k":"food","zh":"揚州炒飯相傳是清代揚州知府伊秉綬的發明，在澳洲叫 special fried rice","en":"Yangzhou fried rice is credited to Qing prefect Yi Bingshou; in Australia it's called 'special fried rice'.","ja":"揚州炒飯は清代の揚州知府・伊秉綬が考案したとされる"},{"k":"origin","zh":"省會的名字意為「南方的首都」，1368 年明朝開國時才正式定名","en":"The capital's name, meaning 'Southern Capital', was formally adopted in 1368, the first year of the Ming.","ja":"省都の名は「南の都」の意で、明が建国した1368年に正式に定められた"}],
"CN-JX":[{"k":"people","zh":"《牡丹亭》作者、明代劇作家湯顯祖的故鄉（臨川）","en":"Hometown (Linchuan) of Tang Xianzu, the Ming playwright of The Peony Pavilion.","ja":"『牡丹亭』の作者、明の劇作家・湯顕祖の故郷（臨川）"},{"k":"people","zh":"寫下「人生自古誰無死，留取丹心照汗青」的文天祥是這裡人","en":"Home of Wen Tianxiang, who wrote: 'Since ancient times, who has not died? Let my loyal heart shine in history.'","ja":"「人生古より誰か死無からん、丹心を留取して汗青を照らさん」の文天祥はここの人"},{"k":"work","zh":"《水滸傳》開頭，洪太尉在這裡的龍虎山打開伏魔殿，放走108個魔星","en":"In the opening of Water Margin, Marshal Hong opens the Hall of Subduing Demons on Mount Longhu here, freeing 108 spirits.","ja":"『水滸伝』冒頭、洪太尉がここの龍虎山で伏魔殿を開き、108の魔星を解き放つ"},{"k":"record","zh":"南部有座城市號稱「世界鎢都」","en":"A city in its south is nicknamed the 'World Capital of Tungsten'.","ja":"南部には「世界のタングステンの都」と呼ばれる都市がある"},{"k":"record","zh":"新中國的第一架飛機、第一輛摩托車、第一枚海防導彈都誕生在這裡","en":"The PRC's first airplane, first motorcycle and first coastal-defense missile were all made here.","ja":"新中国初の飛行機、オートバイ、沿岸防衛ミサイルはいずれもここで生まれた"},{"k":"life","zh":"明清時大批居民遷往湖南、湖北，史稱「○○填湖廣」","en":"In the Ming and Qing, so many people moved from here to Hunan and Hubei that it was called '___ Fills Huguang'.","ja":"明清期に大勢の住民が湖南・湖北へ移り住み、「○○填湖広」と呼ばれた"},{"k":"record","zh":"德興銅礦是亞洲最大的露天銅礦","en":"The Dexing copper mine here is Asia's largest open-pit copper mine.","ja":"徳興銅山はアジア最大の露天掘り銅山"},{"k":"people","zh":"寫《天工開物》、被李約瑟稱為「中國的狄德羅」的宋應星是宜春人","en":"Song Yingxing, author of Tiangong Kaiwu whom Needham called China's Diderot, was born in Yichun here.","ja":"『天工開物』を著し「中国のディドロ」と称された宋応星は○○の宜春生まれ。"},{"k":"people","zh":"宋四家之一、開創一個以本省為名之詩派的黃庭堅，出身這裡","en":"Huang Tingjian, a Song calligraphy master who founded a poetry school named for this province, came from here.","ja":"宋の四大書家の一人で、この省の名を冠した詩派を開いた黄庭堅は○○の出身。"},{"k":"people","zh":"明朝宗室後裔、清初畫家八大山人（朱耷），1626 年生於省會","en":"Bada Shanren, a Ming royal descendant turned painter, was born in this province's capital in 1626.","ja":"明の皇族の末裔で清初の画家・八大山人（朱耷）は、1626年に省都で生まれた。"},{"k":"people","zh":"14 歲就被宋真宗賜「同進士出身」的神童詞人晏殊，是臨川人","en":"Yan Shu, the child prodigy granted jinshi status at 14 by Emperor Zhenzong, was born in Linchuan here.","ja":"14歳で宋の真宗から同進士出身を賜った神童・晏殊は○○の臨川生まれ。"},{"k":"people","zh":"南宋詩人楊萬里是吉水人，以「小荷才露尖尖角」等清新詩句聞名","en":"Southern Song poet Yang Wanli, known for his fresh nature verse, was from Jishui here.","ja":"南宋の詩人・楊万里は○○の吉水の人で、清新な自然詩で知られる。"},{"k":"work","zh":"白居易 816 年被貶到潯陽（今九江）時，寫下長詩〈琵琶行〉","en":"Bai Juyi wrote Song of the Pipa in 816 while exiled to Xunyang, today's Jiujiang here.","ja":"白居易は816年、潯陽（今の九江）に左遷されていた時に「琵琶行」を書いた。"},{"k":"origin","zh":"瓷都景德鎮的名字取自北宋真宗的年號，1004 年起使用","en":"The porcelain capital Jingdezhen is named after Song Emperor Zhenzong's era name, adopted in 1004.","ja":"磁都・景徳鎮の名は北宋真宗の元号に由来し、1004年から使われている。"},{"k":"origin","zh":"省會的名字從西漢沿用至今，取「昌大南疆、南方昌盛」之意","en":"The capital's name, used since the Western Han, means 'may the south prosper'.","ja":"省都の名は前漢以来のもので、「南方の繁栄」を願う意味がある。"},{"k":"origin","zh":"省會古稱「豫章」，相傳因城南門長著大樟樹而得名","en":"The capital's old name Yuzhang is said to come from a great camphor tree at its south gate.","ja":"省都の古称「豫章」は、南門に大きなクスノキがあったことに由来するという。"},{"k":"symbol","zh":"全世界九成以上的白鶴，冬天都到這裡的鄱陽湖一帶過冬","en":"Over 90% of the world's Siberian cranes winter in the Poyang Lake basin here.","ja":"世界のソデグロヅルの9割以上が、○○の鄱陽湖一帯で冬を越す。"},{"k":"record","zh":"萬年縣仙人洞出土約兩萬年前的陶片，發表時被稱為世界已知最早的陶器","en":"Xianren Cave in Wannian yielded 20,000-year-old pottery, announced as the earliest known in the world.","ja":"万年県の仙人洞から約2万年前の土器片が出土し、世界最古の土器と発表された。"},{"k":"record","zh":"省會在唐代有洪州窯，被認為是中國青瓷的發源地之一","en":"The capital's Tang-era Hongzhou kilns are considered one of the birthplaces of Chinese celadon.","ja":"省都にあった唐代の洪州窯は、中国の青磁の発祥地の一つとされる。"},{"k":"history","zh":"四大書院之一的白鹿洞書院，名字來自唐代李渤在此隱居養白鹿","en":"White Deer Grotto Academy, one of the Four Great Academies, is named for the white deer Li Bo kept there.","ja":"四大書院の一つ白鹿洞書院の名は、唐の李渤がここで白鹿を飼ったことに由来する。"},{"k":"life","zh":"樟樹市官方稱號是「中國藥都」，以大量的中藥材交易聞名","en":"Zhangshu here is officially called the Medicine Capital of China for its herbal trade.","ja":"○○の樟樹市は「中国薬都」が公式の呼び名で、生薬の取引で知られる。"},{"k":"life","zh":"佛教寺院的僧團規約，據說就起源於這裡的宜春","en":"Buddhist monastic codes for temple life are said to have originated in Yichun here.","ja":"仏教寺院の僧団規則は、○○の宜春で生まれたと言われる。"},{"k":"food","zh":"臺灣常見的「三杯雞」，相傳源自這裡的寧都","en":"Three-cup chicken, a Taiwanese favorite, is said to trace back to Ningdu here.","ja":"台湾でおなじみの「三杯鶏」は、○○の寧都が発祥とされる。"},{"k":"history","zh":"1363 年朱元璋在鄱陽湖大敗兵力三倍的陳友諒，為明朝開國奠基","en":"In 1363 Zhu Yuanzhang crushed Chen Youliang's far larger fleet on Poyang Lake, paving the way to the Ming.","ja":"1363年、朱元璋は鄱陽湖で3倍の兵力の陳友諒を破り、明建国の基礎を築いた。"},{"k":"history","zh":"1519 年寧王在此起兵叛亂，王陽明只用 41 天就將他擒獲","en":"In 1519 the Prince of Ning rebelled here; Wang Yangming captured him in just 41 days.","ja":"1519年に寧王がここで反乱を起こしたが、王陽明がわずか41日で捕らえた。"},{"k":"history","zh":"1934 年紅軍從于都出發，踏上長征","en":"In 1934 the Red Army set out on the Long March from Yudu County here.","ja":"1934年、紅軍は○○の于都から長征に出発した。"},{"k":"history","zh":"南唐曾在 960 年遷都到這裡的省會，但只維持了約四個月","en":"Southern Tang moved its capital to this province's capital around 960, but only for about four months.","ja":"南唐は960年ごろ都を省都へ移したが、わずか4か月ほどで終わった。"},{"k":"legend","zh":"晉代道士許遜相傳斬蛟治水、立鐵柱鎮妖，各地萬壽宮都供奉他","en":"Jin-era Taoist Xu Xun is said to have slain flood dragons and pinned demons with an iron pillar here.","ja":"晋の道士・許遜は蛟を斬って治水し鉄柱で妖を鎮めたと伝わり、万寿宮に祀られる。"},{"k":"nature","zh":"省內最大的湖平常約 3500 平方公里，2012 年乾旱時一度縮到約 200 平方公里","en":"The province's biggest lake, usually about 3,500 km², shrank to roughly 200 km² in the 2012 drought.","ja":"省内最大の湖は普段約3500平方キロだが、2012年の干ばつで約200平方キロまで縮んだ。"}],
"CN-LN":[{"k":"origin","zh":"1929年由奉天省改為現名，取意一條大河的流域永保安寧","en":"Renamed from Fengtian Province in 1929; the new name expresses the wish that a great river's basin be at peace forever.","ja":"1929年に奉天省から改称。新しい名は「ある大河の流域が永遠に安らかであれ」の意"},{"k":"sport","zh":"大連萬達（實德）足球隊曾8度奪得中國頂級聯賽冠軍","en":"Dalian Wanda (later Shide) won China's top football league 8 times, once the country's most successful club.","ja":"大連万達（のち実徳）は中国サッカー最上位リーグで8回優勝した"},{"k":"people","zh":"小品天王趙本山出生在這裡的鐵嶺開原","en":"Comedy sketch star Zhao Benshan was born in Kaiyuan, Tieling, here.","ja":"コントの大御所・趙本山はここの鉄嶺市開原の生まれ"},{"k":"work","zh":"電視劇《鄉村愛情》的象牙山村，就在這裡的開原拍攝","en":"The TV series Country Love was filmed in Xiangyashan Village, Kaiyuan, here.","ja":"ドラマ『郷村愛情』の象牙山村は、ここの開原で撮影された"},{"k":"people","zh":"長期控制東北的奉系軍閥首領張作霖，出生於這裡的海城","en":"Zhang Zuolin, the Fengtian warlord who long ruled the Northeast, was born in Haicheng here.","ja":"長く東北を支配した奉天軍閥の首領・張作霖は、ここの海城の生まれ"},{"k":"record","zh":"中國大陸海岸線的最北起點——鴨綠江口在這裡","en":"Mainland China's coastline begins in the north at the mouth of the Yalu River, here.","ja":"中国大陸の海岸線の北の起点・鴨緑江の河口がここにある"},{"k":"record","zh":"中國第一款噴射戰鬥機殲-5，在省會的飛機廠造出","en":"China's first jet fighter, the J-5, was built at the aircraft factory in its capital.","ja":"中国初のジェット戦闘機J-5は、省都の航空機工場で造られた"},{"k":"life","zh":"渤海上有座「蛇島」，島上唯一的爬蟲類是特有的蛇島蝮","en":"A 'Snake Island' in the Bohai Sea is home to just one reptile: the endemic Shedao pit viper.","ja":"渤海に浮かぶ「蛇島」にいる爬虫類は、固有種のシャダオマムシただ一種"},{"k":"history","zh":"牛河梁遺址的「女神廟」出土鑲玉眼的泥塑女神頭像，距今約五千年","en":"Niuheliang's 'Goddess Temple' yielded a clay female head with jade-inlaid eyes, about 5,000 years old.","ja":"牛河梁の「女神廟」から、玉をはめた目の女神の土製頭像が出土した（約5千年前）"},{"k":"symbol","zh":"紅山文化的「玉豬龍」，在這裡的牛河梁遺址出土","en":"Hongshan culture jade 'pig dragons' were unearthed at Niuheliang here.","ja":"紅山文化の「玉猪竜」は、ここの牛河梁遺跡から出土した"},{"k":"record","zh":"1996年公布的中華龍鳥，是第一種被發現帶有羽毛狀細絲的恐龍","en":"Sinosauropteryx, announced in 1996, was the first known dinosaur with feather-like filaments.","ja":"1996年発表のシノサウロプテリクスは、羽毛状の繊維を持つ初めての恐竜だった"},{"k":"record","zh":"北票一帶出土的古果約1.25億年前，被認為是最早的開花植物之一","en":"Archaefructus from around Beipiao, about 125 million years old, is proposed as one of the earliest flowers.","ja":"北票一帯の約1.25億年前のアルカエフルクトゥスは、最古級の被子植物とされる"},{"k":"history","zh":"桓仁的五女山城被視為高句麗最早的都城，2004年列入世界遺產","en":"Wunü Mountain in Huanren is seen as Goguryeo's first capital and became World Heritage in 2004.","ja":"桓仁の五女山城は高句麗最初の都とされ、2004年に世界遺産となった"},{"k":"origin","zh":"旅順的英文舊名 Port Arthur，取自1860年測量港口的英國海軍上尉亞瑟","en":"Lüshun's old name Port Arthur honours Lt. William Arthur, who surveyed the harbour in 1860.","ja":"旅順の英名ポート・アーサーは、1860年に港を測量した英海軍のアーサー大尉に由来"},{"k":"origin","zh":"「旅順」意為旅途平順，1371年為紀念明軍遠征順利而命名","en":"The name Lüshun, 'smooth journeys', was given in 1371 to mark a successful Ming expedition.","ja":"「旅順」は旅路が順調の意で、1371年に明軍の遠征成功を記念して名付けられた"},{"k":"origin","zh":"省會的名稱意為「瀋水的北岸」，瀋水就是城南的渾河","en":"Its capital's name means 'north bank of the Shen River', today's Hun River.","ja":"省都の名は「瀋水の北岸」の意で、瀋水は街の南を流れる渾河のこと"},{"k":"history","zh":"1905年日俄戰爭的奉天會戰，是當時史上最大規模的陸戰","en":"The 1905 Battle of Mukden was the largest land battle ever fought up to that time.","ja":"1905年の奉天会戦は、当時史上最大の陸上戦だった"},{"k":"history","zh":"清初修築「柳條邊」，用來阻止漢人移入東北其他地方","en":"The early Qing built the Willow Palisade here to keep Han Chinese out of the rest of the Northeast.","ja":"清初に築かれた「柳条辺」は、漢人が東北の奥地へ入るのを防ぐためのもの"},{"k":"history","zh":"國共內戰三大戰役中的第一場，就在這裡一帶開打","en":"The first major campaign of the Chinese Civil War's three great battles was fought here.","ja":"国共内戦の三大戦役のうち最初の戦役は、この一帯で戦われた"},{"k":"people","zh":"「少帥」張學良生於此，後在臺灣長年遭軟禁，2001年在夏威夷以百歲辭世","en":"The 'Young Marshal' Zhang Xueliang, born here, was long held in Taiwan and died at 100 in Hawaii.","ja":"「少帥」張学良はここで生まれ、台湾で長く軟禁され、2001年ハワイで百歳で没した"},{"k":"people","zh":"雷鋒1962年在撫順因公殉職，墓也在撫順","en":"Lei Feng died on duty in Fushun in 1962, and his tomb is there.","ja":"雷鋒は1962年に撫順で殉職し、墓も撫順にある"},{"k":"sport","zh":"飛豹籃球隊從2021-22球季起，連續三季奪得CBA總冠軍","en":"Its Flying Leopards won three straight CBA titles, from 2021–22 through 2023–24.","ja":"フライング・レオパーズは2021-22年から3季連続でCBA王者となった"},{"k":"brand","zh":"萬達集團1988年在大連創立，2012年收購美國連鎖影院AMC","en":"Wanda Group, founded in Dalian in 1988, bought US cinema chain AMC in 2012.","ja":"1988年に大連で創業した万達グループは、2012年に米映画館チェーンAMCを買収した"},{"k":"symbol","zh":"斑海豹棲息在渤海北端的海灣，2021年升為國家一級保護動物","en":"Spotted seals live in the bay at the Bohai Sea's north end; China raised them to class I protection in 2021.","ja":"ゴマフアザラシは渤海北端の湾にすみ、2021年に国家一級保護動物となった"},{"k":"life","zh":"全中國滿族人口數與比例都最高的省份","en":"It has China's largest Manchu population, both in number and share.","ja":"満州族の人口・比率ともに中国で最も高い省"},{"k":"record","zh":"鐵、菱鎂礦、鑽石與硼的蘊藏量都居全國之冠","en":"It holds China's largest deposits of iron, magnesite, diamond and boron.","ja":"鉄・マグネサイト・ダイヤモンド・ホウ素の埋蔵量がいずれも全国一"},{"k":"history","zh":"東漢末公孫度在此割據，政權到238年被曹魏所滅","en":"Gongsun Du's semi-independent state here was destroyed by Cao Wei in 238.","ja":"後漢末に公孫度が築いた半独立政権は、238年に曹魏に滅ぼされた"},{"k":"brand","zh":"1929年中國第一輛國產汽車「民生」牌卡車，在省會問世","en":"China's first domestically made vehicle, the Minsheng truck, was built in its capital in 1929.","ja":"1929年、中国初の国産自動車「民生」トラックが省都で誕生した"},{"k":"food","zh":"當地菜系多用山珍野味，烹調以「扒」的技法著稱","en":"Its regional cuisine uses mountain game and is famed for the 'pa' braising technique.","ja":"ここの料理は山の幸を使い、「扒（パー）」という煮込み技法で知られる"},{"k":"sport","zh":"2013年第十二屆全運會的主場館，是省會的奧林匹克體育中心","en":"Its capital's Olympic Sports Center was the main venue of the 12th National Games in 2013.","ja":"2013年の第12回全国運動会は、省都のオリンピックスポーツセンターが主会場"},{"k":"nature","zh":"最高峰是花脖子山，海拔1336公尺","en":"Its highest point is Mount Huabozi at 1,336 m.","ja":"最高峰は標高1336mの花脖子山"},{"k":"history","zh":"明代在此擴建的邊牆多是挖壕溝、堆土堤而成，比長城省錢","en":"The Ming frontier wall here, expanded in 1467–68, was mostly an earthen dike with moats.","ja":"明が1467〜68年に拡張したこの地の辺牆は、主に堀と土塁でできていた"}],
"CN-MO":[{"k":"origin","zh":"葡萄牙文名稱一般認為源自當時居民口中的「媽閣」","en":"Its Portuguese name is commonly said to come from 'Ma Kok' (A-Ma's place), as locals called it.","ja":"ポルトガル語名は、当時の住民が口にした「媽閣」に由来するとされる"},{"k":"record","zh":"旅遊塔233公尺的高空彈跳，獲金氏世界紀錄認證為世界最高的彈跳設施","en":"Its tower's 233 m bungee jump is recognized by Guinness as the world's highest bungee jump facility.","ja":"タワーの高さ233mのバンジージャンプは、ギネス認定の世界一高いバンジー施設"},{"k":"people","zh":"孫中山曾在這裡的鏡湖醫院行醫，是該院第一位西醫","en":"Sun Yat-sen practised at Kiang Wu Hospital here, becoming its first Western-medicine doctor.","ja":"孫文はここの鏡湖医院で診療し、同院初の西洋医となった"},{"k":"work","zh":"《007：空降危機》中，龐德追查一枚籌碼，來到這裡的賭場","en":"In Skyfall, James Bond follows a casino chip to a casino here.","ja":"『007 スカイフォール』で、ボンドはカジノチップを追ってここのカジノへ"},{"k":"symbol","zh":"區旗是綠底上一朵白色蓮花、一座大橋和海水，上方有五顆星","en":"Its flag shows a white lotus above a bridge and water on a green field, under five stars.","ja":"旗は緑地に白い蓮の花と橋と海、その上に五つの星"},{"k":"life","zh":"土生葡人的克里奧爾語「土生土語」被聯合國教科文組織列為極度瀕危","en":"Patuá, the creole of the local Eurasian community, is rated critically endangered by UNESCO.","ja":"土生ポルトガル人のクレオール語「パトゥア」は、ユネスコが極めて深刻な危機言語に指定"},{"k":"record","zh":"2013年起，位在橫琴島上的大學新校區劃歸這裡管轄","en":"Since 2013, a university's new campus on Hengqin Island has been under its jurisdiction.","ja":"2013年から、横琴島にある大学の新キャンパスがここの管轄になった"},{"k":"life","zh":"中國唯一以葡萄牙文為官方語言之一的地區","en":"The only part of China with Portuguese as an official language.","ja":"中国で唯一、ポルトガル語を公用語の一つとする地域"},{"k":"history","zh":"1622 年擊退來犯的荷蘭艦隊，6 月 24 日後來成為當地的「城市日」","en":"A Dutch attack was repulsed in June 1622; the 24th later became City Day here.","ja":"1622年にオランダ艦隊の攻撃を撃退し、6月24日はのちに「市の日」となった"},{"k":"legend","zh":"相傳 1622 年耶穌會神父從大炮台開炮，命中荷軍火藥扭轉戰局","en":"Legend says a Jesuit priest fired a cannon from Monte Fort in 1622, blowing up the Dutch gunpowder.","ja":"1622年、イエズス会の神父がモンテの砦から撃った砲弾がオランダ軍の火薬を爆発させたと伝わる"},{"k":"people","zh":"《黃河大合唱》的作曲家冼星海，1905 年在這裡出生","en":"Xian Xinghai, composer of the Yellow River Cantata, was born here in 1905.","ja":"『黄河大合唱』の作曲家冼星海は、1905年にここで生まれた"},{"k":"people","zh":"鄭觀應在自家的鄭家大屋寫成《盛世危言》","en":"Reformer Zheng Guanying finished 'Words of Warning in Times of Prosperity' at his family's Mandarin's House here.","ja":"鄭観応は自宅の鄭家大屋で『盛世危言』を書き上げた"},{"k":"record","zh":"1594 年創立的聖保祿學院號稱東亞第一所西式大學，1835 年毀於大火","en":"St. Paul's College, founded in 1594, claimed to be East Asia's first Western university; fire destroyed it in 1835.","ja":"1594年創立の聖パウロ学院は東アジア初の西洋式大学とされ、1835年に火災で焼失した"},{"k":"people","zh":"第一位來華的基督新教傳教士馬禮遜，葬在這裡的基督教墳場","en":"Robert Morrison, the first Protestant missionary to China, is buried in the Old Protestant Cemetery here.","ja":"中国初のプロテスタント宣教師モリソンは、ここの旧プロテスタント墓地に眠る"},{"k":"nature","zh":"靠填海，土地從 19 世紀末約 10 平方公里，擴大到 2018 年約 33 平方公里","en":"Land reclamation tripled its area, from about 10 km² in the late 1800s to about 33 km² by 2018.","ja":"埋め立てで面積は19世紀末の約10平方キロから2018年には約33平方キロへと3倍に"},{"k":"history","zh":"二戰期間日本始終沒有佔領這裡，大致尊重葡萄牙的中立","en":"Japan never occupied it during WWII, largely respecting Portugal's neutrality.","ja":"第二次世界大戦中、日本はここを占領せず、ポルトガルの中立をおおむね尊重した"},{"k":"history","zh":"1945 年美軍因這裡賣燃料給日本而轟炸，1950 年賠給葡萄牙 2000 多萬美元","en":"The US bombed it in 1945 over fuel sales to Japan, then paid Portugal over US$20 million in 1950.","ja":"1945年、日本への燃料販売を理由に米軍が爆撃し、1950年にポルトガルへ2000万ドル超を賠償した"},{"k":"history","zh":"1887 年的中葡條約讓葡萄牙取得永久管治權，但未經中國同意不得轉讓","en":"An 1887 treaty gave Portugal perpetual rule here but barred ceding it without China's consent.","ja":"1887年の条約でポルトガルは永久統治権を得たが、中国の同意なく他国へ譲れないとされた"},{"k":"history","zh":"1966 年的「一二·三事件」造成 8 人死亡，之後葡萄牙失去完全控制權","en":"After the 12-3 incident of 1966, which left 8 dead, Portugal lost full control of the colony.","ja":"1966年の「一二・三事件」で8人が死亡し、以後ポルトガルは完全な統治力を失った"},{"k":"nature","zh":"最高點在路環的疊石塘山，海拔只有約 170 公尺","en":"Its highest point, Coloane Alto, is only about 170 m above sea level.","ja":"最高地点は路環の畳石塘山で、標高はわずか約170m"},{"k":"nature","zh":"2015 年國務院把約 85 平方公里的海域劃歸這裡管轄","en":"In 2015 China's State Council placed about 85 km² of sea under its jurisdiction.","ja":"2015年、国務院は約85平方キロの海域をここの管轄とした"},{"k":"people","zh":"「賭王」何鴻燊 1961 年取得賭牌，壟斷這裡的博彩業約 40 年","en":"'King of Gambling' Stanley Ho won the gaming monopoly in 1961 and held it for about 40 years.","ja":"「カジノ王」スタンレー・ホーは1961年に賭博の独占権を得て、約40年握り続けた"},{"k":"brand","zh":"何鴻燊 1970 年開設葡京酒店，成為他旗下賭場的旗艦","en":"Stanley Ho opened the Hotel Lisboa casino in 1970 as his flagship here.","ja":"1970年、スタンレー・ホーは旗艦となるホテル・リスボアを開業した"},{"k":"legend","zh":"傳說葡萄牙詩人賈梅士在這裡的岩洞寫下史詩《盧濟塔尼亞人之歌》的一部分","en":"Tradition says Portuguese poet Camões wrote part of Os Lusíadas in a grotto here, later named after him.","ja":"ポルトガルの詩人カモンイスは、ここの洞窟で『ウズ・ルジアダス』の一部を書いたと伝わる"},{"k":"people","zh":"賈梅士 1562 年被任命為這裡的「死者與失蹤者財產管理官」","en":"Camões was appointed here in 1562 as Superintendent for the Dead and Missing.","ja":"カモンイスは1562年、ここの「死者・行方不明者財産管理官」に任命された"},{"k":"festival","zh":"每年農曆四月初八，魚行的人邊喝酒邊舞木雕龍頭龍尾，稱為「醉龍」","en":"On the 8th day of the 4th lunar month, fish traders drink and dance with a wooden dragon head and tail.","ja":"旧暦4月8日、魚業の人々が酒を飲みながら木彫りの龍の頭と尾を手に舞う「酔龍」"},{"k":"food","zh":"2017 年獲選聯合國教科文組織「美食之都」，是成都、順德之後中國第三個","en":"UNESCO named it a City of Gastronomy in 2017, China's third after Chengdu and Shunde.","ja":"2017年にユネスコ食文化創造都市に選ばれた。中国では成都、順徳に次ぐ3例目"},{"k":"food","zh":"土生葡人菜源自葡萄牙水手的妻子，用本地食材模仿歐洲菜色","en":"The local Creole cuisine began with Portuguese sailors' wives recreating European dishes from local ingredients.","ja":"土生ポルトガル人料理は、ポルトガル人船乗りの妻が地元食材で欧州料理を再現したのが始まり"},{"k":"work","zh":"聞一多 1925 年的組詩《七子之歌》，第一首寫的就是○○","en":"The first poem of Wen Yiduo's 1925 cycle 'Song of the Seven Sons' is about this place.","ja":"聞一多が1925年に書いた連作詩『七子之歌』の第一首は、ここを詠んだもの"},{"k":"history","zh":"1844 年中美《望廈條約》在望廈村的觀音堂簽訂","en":"The 1844 Treaty of Wanghia between the US and Qing China was signed at the Kun Iam Temple here.","ja":"1844年の米清間の望廈条約は、ここの観音堂で調印された"},{"k":"record","zh":"1576 年設立的天主教教區，最初管轄範圍包括中國、日本與越南","en":"The Catholic diocese founded here in 1576 originally covered China, Japan and Vietnam.","ja":"1576年に設置されたカトリック教区は、当初中国・日本・ベトナムまで管轄した"}],
"CN-NM":[{"k":"origin","zh":"首府的名字在蒙古語中意為「青色的城」","en":"Its capital's name means 'Blue City' in Mongolian.","ja":"区都の名はモンゴル語で「青い城」の意"},{"k":"festival","zh":"夏天舉辦那達慕，比摔跤、賽馬、射箭","en":"In summer it holds Naadam, with wrestling, horse racing and archery.","ja":"夏にはナーダムが開かれ、相撲・競馬・弓射を競う"},{"k":"people","zh":"王昭君墓「青塚」在這裡，據說秋天四周草枯，墓上的草卻仍青綠","en":"Wang Zhaojun's tomb, the 'Green Mound', is here; its grass is said to stay green when all around withers in autumn.","ja":"王昭君の墓「青塚」がある。秋に周りが枯れても墓の草だけは青いという"},{"k":"work","zh":"北朝民歌《敕勒歌》「天蒼蒼，野茫茫，風吹草低見牛羊」唱的敕勒川在這裡","en":"The plain of the old folk song 'Song of Chile' ('wind bends the grass, revealing cattle and sheep') is here.","ja":"「天蒼蒼、野茫茫、風吹き草低れて牛羊見る」と『敕勒歌』に歌われた敕勒川がここ"},{"k":"people","zh":"以《天堂》聞名的歌手騰格爾，出生於這裡的鄂托克旗","en":"Singer Tengger, known for 'Paradise', was born in Otog Banner here.","ja":"『天堂』で知られる歌手テンゲルは、ここのオトク旗の生まれ"},{"k":"life","zh":"街上的招牌常見由上往下直寫的蒙古文","en":"Street signs here often show Mongolian script, written vertically from top to bottom.","ja":"街の看板には、上から下へ縦書きするモンゴル文字がよく見られる"},{"k":"record","zh":"東北部的呼倫貝爾市面積約25萬平方公里，和英國差不多大","en":"Hulunbuir, a city in its northeast, covers about 253,000 km², roughly the size of the UK.","ja":"北東部のフルンボイル市は面積約25万km²で、イギリスとほぼ同じ広さ"},{"k":"life","zh":"境內有鄂溫克族、鄂倫春、莫力達瓦達斡爾族三個民族自治旗","en":"It has autonomous banners for the Evenk, Oroqen and Daur peoples.","ja":"エヴェンキ族・オロチョン族・ダウール族の自治旗がある"},{"k":"history","zh":"首府由俺答汗建立，明朝在1575年賜名「歸化」","en":"Its capital was founded by Altan Khan; the Ming renamed the town Guihua in 1575.","ja":"区都はアルタン・ハーンが築き、明は1575年に「帰化」と名付けた"},{"k":"legend","zh":"傳說黑水城守將哈拉巴特爾被明軍截斷河水，1372年全軍覆沒","en":"Legend says Khara-Khoto's general Khara Bator fell in 1372 after Ming troops diverted its river.","ja":"黒水城の将軍ハラ・バートルは1372年、明軍に川をせき止められ滅びたと伝わる"},{"k":"history","zh":"1908到1909年，俄國探險家科茲洛夫在黑水城挖出2000多件西夏文典籍","en":"In 1908–09, Russian explorer Kozlov dug up over 2,000 Tangut books at Khara-Khoto.","ja":"1908〜09年、ロシアのコズロフが黒水城で西夏文の書物2000点以上を発掘した"},{"k":"origin","zh":"額濟納旗的名字來自黑水城，也就是馬可波羅筆下的 Etzina","en":"Ejin Banner is named after Khara-Khoto, the 'Etzina' of Marco Polo.","ja":"エジナ旗の名は黒水城に由来し、それはマルコ・ポーロの記す「エツィナ」である"},{"k":"record","zh":"巴丹吉林沙漠的必魯圖峰，被稱為世界最高的固定沙丘","en":"Bilutu Peak in the Badain Jaran Desert is called the world's tallest stationary dune.","ja":"バダインジャラン砂漠のビルトゥ峰は、世界一高い固定砂丘とされる"},{"k":"nature","zh":"巴丹吉林的沙丘會發出高達105分貝的轟鳴，沙漠裡還有上百座湖泊","en":"Badain Jaran's dunes can boom at up to 105 decibels, and over 100 lakes dot the desert.","ja":"バダインジャランの砂丘は最大105デシベルで鳴り、砂漠には100以上の湖がある"},{"k":"record","zh":"名叫「酒泉」的衛星發射中心，部分設施其實位在這裡的額濟納旗","en":"Part of the Jiuquan Satellite Launch Center actually lies in Ejin Banner here.","ja":"酒泉衛星発射センターの施設の一部は、実はここのエジナ旗にある"},{"k":"work","zh":"尚賈克・阿諾的《狼圖騰》講1969年學生下放草原，在烏拉蓋附近拍攝","en":"Jean-Jacques Annaud's 'Wolf Totem', about a student sent here in 1969, was filmed near Wulagai.","ja":"アノー監督『神なるオオカミ』は1969年に草原へ送られた学生の物語で、ウラガイ付近で撮影"},{"k":"people","zh":"1929年為反抗墾荒奪地而起義的嘎達梅林，事蹟被唱成民歌傳頌","en":"Gada Meiren led a 1929–31 revolt against land seizures; a folk song about him became famous.","ja":"1929年に開墾による土地収奪に抗して蜂起したガダメイリンは、民謡で歌い継がれる"},{"k":"nature","zh":"根河曾測得攝氏零下58度的低溫，年均溫約零下3.6度","en":"Genhe has recorded −58.0 °C, and its annual mean temperature is about −3.6 °C.","ja":"根河では−58.0℃を記録し、年平均気温は約−3.6℃"},{"k":"life","zh":"根河的敖魯古雅鄉，仍有少數鄂溫克族人放養馴鹿","en":"In Genhe's Aoluguya township, a few Evenk herders still keep reindeer.","ja":"根河のオルグヤ郷では、今も少数のエヴェンキ族がトナカイを飼っている"},{"k":"record","zh":"呼倫湖是中國北方第一大湖、全國第四大淡水湖","en":"Hulun Lake is the largest lake in northern China and the country's 4th largest freshwater lake.","ja":"フルン湖は中国北方最大の湖で、全国4位の淡水湖"},{"k":"sport","zh":"莫力達瓦達斡爾族自治旗，被國家民委認定為中國曲棍球重鎮","en":"Morin Dawa Daur Banner is officially recognized as a center of hockey in China.","ja":"モリンダワ・ダウール族自治旗は、中国のホッケーの拠点と公認されている"},{"k":"history","zh":"1937年德王在日本扶植下宣布成立政權，轄綏遠與察哈爾","en":"In 1937 Prince Demchugdongrub declared a Japanese-backed regime covering Suiyuan and Chahar.","ja":"1937年、徳王は日本の後ろ盾で綏遠・チャハルを治める政権を宣言した"},{"k":"history","zh":"1969年本區大片土地被劃給鄰近省份，1979年才恢復","en":"In 1969 much of the region was divided among neighbouring provinces; this was reversed in 1979.","ja":"1969年に大部分が隣接する省に分割され、1979年に元に戻された"},{"k":"life","zh":"二連浩特是國際列車口岸，因兩國軌距不同，火車要在此更換轉向架","en":"At Erenhot, international trains change bogies because the two countries' rail gauges differ.","ja":"二連浩特では両国の軌間が違うため、国際列車が台車を交換する"},{"k":"symbol","zh":"二連浩特出土許多恐龍化石，公路上有兩隻蜥腳類恐龍搭成的拱門","en":"Dinosaur-rich Erenhot built a highway arch of two sauropods in 2006.","ja":"恐竜化石で知られる二連浩特には、2頭の竜脚類が形作るアーチが道路に立つ"},{"k":"people","zh":"首任自治區主席烏蘭夫，後來當上國家副主席","en":"Ulanhu, the region's founding chairman, later became Vice President of the PRC.","ja":"初代自治区主席のウランフは、のちに国家副主席となった"},{"k":"food","zh":"當地把奶製品叫「白食」，把肉類叫「紅食」","en":"Here dairy products are called 'white food' and meat 'red food'.","ja":"ここでは乳製品を「白い食べ物」、肉を「赤い食べ物」と呼ぶ"},{"k":"food","zh":"「炒米」是牧民主食之一，與餡餅、包子並列","en":"Fried millet (chaomi) is a staple here, alongside meat pies and buns.","ja":"炒った黍「炒米」は、餡餅や包子と並ぶ牧畜民の主食"},{"k":"sport","zh":"張小平2008年奪得奧運拳擊81公斤級金牌，是本區首位奧運獎牌得主","en":"Boxer Zhang Xiaoping won 2008 Olympic gold at 81 kg, the region's first Olympic medalist.","ja":"張小平は2008年五輪ボクシング81kg級で金を取り、ここ初の五輪メダリストとなった"},{"k":"symbol","zh":"西部荒漠出產阿拉善雙峰駝，也有野駱駝","en":"Its western deserts are home to Alxa Bactrian camels and wild camels.","ja":"西部の砂漠にはアラシャンのフタコブラクダや野生のラクダがいる"},{"k":"brand","zh":"鄂爾多斯集團等多家羊絨公司設在這裡","en":"Cashmere makers such as the Erdos Group are based here.","ja":"オルドス・グループなど多くのカシミヤ企業がここにある"},{"k":"record","zh":"全世界面積超過100萬平方公里的一級行政區中，這裡人口最多","en":"Of all first-level divisions over 1 million km² worldwide, it has the largest population.","ja":"面積100万km²を超える世界の一級行政区の中で、最も人口が多い"},{"k":"festival","zh":"牧民與鄂倫春、鄂溫克族有在石堆「敖包」前祭祀的傳統","en":"Local herders and the Oroqen and Evenk keep the custom of worship at 'oboo' stone cairns.","ja":"牧畜民やオロチョン族、エヴェンキ族には石積み「オボー」を祀る伝統がある"}],
"CN-NX":[{"k":"origin","zh":"元朝滅西夏後命名，取「夏地安寧」之意","en":"Named in the Yuan dynasty after the fall of Western Xia, meaning 'may the Xia lands be at peace'.","ja":"元代、西夏の滅亡後に「夏の地が安らかであれ」との意で名付けられた"},{"k":"work","zh":"《紅高粱》《大話西遊》《新龍門客棧》都在這裡的同一座影城拍攝","en":"Red Sorghum, A Chinese Odyssey and New Dragon Gate Inn were all filmed at the same film studio here.","ja":"『紅いコーリャン』『チャイニーズ・オデッセイ』『ドラゴン・イン』は皆ここの同じ撮影所で撮られた"},{"k":"work","zh":"2021年電視劇《山海情》，講述這裡西海固的移民靠福建對口幫扶脫貧","en":"The 2021 drama Minning Town tells how migrants from Xihaigu here escaped poverty with Fujian's help.","ja":"2021年のドラマ『山海情』は、福建の支援で貧困を脱したここ西海固の移民の物語"},{"k":"people","zh":"作家張賢亮1954年來到這裡，後來創辦了一座知名影視城","en":"Writer Zhang Xianliang came here in 1954 and later founded a famous film studio.","ja":"作家・張賢亮は1954年にここへ来て、のちに有名な撮影所を創設した"},{"k":"life","zh":"有「紅黃藍白黑」五寶：枸杞、甘草、賀蘭石、灘羊皮、髮菜","en":"Its 'five treasures' are red, yellow, blue, white and black: goji, licorice, Helan stone, Tan sheepskin and fat choy.","ja":"「紅黄藍白黒」の五宝は、クコ・甘草・賀蘭石・灘羊の毛皮・髪菜"},{"k":"life","zh":"南部的西海固，曾被聯合國機構評為全球最不適宜人類居住的地區之一","en":"Its southern Xihaigu area was once named by a UN agency one of the least habitable places on Earth.","ja":"南部の西海固は、国連機関に世界で最も人が住みにくい地域の一つとされた"},{"k":"record","zh":"黃河邊有108座喇嘛塔排成等腰三角形，是中國最大的喇嘛塔群","en":"By the Yellow River, 108 lama stupas form an isosceles triangle, China's largest group of its kind.","ja":"黄河のほとりに108基のラマ塔が二等辺三角形に並ぶ、中国最大のラマ塔群"},{"k":"record","zh":"中衛山羊是全世界唯一的白色裘皮山羊","en":"The Zhongwei goat bred here is the world's only white fur-pelt goat.","ja":"中衛ヤギは、世界で唯一の白い毛皮用ヤギ"},{"k":"history","zh":"安史之亂時，太子李亨 756 年在這裡的靈州即位，就是唐肅宗","en":"During the An Lushan Rebellion, Crown Prince Li Heng took the throne here at Lingzhou in 756.","ja":"安史の乱のさなか、皇太子李亨は756年にここの霊州で即位し、唐の粛宗となった"},{"k":"history","zh":"1209 年蒙古軍圍攻西夏都城，築堤引水，結果堤防潰決反淹了自己的營地","en":"Besieging the Western Xia capital in 1209, the Mongols built a dike that broke and flooded their own camp.","ja":"1209年に西夏の都を囲んだモンゴル軍は堤を築いたが、決壊して自軍の陣営が水浸しになった"},{"k":"history","zh":"成吉思汗 1227 年在征討西夏期間去世，一說死於境內的六盤山","en":"Genghis Khan died in 1227 during his Western Xia campaign, by one account in the Liupan Mountains here.","ja":"チンギス・カンは1227年、西夏遠征中に六盤山で死去したとされる"},{"k":"history","zh":"1920 年海原大地震死亡超過 23 萬人，是中國最慘重的地震之一","en":"The 1920 Haiyuan earthquake here killed over 230,000 people, one of China's deadliest quakes.","ja":"1920年の海原地震は23万人以上が死亡し、中国で最も犠牲の大きい地震のひとつ"},{"k":"history","zh":"1954 年曾被併入甘肅省，1958 年才重新成立為自治區","en":"It was merged into Gansu in 1954 and only re-created as an autonomous region in 1958.","ja":"1954年に甘粛省へ併合され、1958年に自治区として復活した"},{"k":"history","zh":"1928 年設省，是民國時期「塞北四省」之一","en":"Made a province in 1928, it was one of the Republic of China's 'four provinces north of the frontier'.","ja":"1928年に省が置かれ、民国期の「塞北四省」のひとつとなった"},{"k":"history","zh":"明朝萬曆三大征之一的哱拜之亂，就發生在這裡","en":"The Pubei rebellion, one of the Ming Wanli emperor's three great campaigns, broke out here.","ja":"明の万暦三大征のひとつ、哱拝の乱はここで起きた"},{"k":"history","zh":"固原的須彌山石窟始鑿於北魏末年，最大的大佛樓高 20.6 公尺","en":"The Xumishan Grottoes in Guyuan date from the late Northern Wei; the biggest Buddha niche is 20.6 m tall.","ja":"固原の須弥山石窟は北魏末に開削が始まり、最大の大仏楼は高さ20.6mある"},{"k":"life","zh":"1489 年開封猶太人的經卷毀於洪水，是由這裡和寧波的猶太社群送去替代的","en":"After a 1489 flood, Jewish communities here and in Ningbo sent replacement scrolls to the Kaifeng Jews.","ja":"1489年に開封のユダヤ人の経典が洪水で失われると、ここと寧波のユダヤ人が代わりを送った"},{"k":"people","zh":"西夏開國君主李元昊下「禿髮令」，命全國人民三天內剃去頭頂頭髮，違者可處死","en":"Western Xia founder Li Yuanhao ordered all subjects to shave their crowns within three days or face death.","ja":"西夏の建国者・李元昊は「禿髪令」を出し、3日以内に頭頂を剃らない者は死罪とした"},{"k":"people","zh":"明太祖第十六子慶王朱㮵受封在此，寫下當地第一本完備的地方志","en":"Zhu Zhan, Prince of Qing and 16th son of the Hongwu Emperor, lived here and wrote its first full gazetteer.","ja":"明太祖の第16子・慶王朱㮵はここに封じられ、当地初の本格的な地方志を著した"},{"k":"brand","zh":"西夏文由大臣野利仁榮設計，1036 年開始在官方使用","en":"The Tangut script, credited to official Yeli Renrong, was put into government use in 1036.","ja":"西夏文字は高官・野利仁栄が考案したとされ、1036年に公用化された"},{"k":"record","zh":"1990 年在賀蘭山拜寺口方塔出土的西夏佛經，被認為是已知最早的木活字印本","en":"A Tangut sutra found in 1990 at the Baisikou pagoda is considered the earliest known wooden movable-type print.","ja":"1990年に拝寺口方塔から出た西夏の仏典は、知られる最古の木活字印刷物とされる"},{"k":"record","zh":"境內歷代長城總長約 1507.9 公里，被稱為「長城博物館」","en":"Great Wall sections here total about 1,507.9 km, earning it the nickname 'museum of the Great Wall'.","ja":"域内の歴代の長城は総延長約1507.9kmで、「長城博物館」と呼ばれる"},{"k":"nature","zh":"南部的六盤山是涇河與渭河的分水嶺，森林覆蓋率超過八成","en":"The Liupan Mountains in the south divide the Jing and Wei rivers and are over 80% forested.","ja":"南部の六盤山は涇河と渭河の分水嶺で、森林被覆率は8割を超える"},{"k":"nature","zh":"賀蘭山東側陡峭，與平原落差可達兩千公尺，也是季風氣候的分界線","en":"The Helan Mountains rise up to 2,000 m sheer above the plain and mark the edge of the monsoon climate.","ja":"賀蘭山の東側は平原から最大2000mそそり立ち、モンスーン気候の境界線でもある"},{"k":"nature","zh":"首府古有「七十二連湖」之說，至今仍有近 200 處自然湖泊","en":"The regional capital was once called the city of '72 linked lakes' and still has nearly 200 natural lakes.","ja":"首府はかつて「七十二連湖」と呼ばれ、今も200近い天然の湖がある"},{"k":"life","zh":"賀蘭山區的煤層長期自燃，估計已燒掉數億噸煤","en":"Coal seams in the Helan Mountains have long burned underground, consuming hundreds of millions of tons.","ja":"賀蘭山の炭層は長年自然発火を続け、数億トンの石炭が燃えたと推計される"},{"k":"origin","zh":"「賀蘭山」之名來自《晉書》記載的匈奴「賀蘭部」，部落名後來變成山名","en":"The Helan Mountains take their name from the Helan, a Xiongnu tribe recorded in the Book of Jin.","ja":"賀蘭山の名は『晋書』に記された匈奴の「賀蘭部」に由来する"},{"k":"origin","zh":"城市「吳忠」的名字，據說來自明代一位叫吳忠的屯長","en":"The city of Wuzhong is said to be named after Wu Zhong, a Ming-era garrison farm chief.","ja":"呉忠市の名は、明代の屯長・呉忠という人物に由来するとされる"},{"k":"brand","zh":"賀蘭山區出產的太西煤低灰低硫，被稱為「煤中之王」","en":"Taixi anthracite from the Helan Mountains is known internationally as the 'king of coal'.","ja":"賀蘭山で採れる太西炭は「石炭の王」と呼ばれる"},{"k":"brand","zh":"2011 年中法葡萄酒盲品賽，前四名全被賀蘭山東麓的酒包辦","en":"At a 2011 Sino-French blind tasting, the top four wines all came from the eastern Helan foothills.","ja":"2011年の中仏ワイン・ブラインドテイスティングで、上位4位を賀蘭山東麓のワインが独占した"},{"k":"food","zh":"1730 年英國阿蓋爾公爵把這裡的枸杞引進英國","en":"In 1730 the Duke of Argyll introduced goji from here to Britain.","ja":"1730年、英国のアーガイル公がここのクコを英国に持ち込んだ"},{"k":"life","zh":"「五寶」的黑寶原本是髮菜，2000 年禁採後改成了太西煤","en":"Its 'black treasure' used to be fat choy moss, replaced by Taixi coal after harvesting was banned in 2000.","ja":"「五宝」の黒宝はもとは髪菜だったが、2000年の採取禁止後は太西炭に替わった"},{"k":"life","zh":"俗諺「天下黃河富○○」，說的是黃河灌溉的平原特別富饒","en":"A proverb says the Yellow River enriches this place above all others along its course.","ja":"「天下の黄河は○○を富ます」という言い回しがある"}],
"CN-QH":[{"k":"origin","zh":"省名來自境內的中國最大內陸鹹水湖","en":"Named after the lake inside it, China's largest inland saltwater lake.","ja":"省名は省内にある中国最大の内陸塩湖に由来する"},{"k":"sport","zh":"每年夏天舉辦繞著一座大湖騎的國際公路自行車賽","en":"Each summer it hosts an international road cycling race that loops around a huge lake.","ja":"毎年夏、大きな湖を巡る国際自転車ロードレースが開かれる"},{"k":"work","zh":"王洛賓改編的名曲《在那遙遠的地方》，相傳誕生於這裡的金銀灘草原","en":"Wang Luobin's song 'In That Faraway Place' is said to have been born on the Jinyintan grassland here.","ja":"王洛賓の名曲『遥かな地にて』は、ここの金銀灘草原で生まれたと伝わる"},{"k":"people","zh":"藏傳佛教格魯派創始人宗喀巴出生在這裡，出生地後來建了塔爾寺","en":"Tsongkhapa, founder of the Gelug school, was born here; Kumbum Monastery now stands on the spot.","ja":"ゲルク派の開祖ツォンカパはここで生まれ、その地にタール寺が建てられた"},{"k":"festival","zh":"土族慶豐收的「納頓節」，前後長達63天","en":"The Tu people's Nadun harvest festival here runs for about 63 days.","ja":"土族の収穫祭「ナトゥン節」は63日間も続く"},{"k":"record","zh":"民和喇家遺址出土約4000年前的麵條，是已知世界最古老的麵條","en":"The Lajia site here yielded 4,000-year-old noodles, the oldest known in the world.","ja":"民和の喇家遺跡から約4000年前の麺が出土し、世界最古の麺とされる"},{"k":"record","zh":"循化縣是全國唯一單一撒拉族的民族自治地方","en":"Xunhua is China's only autonomous county solely for the Salar people.","ja":"循化県は全国で唯一のサラール族単独の自治地方"},{"k":"work","zh":"金馬獎最佳影片《可可西里》，講述巡山隊追捕藏羚羊盜獵者的故事","en":"Golden Horse Best Film Kekexili: Mountain Patrol follows rangers here hunting Tibetan antelope poachers.","ja":"金馬奨作品賞の『ココシリ』は、チベットカモシカの密猟者を追う巡回隊の物語"},{"k":"people","zh":"第十世班禪喇嘛 1938 年出生在○○的循化一帶","en":"The 10th Panchen Lama was born here in 1938, in today's Xunhua County.","ja":"第10世パンチェン・ラマは1938年、○○の循化一帯で生まれた"},{"k":"people","zh":"藏族導演萬瑪才旦出生於○○貴德縣，以《塔洛》拿下金馬獎最佳改編劇本","en":"Tibetan director Pema Tseden, born in Guide County here, won a Golden Horse for the script of Tharlo.","ja":"チベット族の監督ペマ・ツェテンは○○の貴徳県出身で、『タルロ』で金馬奨脚色賞を受賞した"},{"k":"people","zh":"民國時期統治這裡的回族軍閥馬步芳強力推動植樹，擅自砍樹甚至可能被處死","en":"Warlord Ma Bufang, who ruled here, enforced tree planting; cutting a tree without permission could mean death.","ja":"民国期にここを支配した回族軍閥・馬歩芳は植林を強行し、無断で木を切ると死刑もあり得た"},{"k":"history","zh":"1932 年西藏軍隊東侵，被馬步芳的回族部隊擊退","en":"In 1932 a Tibetan army invaded and was driven back by Ma Bufang's Muslim troops.","ja":"1932年に東進してきたチベット軍は、馬歩芳の回族部隊に撃退された"},{"k":"history","zh":"1928 年才正式建省，到 1949 年都由回族軍閥「馬家軍」統治","en":"Made a province only in 1928, it was ruled by the Hui warlords of the Ma clique until 1949.","ja":"1928年に省となり、1949年まで回族軍閥「馬家軍」が支配した"},{"k":"history","zh":"鮮卑人建立的吐谷渾王國統治這裡約三百年，以大湖畔的伏俟城為都","en":"The Xianbei-founded Tuyuhun kingdom ruled here for about 300 years, with its capital Fuqi near the great lake.","ja":"鮮卑系の吐谷渾が約300年ここを治め、大湖のほとりの伏俟城を都とした"},{"k":"history","zh":"11 世紀吐蕃王族後裔唃廝囉在此建立青唐政權，都城在今日的省會","en":"In the 11th century Gyalsé, a Tibetan royal descendant, founded the Tsongkha kingdom with its seat at today's capital.","ja":"11世紀、吐蕃王家の末裔・唃廝囉がここに青唐政権を建て、今の省都を都とした"},{"k":"history","zh":"2010 年玉樹發生強烈地震，造成兩千六百多人死亡","en":"The 2010 Yushu earthquake here killed about 2,700 people.","ja":"2010年の玉樹地震では2600人以上が亡くなった"},{"k":"symbol","zh":"瀕危的普氏原羚野外只剩○○湖周邊還找得到","en":"The endangered Przewalski's gazelle survives in the wild only around one big lake here.","ja":"絶滅危惧種のプルジェワルスキーガゼルは、野生では○○湖の周辺にしか残っていない"},{"k":"symbol","zh":"湟魚（裸鯉）幾乎沒有鱗片，每年逆流四五十公里到淡水河產卵","en":"The nearly scaleless naked carp lives only here and swims 40-50 km up freshwater streams to spawn.","ja":"ほとんど鱗のない湟魚（裸鯉）は、毎年40〜50キロ川をさかのぼって産卵する"},{"k":"legend","zh":"《隋書》說湖中小山冬天放上母馬可得「龍種」，生出日行千里的「○○驄」","en":"The Book of Sui says mares left on the lake's islet in winter bore 'dragon' foals that ran 1,000 li a day.","ja":"『隋書』は、冬に湖の小島へ雌馬を放つと「龍種」を得て、一日千里を走る「○○驄」が生まれたと記す"},{"k":"legend","zh":"撒拉族傳說祖先牽著白駱駝、帶著《古蘭經》從撒馬爾罕遷來，那部經書至今仍保存在街子清真寺","en":"Salar legend says ancestors came from Samarkand with a white camel and a Quran, still kept at Jiezi Mosque.","ja":"サラール族の祖先は白いラクダとコーランを携えてサマルカンドから来たと伝わり、その経典は街子モスクに残る"},{"k":"nature","zh":"藏族聖山阿尼瑪卿曾被飛行員誤估超過九千公尺，一度被懷疑比聖母峰還高","en":"Sacred Amne Machin was once overestimated by pilots at 30,000 ft, raising hopes it topped Everest.","ja":"チベットの聖山アムニェ・マチェンはかつて9000m超と誤認され、エベレストより高いかと疑われた"},{"k":"nature","zh":"柴達木盆地極度乾燥，被中國地質調查局當成火星的模擬場地","en":"The arid Qaidam Basin is used by China's Geological Survey as a Mars analog for rover testing.","ja":"極度に乾燥したツァイダム盆地は、中国地質調査局が火星の模擬地として使っている"},{"k":"nature","zh":"○○湖的鳥島春夏聚集十萬隻以上的候鳥","en":"Bird Island on the big lake here hosts over 100,000 migratory birds in spring and summer.","ja":"○○湖の鳥島には、春から夏にかけて10万羽以上の渡り鳥が集まる"},{"k":"origin","zh":"格爾木的名字來自蒙古語（衛拉特語），意思是「河流」","en":"The city name Golmud comes from Oirat Mongolian and means 'rivers'.","ja":"ゴルムドの名はオイラト語に由来し、「川」を意味する"},{"k":"origin","zh":"石油鎮「冷湖」得名於蒙古語的「冷的湖」，1954 年發現石油前荒無人煙","en":"Oil town Lenghu is named after a Mongolian 'cold lake'; nobody lived there before oil was found in 1954.","ja":"石油の町・冷湖はモンゴル語の「冷たい湖」に由来し、1954年に石油が見つかるまで無人だった"},{"k":"origin","zh":"英文舊稱 Koko Nor 來自蒙古語，意思是「藍色的湖」","en":"Its old English name Koko Nor comes from Mongolian for 'blue lake'.","ja":"英語の旧称ココノールはモンゴル語で「青い湖」を意味する"},{"k":"festival","zh":"大通縣老爺山每年農曆六月初六舉行花兒會，2006 年列入國家級非遺","en":"Datong's Laoye Mountain holds a 'hua'er' folk song fair on the 6th day of the 6th lunar month.","ja":"大通県の老爺山では毎年旧暦6月6日に民謡「花児」の歌会が開かれる"},{"k":"festival","zh":"宗喀巴出生地的大寺每年正月十五展出僧侶用酥油捏成的「酥油花」","en":"Each 15th of the first lunar month, the monastery at Tsongkhapa's birthplace shows sculptures made of butter.","ja":"ツォンカパ生誕地の大寺では毎年旧暦1月15日、僧がバターで作る「酥油花」を展示する"},{"k":"life","zh":"省會夏季均溫只有約 17～19℃，有「中國夏都」之稱","en":"With summer averages of about 17-19°C, the provincial capital is nicknamed China's 'Summer Capital'.","ja":"省都は夏の平均気温が17〜19℃ほどで、「中国の夏の都」と呼ばれる"},{"k":"life","zh":"省會的東關清真大寺從 1380 年起一直持續運作","en":"The Dongguan Mosque in the provincial capital has operated continuously since 1380.","ja":"省都の東関清真大寺は1380年から途切れることなく使われ続けている"},{"k":"life","zh":"互助土族最具代表性的傳統舞蹈是「安昭舞」","en":"The signature traditional dance of the Huzhu Tu (Monguor) people is the Anzhao dance.","ja":"互助の土族を代表する伝統舞踊は「安昭舞」である"},{"k":"record","zh":"不算自治區的話，是中國面積最大的省","en":"Excluding autonomous regions, this is the largest province in China by area.","ja":"自治区を除けば、中国で面積が最も大きい省である"},{"k":"work","zh":"在中國文化中，這裡最常與周穆王西遊的古書《穆天子傳》聯想在一起","en":"In Chinese culture this province is most associated with the Tale of King Mu, Son of Heaven.","ja":"中国文化では、周の穆王の西遊を描く古書『穆天子伝』と最も結びつけられる地である"},{"k":"brand","zh":"柴達木盆地 1954 年開始找石油，1955 年鑽下第一口油井","en":"Oil exploration in the Qaidam Basin began in 1954, and its first oil well was drilled in 1955.","ja":"ツァイダム盆地の石油探査は1954年に始まり、1955年に最初の油井が掘られた"}],
"CN-SC":[{"k":"symbol","zh":"省會市花是木芙蓉，五代時城牆遍植芙蓉，因而別稱「蓉城」","en":"Its capital's flower is the cotton rose; a 10th-century ruler lined the walls with it, hence 'Hibiscus City'.","ja":"省都の市花はフヨウ。五代の君主が城壁に植えたことから「蓉城」と呼ばれる"},{"k":"work","zh":"杜甫在這裡的草堂住了近四年，寫下《茅屋為秋風所破歌》","en":"Du Fu lived nearly four years in a thatched cottage here, writing 'My Thatched Hut Torn by the Autumn Wind'.","ja":"杜甫はここの草堂に約4年住み、「茅屋秋風の破る所と為る歌」を書いた"},{"k":"festival","zh":"自貢燈會被譽為「天下第一燈」","en":"The Zigong Lantern Festival here is hailed as 'the finest lanterns under heaven'.","ja":"自貢の灯籠祭りは「天下第一の灯」と称される"},{"k":"life","zh":"當地戲曲有一門絕技「變臉」，演員能瞬間換上不同臉譜","en":"Its local opera features 'face-changing', where performers switch masks in an instant.","ja":"地元の伝統劇には、一瞬で面を替える秘技「変面」がある"},{"k":"life","zh":"白酒名牌五糧液、瀘州老窖、劍南春都產自這裡","en":"Famous baijiu brands Wuliangye, Luzhou Laojiao and Jiannanchun all come from here.","ja":"白酒の銘柄、五糧液・瀘州老窖・剣南春はいずれもここ産"},{"k":"people","zh":"蘇軾與父親蘇洵、弟弟蘇轍「三蘇」的故鄉（眉山）","en":"Home (Meishan) of the 'Three Su': Su Shi, his father Su Xun and his brother Su Zhe.","ja":"蘇軾と父・蘇洵、弟・蘇轍の「三蘇」の故郷（眉山）"},{"k":"record","zh":"金沙江流到這裡的宜賓之後，才開始叫「長江」","en":"The Jinsha River is only called the Yangtze after it reaches Yibin here.","ja":"金沙江はここの宜賓に至って初めて「長江」と呼ばれる"},{"k":"history","zh":"西元前316年秦國滅了古蜀與巴，這裡的物產成為秦統一天下的後盾","en":"Qin conquered the ancient kingdoms of Shu and Ba here by 316 BC, using their wealth to unify China.","ja":"紀元前316年、秦が古代の蜀と巴を滅ぼし、その豊かな物産が天下統一の支えとなった"},{"k":"history","zh":"221年劉備在此建立蜀漢，以今天的省會為都城","en":"In 221 Liu Bei founded the Shu Han state here, with today's provincial capital as its capital.","ja":"221年、劉備がここで蜀漢を建国し、現在の省都を都とした"},{"k":"history","zh":"1911年反對清廷把鐵路收歸國有的「保路運動」在此爆發，間接促成武昌起義","en":"The 1911 Railway Protection Movement erupted here, drawing Qing troops away and helping the Wuchang Uprising succeed.","ja":"1911年、鉄道国有化に反対する「保路運動」がここで起こり、武昌起義の成功を後押しした"},{"k":"record","zh":"中國首顆探月衛星嫦娥一號，2007年從這裡的西昌發射升空","en":"China's first lunar probe, Chang'e 1, lifted off from the Xichang launch center here in 2007.","ja":"中国初の月探査機「嫦娥1号」は2007年、ここの西昌衛星発射センターから打ち上げられた"},{"k":"history","zh":"1701年建成的鍊條吊橋瀘定橋，1935年長征時紅軍在此奪橋渡過大渡河","en":"Luding Bridge, a chain bridge from 1701 over the Dadu River, was seized by the Red Army in 1935.","ja":"1701年完成の鎖の吊り橋・瀘定橋は、1935年の長征で紅軍が奪取して大渡河を渡った"},{"k":"record","zh":"金沙遺址出土的金箔「太陽神鳥」，被選為中國文化遺產的標誌","en":"The 'Sun and Immortal Birds' gold foil from the Jinsha site became the logo of China's cultural heritage.","ja":"金沙遺跡から出土した金箔「太陽神鳥」は、中国の文化遺産のシンボルマークに選ばれた"},{"k":"record","zh":"省會的武侯祠同時祭祀劉備與諸葛亮，是中國唯一的君臣合祀祠廟","en":"The capital's Wuhou Shrine honors Liu Bei and Zhuge Liang together, China's only joint ruler-minister temple.","ja":"省都の武侯祠は劉備と諸葛亮を共に祀る、中国で唯一の君臣合祀の廟"},{"k":"history","zh":"蜀漢昭烈帝劉備的陵墓「惠陵」，就在省會武侯祠的園區內","en":"Huiling, the tomb of Shu Han emperor Liu Bei, lies within the capital's Wuhou Shrine grounds.","ja":"蜀漢の昭烈帝・劉備の陵墓「恵陵」は、省都の武侯祠の敷地内にある"},{"k":"record","zh":"自貢的燊海井1835年鑿成，深1001公尺，是世界第一口超過千米的深井","en":"Zigong's Shenhai Well, finished in 1835 at 1,001 m deep, was the world's first well over 1,000 m.","ja":"自貢の燊海井は1835年に完成、深さ1001mで世界初の千メートル超えの井戸とされる"},{"k":"nature","zh":"黃龍的鈣華池層層疊疊、色彩斑斕，1992年列入世界自然遺產","en":"Huanglong's terraced travertine pools in yellow, green and blue became a World Heritage Site in 1992.","ja":"黄龍では石灰華の棚田状の池が色とりどりに連なり、1992年に世界自然遺産となった"},{"k":"brand","zh":"古蜀國起源的織錦「蜀錦」，在隋唐時期沿絲路遠銷中亞與西亞","en":"Shu brocade, a silk weaving dating to the ancient Shu kingdom, reached Central and West Asia in the Sui-Tang era.","ja":"古蜀国に起源をもつ絹織物「蜀錦」は、隋唐時代にシルクロードで中央・西アジアへ渡った"},{"k":"work","zh":"傳遍華人世界的民歌《康定情歌》，原名《跑馬溜溜的山上》","en":"'Kangding Love Song', loved across the Chinese-speaking world, is a folk song from this province.","ja":"中華圏で広く愛される民謡「康定情歌」は、この地の康定に伝わる歌"},{"k":"legend","zh":"傳說古蜀王望帝死後化為杜鵑，日夜悲啼到吐血，把杜鵑花染紅","en":"Legend says Emperor Wang of ancient Shu became a cuckoo, crying until its blood dyed the azaleas red.","ja":"古蜀の望帝は死後ホトトギスとなり、血を吐くまで鳴いてツツジを赤く染めたと伝わる"},{"k":"sport","zh":"2025年第12屆世界運動會在省會舉行，是首次在中華人民共和國舉辦","en":"The 12th World Games in 2025 were held in the provincial capital, the first ever hosted in the PRC.","ja":"2025年の第12回ワールドゲームズは省都で開かれ、中国での開催は初めてだった"},{"k":"work","zh":"巴金的長篇小說《家》，以1920年代省會的大家族為舞台","en":"Ba Jin's novel 'Family' is set among a wealthy clan in this province's capital in the 1920s.","ja":"巴金の長編小説『家』は、1920年代の省都に暮らす大家族を描いた"},{"k":"people","zh":"《三國志》的作者陳壽，出身今天的南充","en":"Chen Shou, author of the 'Records of the Three Kingdoms', was born in present-day Nanchong here.","ja":"『三国志』の著者・陳寿は、現在の南充の出身"},{"k":"food","zh":"郫縣豆瓣醬常曬製三年以上，被稱為「○菜之魂」","en":"Pixian doubanjiang, often sun-fermented for over three years, is called the soul of this province's cuisine.","ja":"郫県豆板醤は3年以上天日で発酵させることも多く、「○菜の魂」と呼ばれる"},{"k":"brand","zh":"綿陽的長虹原是生產機載雷達的軍工廠，後來轉型成電視大廠","en":"Changhong in Mianyang began as a factory making airborne radar before becoming a major TV maker.","ja":"綿陽の長虹は機上レーダーを作る軍需工場から始まり、テレビの大手メーカーになった"},{"k":"food","zh":"料理講究「麻」，靠的是花椒讓舌頭發麻的效果","en":"Its cuisine prizes 'ma', the tongue-numbing tingle of the local peppercorn.","ja":"料理は「麻（マー）」を重んじ、花椒による舌のしびれが特徴"},{"k":"legend","zh":"二郎神源於灌口的地方神，相傳是李冰之子，曾助父斬蛟治水","en":"The god Erlang began as a local deity of Guankou, said to be Li Bing's son who slew a flood dragon.","ja":"二郎神は灌口の地方神が起源で、李冰の息子として蛟竜を斬り治水を助けたと伝わる"},{"k":"work","zh":"李白名句「蜀道之難，難於上青天」，形容的是通往這裡的山路","en":"Li Bai's famous line 'harder than climbing to the blue sky' describes the roads into this region.","ja":"李白の名句「蜀道の難きは青天に上るより難し」は、この地へ通じる山道を詠んだ"},{"k":"people","zh":"臨邛富家女卓文君與司馬相如私奔，後來回鄉開酒店賣酒","en":"Zhuo Wenjun of Linqiong eloped with poet Sima Xiangru, and the couple ran a wine shop to get by.","ja":"臨邛の富豪の娘・卓文君は司馬相如と駆け落ちし、酒場を開いて暮らした"},{"k":"people","zh":"中國科學院首任院長郭沫若，出生於樂山沙灣","en":"Guo Moruo, first president of the Chinese Academy of Sciences, was born in Shawan near Leshan.","ja":"中国科学院の初代院長・郭沫若は、楽山の沙湾で生まれた"},{"k":"nature","zh":"北部的若爾蓋沼澤，被認為是世界最大的高海拔沼澤區","en":"The Zoigê marshes in the north form the largest high-altitude marsh area in the world.","ja":"北部の若爾蓋湿原は、世界最大の高地湿原とされる"}],
"CN-SD":[{"k":"sport","zh":"2008年北京奧運的帆船比賽在這裡的青島舉行","en":"The sailing events of the 2008 Beijing Olympics were held in Qingdao here.","ja":"2008年北京五輪のセーリング競技は、ここの青島で行われた"},{"k":"work","zh":"《水滸傳》108條好漢聚義的梁山泊，就在這裡的梁山縣","en":"Liangshan Marsh, where the 108 heroes of Water Margin gathered, is in Liangshan County here.","ja":"『水滸伝』の108人の好漢が集った梁山泊は、ここの梁山県にある"},{"k":"people","zh":"《聊齋誌異》作者蒲松齡是這裡的淄川人","en":"Pu Songling, author of Strange Tales from a Chinese Studio, was from Zichuan here.","ja":"『聊斎志異』の作者・蒲松齢はここの淄川の人"},{"k":"festival","zh":"青島國際啤酒節自1991年起舉辦，每年吸引數百萬遊客","en":"The Qingdao International Beer Festival, held since 1991, draws millions of visitors each year.","ja":"1991年から続く青島国際ビール祭りには、毎年数百万人が訪れる"},{"k":"people","zh":"詞人李清照與辛棄疾都出身省會一帶，合稱「○○二安」","en":"Ci poets Li Qingzhao and Xin Qiji both came from around its capital and are called its 'Two An'.","ja":"詞人の李清照と辛棄疾はともに省都の出身で「○○二安」と並び称される"},{"k":"life","zh":"清末民初大批居民遷往東北謀生，俗稱「闖關東」","en":"In the late Qing and early Republic, masses migrated from here to the Northeast, known as 'Braving Guandong'.","ja":"清末から民国初め、大勢が東北へ移住した。俗に「闖関東」という"},{"k":"record","zh":"壽光是中國最大的蔬菜集散中心，被授予「蔬菜之鄉」稱號","en":"Shouguang here is China's largest vegetable distribution hub, titled 'Home of Vegetables'.","ja":"寿光は中国最大の野菜の集散地で「野菜の郷」の称号を持つ"},{"k":"people","zh":"被尊為「書聖」、寫下〈蘭亭集序〉的王羲之，生於琅琊（今臨沂）","en":"Wang Xizhi, the Sage of Calligraphy who wrote the Lantingji Xu, was born in Langya, today's Linyi.","ja":"「書聖」と称され「蘭亭序」を書いた王羲之は、琅琊（今の臨沂）の生まれ。"},{"k":"people","zh":"抗倭名將戚繼光生於濟寧，家族世襲登州（今蓬萊）的衛所職位","en":"Qi Jiguang, the Ming general who fought Japanese pirates, was born in Jining and served at Dengzhou here.","ja":"倭寇と戦った明の名将・戚継光は済寧に生まれ、登州（今の蓬萊）の世襲武官だった。"},{"k":"people","zh":"《孫子兵法》的作者孫子，傳統上認為出身春秋時的齊國","en":"Sun Tzu, author of The Art of War, is traditionally said to have come from the ancient state of Qi here.","ja":"『孫子』の著者・孫武は、伝統的に春秋時代の斉の出身とされる。"},{"k":"people","zh":"日本名演員三船敏郎出生在青島","en":"Japanese film star Toshiro Mifune was born in Qingdao.","ja":"名優・三船敏郎は青島で生まれた。"},{"k":"sport","zh":"《戰國策》記載齊國都城臨淄的居民愛踢「蹴鞠」，被視為古代足球","en":"The Zhan Guo Ce records people of Linzi, the Qi capital here, playing cuju, an ancient form of football.","ja":"『戦国策』は斉の都・臨淄の人々が古代サッカー「蹴鞠」を楽しんだと記す。"},{"k":"work","zh":"《水滸傳》武松在景陽岡打死老虎後，被陽穀縣知縣任用","en":"In Water Margin, Wu Song kills a tiger at Jingyang Ridge and is then hired by Yanggu County here.","ja":"『水滸伝』で武松は景陽岡で虎を倒し、陽穀県の知県に取り立てられる。"},{"k":"work","zh":"張藝謀電影《紅高粱》改編自莫言小說，以這裡的鄉村為舞台，1988 年獲柏林金熊獎","en":"Zhang Yimou's Red Sorghum, from Mo Yan's novel and set in a village here, won the 1988 Golden Bear.","ja":"張芸謀の『紅いコーリャン』は莫言の小説が原作で○○の農村が舞台、1988年金熊賞。"},{"k":"origin","zh":"省會的名字意思是「濟水之南」，但濟水在 19 世紀中被改道的黃河佔去","en":"The capital's name means 'south of the Ji River', a river later swallowed by the shifting Yellow River.","ja":"省都の名は「済水の南」の意味だが、済水は19世紀に流路を変えた黄河に飲み込まれた。"},{"k":"origin","zh":"煙台得名自 1398 年為警戒倭寇而建、燒狼煙報信的烽火台","en":"Yantai, 'smoke tower', is named for beacon towers built in 1398 to warn of Japanese pirates.","ja":"煙台の名は、1398年に倭寇を警戒して狼煙を上げた烽火台に由来する。"},{"k":"symbol","zh":"黃河三角洲是東方白鸛全球最重要的繁殖地","en":"The Yellow River Delta here is the world's most important breeding ground for the Oriental stork.","ja":"黄河デルタは、コウノトリにとって世界で最も重要な繁殖地だ。"},{"k":"record","zh":"齊國修築、綿延約 600 公里的齊長城，被稱為中國現存最古老的長城","en":"The 600-km Great Wall of Qi, built by the state of Qi, is called China's oldest existing great wall.","ja":"斉が築いた全長約600キロの斉長城は、現存する中国最古の長城とされる。"},{"k":"record","zh":"中國最大的半島，夾在渤海與黃海之間","en":"China's largest peninsula, lying between the Bohai and Yellow Seas, belongs to this province.","ja":"渤海と黄海の間に突き出た中国最大の半島がある。"},{"k":"record","zh":"由四個湖連成的南四湖（微山湖），是中國北方最大的淡水湖","en":"Nansi Lake, four linked lakes including Weishan Lake, is the largest freshwater lake in northern China.","ja":"四つの湖がつながった南四湖（微山湖）は、中国北部最大の淡水湖。"},{"k":"record","zh":"省會附近的四門塔，是中國唯一的隋代石塔","en":"The Four Gates Pagoda near the capital is China's only stone pagoda from the Sui dynasty.","ja":"省都近郊の四門塔は、中国で唯一の隋代の石塔。"},{"k":"food","zh":"八大菜系中，北京宮廷菜與京津、東北菜都被視為源自這裡的菜系","en":"This province's cuisine shaped Beijing's imperial cooking; Beijing and northeastern food are its branches.","ja":"八大料理のうち、北京の宮廷料理や東北料理のルーツとされる料理系統がここで生まれた。"},{"k":"food","zh":"曲阜孔子後代因地位特殊，傳下了講究多道工序的「孔府菜」","en":"Confucius's descendants in Qufu preserved Kongfu cuisine, an elaborate multi-step family cooking style.","ja":"曲阜の孔子の子孫は特別な地位から、手間をかけた「孔府料理」を伝えてきた。"},{"k":"history","zh":"巴黎和會決定把德國在青島的權益轉給日本，引爆了 1919 年五四運動","en":"The Paris Peace Conference's decision to hand Germany's Qingdao rights to Japan sparked the 1919 May Fourth Movement.","ja":"パリ講和会議が青島のドイツ権益を日本に渡すと決め、1919年の五四運動が起きた。"},{"k":"history","zh":"1897 年巨野教案中德國傳教士遇害，德國藉機佔領了膠州灣","en":"After German missionaries were killed in Juye in 1897, Germany seized Jiaozhou Bay.","ja":"1897年の巨野教案でドイツ人宣教師が殺され、ドイツはこれを口実に膠州湾を占領した。"},{"k":"history","zh":"清末的義和團，最早興起於這裡的內陸地區","en":"The Boxer movement of the late Qing first arose in the inland parts of this province.","ja":"清末の義和団は、○○の内陸部で最初に興った。"},{"k":"history","zh":"1928 年北伐途中，國民革命軍與日軍在省會爆發流血衝突","en":"In 1928, during the Northern Expedition, Nationalist and Japanese troops clashed bloodily in the capital.","ja":"1928年、北伐の途中で国民革命軍と日本軍が省都で衝突し、流血の事件となった。"},{"k":"nature","zh":"黃河夾帶的泥沙每年在出海口造出約 3240 公頃新陸地","en":"Silt from the Yellow River adds about 3,240 hectares of new land at its mouth here every year.","ja":"黄河の土砂が河口に毎年約3240ヘクタールの新しい陸地をつくっている。"},{"k":"brand","zh":"海爾的張瑞敏曾下令砸毀 76 台不合格冰箱，這家公司就誕生在青島","en":"Haier, whose boss once had 76 faulty fridges smashed with sledgehammers, was founded in Qingdao.","ja":"不良品の冷蔵庫76台をハンマーで壊させた逸話で知られるハイアールは、青島で創業。"},{"k":"brand","zh":"用驢皮熬成的中藥「阿膠」，名字來自這裡的東阿縣","en":"Ejiao, a TCM gelatin boiled from donkey hide, is named after Dong'e County here.","ja":"ロバの皮を煮詰めた漢方「阿膠」の名は、○○の東阿県に由来する。"},{"k":"legend","zh":"蓬萊的丹崖，相傳是八仙出發赴蟠桃會的地方","en":"Penglai's Dan Cliffs are said to be where the Eight Immortals set off for the Peach Banquet.","ja":"蓬萊の丹崖は、八仙が蟠桃会へ旅立った場所と伝えられる。"},{"k":"legend","zh":"替秦始皇帶三千童男童女出海求仙藥的徐福，出身齊國，傳說最後到了日本","en":"Xu Fu, who sailed with 3,000 youths to find Qin Shi Huang's elixir, came from Qi; legend says he reached Japan.","ja":"始皇帝のため童男童女3千人と不老不死の薬を探した徐福は斉の出身で、日本に渡ったとも。"}],
"CN-SH":[{"k":"origin","zh":"名稱來自吳淞江下游一條叫「○○浦」的支流","en":"Named after a tributary of the lower Wusong River called '___ Pu'.","ja":"名は呉淞江下流の支流「○○浦」に由来する"},{"k":"sport","zh":"F1中國大獎賽的賽道，形狀仿照這座城市名稱的第一個字","en":"Its F1 Chinese Grand Prix circuit is shaped like the first character of the city's name.","ja":"F1中国GPのサーキットは、この都市名の一文字目をかたどっている"},{"k":"work","zh":"周星馳電影《功夫》的故事發生在1940年代的這裡","en":"Stephen Chow's Kung Fu Hustle is set here in the 1940s.","ja":"チャウ・シンチー監督『カンフーハッスル』の舞台は1940年代のここ"},{"k":"festival","zh":"這裡的國際電影節，是華語地區唯一獲國際製片人協會認證的競賽型電影節","en":"Its international film festival is the only FIAPF-accredited competitive festival in the Chinese-speaking world.","ja":"ここの国際映画祭は、中華圏で唯一国際映画製作者連盟公認のコンペ映画祭"},{"k":"people","zh":"與利瑪竇合譯《幾何原本》的明代學者徐光啟是這裡人","en":"Xu Guangqi, the Ming scholar who translated Euclid's Elements with Matteo Ricci, was born here.","ja":"マテオ・リッチと『幾何原本』を共訳した明の学者・徐光啓はここの出身"},{"k":"symbol","zh":"市花是白玉蘭，市徽也畫著白玉蘭、沙船和螺旋槳","en":"Its city flower is the white magnolia, shown on the emblem with a junk and a propeller.","ja":"市花はハクモクレン。市章にもハクモクレン、沙船、スクリューが描かれる"},{"k":"life","zh":"傳統住宅「石庫門」：石框黑漆木門，配上狹窄的弄堂","en":"Its classic 'shikumen' row houses have stone-framed black wooden gates along narrow lanes.","ja":"伝統的住宅「石庫門」は、石枠に黒い木の門、細い路地が特徴"},{"k":"record","zh":"2016年開幕的迪士尼度假區，是中國內地第一座","en":"Its Disney resort, opened in 2016, was the first in mainland China.","ja":"2016年開業のディズニーリゾートは中国本土初"},{"k":"origin","zh":"別稱「魔都」源自日本作家村松梢風 1924 年的同名小說","en":"Its nickname 'Modu' (Demon City) comes from a 1924 novel by Japanese writer Muramatsu Shōfū.","ja":"愛称「魔都」は、村松梢風が1924年に発表した同名の小説に由来する"},{"k":"origin","zh":"別稱「○」與黃浦江舊名「春申江」，都和戰國楚國的春申君黃歇有關","en":"One of its one-character nicknames and the Huangpu's old name both trace to Lord Chunshen of Chu.","ja":"別称「○」と黄浦江の旧名「春申江」は、戦国時代楚の春申君に由来する"},{"k":"origin","zh":"簡稱「○」源自古時一種捕魚工具的名稱","en":"Its main one-character abbreviation comes from an old name for a fishing device.","ja":"略称「○」は、昔の漁具の名前に由来する"},{"k":"people","zh":"元代黃道婆跟海南黎族學會紡織，回到故鄉松江推廣棉紡技術","en":"In the Yuan dynasty, Huang Daopo learned weaving from the Li people of Hainan and brought it home to Songjiang.","ja":"元代の黄道婆は海南島の黎族に紡織を学び、故郷の松江に綿紡織を広めた"},{"k":"people","zh":"本地出身的姚明，是第一位沒打過美國大學就成為 NBA 選秀狀元的外國球員","en":"Local-born Yao Ming was the first international No. 1 NBA draft pick who never played US college ball.","ja":"ここ出身の姚明は、米大学を経ずにNBAドラフト全体1位となった初の外国人選手だ"},{"k":"sport","zh":"本地出身的劉翔 2004 年奪下 110 公尺跨欄金牌，是中國男子第一面奧運田徑金牌","en":"Local hurdler Liu Xiang won 110 m hurdles gold in 2004, China's first men's Olympic athletics gold.","ja":"地元出身の劉翔は2004年に110m障害で優勝、中国男子初の五輪陸上金メダルだった"},{"k":"history","zh":"1919 年大韓民國臨時政府在這裡的法租界成立","en":"The Provisional Government of the Republic of Korea was founded in the French Concession here in 1919.","ja":"1919年、大韓民国臨時政府がここのフランス租界で樹立された"},{"k":"history","zh":"1972 年尼克森訪華，中美聯合公報在這裡的錦江飯店簽署","en":"During Nixon's 1972 visit, the US–China joint communiqué was signed at the Jinjiang Hotel here.","ja":"1972年のニクソン訪中で、米中共同声明がここの錦江飯店で署名された"},{"k":"history","zh":"二戰時約兩萬名逃離納粹的猶太難民，被集中在虹口的隔離區","en":"In WWII about 20,000 Jewish refugees who had fled the Nazis were confined to a ghetto in Hongkou.","ja":"第二次大戦中、ナチスを逃れた約2万人のユダヤ難民が虹口のゲットーに集められた"},{"k":"history","zh":"1937 年「八百壯士」死守四行倉庫，女童軍楊惠敏冒險送去國旗","en":"In 1937 the 'Eight Hundred Heroes' held Sihang Warehouse, and Girl Guide Yang Huimin brought them a flag.","ja":"1937年「八百壮士」が四行倉庫を守り抜き、ガールガイドの楊恵敏が国旗を届けた"},{"k":"brand","zh":"大白兔奶糖 1943 年在這裡誕生，糖紙內那層糯米紙是可以吃的","en":"White Rabbit candy was born here in 1943; the thin rice-paper layer inside the wrapper is meant to be eaten.","ja":"ホワイトラビットのミルクキャンディーは1943年ここで誕生、内側のオブラートは食べられる"},{"k":"work","zh":"周潤發主演、以 1920 年代為背景的 1980 年 TVB 經典劇集，故事就在這裡","en":"It's the setting of the classic 1980 TVB drama starring Chow Yun-fat, with a theme song by Frances Yip.","ja":"周潤発主演、1920年代が舞台の1980年のTVB名作ドラマの舞台だ"},{"k":"work","zh":"史匹柏電影《太陽帝國》描寫二戰時被關進這裡龍華集中營的英國少年","en":"Spielberg's Empire of the Sun (1987) follows a British boy interned at the Lunghua camp here in WWII.","ja":"スピルバーグの『太陽の帝国』は、ここの龍華収容所に入れられた英国人少年を描く"},{"k":"food","zh":"本幫菜講究「濃油赤醬」，醬油裡常加糖，讓菜色紅亮","en":"Local cooking is known for 'thick oil, red sauce': sugared soy sauce gives dishes a glossy red look.","ja":"地元料理は「濃油赤醤」が特徴で、砂糖を加えた醤油で照りのある赤色に仕上げる"},{"k":"food","zh":"早餐「四大金剛」是大餅、油條、粢飯、豆漿","en":"The classic breakfast 'Four Warriors' is sesame flatbread, youtiao, sticky rice rolls and soy milk.","ja":"朝食の「四大金剛」は大餅・油条・粢飯・豆乳の四つだ"},{"k":"food","zh":"中秋節這裡的人偏愛包肉餡的鹹月餅，而不是甜月餅","en":"At the Mid-Autumn Festival, locals favor savory meat-filled mooncakes over sweet ones.","ja":"中秋節には甘い月餅より、肉餡入りの塩味の月餅が好まれる"},{"k":"life","zh":"人民公園的「相親角」自 2004 年起，每逢週末就貼滿徵婚資料","en":"Since 2004, the 'marriage market' in People's Park has filled with matchmaking ads every weekend.","ja":"人民公園の「お見合いコーナー」には、2004年から毎週末結婚相手募集の紙が並ぶ"},{"k":"history","zh":"市中心的人民公園，原是英國人 1862 年建的跑馬場","en":"People's Park downtown sits on the old racecourse founded by the British in 1862.","ja":"中心部の人民公園は、1862年に英国人が造った競馬場の跡地だ"},{"k":"legend","zh":"相傳龍華寺是三國時孫權為報答母親而建","en":"Legend says Longhua Temple was founded by Sun Quan of the Three Kingdoms to honor his mother.","ja":"龍華寺は三国時代、孫権が母のために建てたと伝わる"},{"k":"nature","zh":"自然陸地最高點在海上的大金山島，海拔只有約 104 公尺","en":"Its highest natural point, only about 104 m above sea level, is on offshore Dajinshan Island.","ja":"自然の最高地点は沖合の大金山島で、標高はわずか約104メートルだ"},{"k":"nature","zh":"黃浦江原是吳淞江的支流，明代後反客為主，蘇州河反而成了它的支流","en":"The Huangpu was once a tributary of the Wusong; after the Ming the roles reversed and Suzhou Creek became its tributary.","ja":"黄浦江はもと呉淞江の支流だったが、明代以降は逆転し蘇州河が支流になった"},{"k":"life","zh":"本地方言的「水門汀」（水泥）是英語 cement 的音譯","en":"In the local dialect, the word for concrete, 'shuimenting', is a borrowing of English 'cement'.","ja":"地元方言でセメントを指す「水門汀」は、英語のcementの音訳だ"},{"k":"record","zh":"2017 年 Siri 開始支援本地方言，是繼普通話、粵語後的第三種中文","en":"In 2017 Siri began supporting the local dialect, the third Chinese variety after Mandarin and Cantonese.","ja":"2017年、Siriが地元の方言に対応し、普通話・広東語に次ぐ3番目の中国語になった"},{"k":"people","zh":"新文化運動的旗手胡適，1891 年就出生在這裡","en":"Hu Shih, a leading figure of the New Culture Movement, was born here in 1891.","ja":"新文化運動の旗手・胡適は、1891年にここで生まれた"}],
"CN-SN":[{"k":"origin","zh":"周公、召公曾以一處高原為界分治東西，省名即指它的西邊","en":"The Dukes of Zhou and Shao once split their rule at a plateau; the name means the land west of it.","ja":"周公と召公がある高原を境に東西を分治した。省名はその西側の意"},{"k":"work","zh":"陳忠實獲茅盾文學獎的小說《白鹿原》，舞台在省會東郊","en":"Chen Zhongshi's Mao Dun Prize-winning novel White Deer Plain is set on the plateau east of its capital.","ja":"陳忠実の茅盾文学賞受賞作『白鹿原』の舞台は省都の東郊"},{"k":"people","zh":"茅盾文學獎小說《平凡的世界》作者路遙，出生於這裡的清澗縣","en":"Lu Yao, author of the Mao Dun Prize-winning Ordinary World, was born in Qingjian County here.","ja":"茅盾文学賞『平凡的世界』の作者・路遥は、ここの清澗県の生まれ"},{"k":"sport","zh":"2021年第十四屆全國運動會在這裡舉辦","en":"It hosted China's 14th National Games in 2021.","ja":"2021年の第14回全国運動会がここで開かれた"},{"k":"record","zh":"1981年，世界僅存的7隻朱鷺在這裡的洋縣被發現","en":"In 1981, the last 7 known crested ibises were found in Yang County here.","ja":"1981年、世界に7羽だけ残ったトキがここの洋県で見つかった"},{"k":"record","zh":"中國的大地原點（測量座標的原點）設在這裡的涇陽縣","en":"China's geodetic origin, the zero point of its national survey coordinates, is in Jingyang County here.","ja":"中国の測地原点（測量座標の原点）はここの涇陽県にある"},{"k":"record","zh":"「中國」二字最早見於這裡寶雞出土的西周青銅器何尊","en":"The earliest known use of the word 'Zhongguo' (China) is on the He zun, a Western Zhou bronze found in Baoji here.","ja":"「中国」の語の最古の例は、ここの宝鶏で出土した西周の青銅器・何尊"},{"k":"life","zh":"英文拼法比鄰省多一個 a，就是為了區分兩省","en":"Its English spelling has an extra 'a' just to tell it apart from a neighboring province.","ja":"英語表記に a が一つ多いのは、隣の省と区別するため"},{"k":"history","zh":"乾陵合葬唐高宗與中國唯一的女皇帝武則天","en":"Qianling holds Tang Emperor Gaozong together with Wu Zetian, China's only reigning empress.","ja":"乾陵には唐の高宗と、中国唯一の女帝・武則天が合葬されている"},{"k":"record","zh":"乾陵為武則天立的石碑高7.5公尺，卻一個字都沒刻","en":"Wu Zetian's 7.5 m stele at Qianling was left completely blank.","ja":"乾陵にある武則天の石碑は高さ7.5mだが、一文字も刻まれていない"},{"k":"history","zh":"1936年張學良、楊虎城在臨潼華清池扣押蔣介石，促成國共合作抗日","en":"In 1936 Zhang Xueliang and Yang Hucheng seized Chiang Kai-shek at Huaqing Pool, forcing a united front.","ja":"1936年、張学良と楊虎城が臨潼の華清池で蒋介石を拘束し、国共合作のきっかけとなった"},{"k":"symbol","zh":"秦嶺有罕見的棕白色大熊貓，最有名的是「七仔」","en":"The Qinling Mountains are home to rare brown-and-white giant pandas, the best known named Qizai.","ja":"秦嶺には珍しい茶色と白のジャイアントパンダがいて、「七仔」が有名"},{"k":"origin","zh":"別稱「三秦」，源自項羽把關中分給三位投降的秦將","en":"Its nickname 'Three Qins' dates to Xiang Yu splitting the region among three surrendered Qin generals.","ja":"別称「三秦」は、項羽が関中を降伏した秦の3将軍に分け与えたことに由来する"},{"k":"nature","zh":"太白山拔仙台海拔3767公尺，是秦嶺與全省最高峰","en":"Mount Taibai's Baxiantai, 3,767 m, is the highest point of the Qinling range and the province.","ja":"太白山の抜仙台は標高3767mで、秦嶺山脈と省内の最高峰"},{"k":"record","zh":"省會的碑林始於1087年，收藏近三千方石碑","en":"The capital's Stele Forest, begun in 1087, holds nearly 3,000 stone tablets.","ja":"省都の碑林は1087年に始まり、3000近い石碑を収める"},{"k":"record","zh":"781年立的景教碑，以漢文和敘利亞文記錄基督教在唐朝的傳播","en":"The Nestorian Stele of 781 records Christianity in Tang China in Chinese and Syriac.","ja":"781年建立の景教碑は、唐での景教（キリスト教）の伝来を漢文とシリア文で記す"},{"k":"record","zh":"唐代開成石經把十二部儒家經典刻在114塊石上，共65萬多字","en":"The Tang Kaicheng Stone Classics carved twelve Confucian classics, over 650,000 characters, on 114 stones.","ja":"唐の開成石経は儒教の経典12部、65万字余りを114枚の石に刻んだ"},{"k":"people","zh":"開拓絲綢之路的張騫出身漢中城固，出使途中被匈奴扣留十多年","en":"Silk Road pioneer Zhang Qian came from Chenggu near Hanzhong and was held by the Xiongnu for about 13 years.","ja":"シルクロードを開いた張騫は漢中・城固の出身で、旅の途中匈奴に十数年抑留された"},{"k":"history","zh":"西元前206年的鴻門宴在臨潼舉行，項莊舞劍意在沛公","en":"The Hongmen Banquet of 206 BC, where Xiang Zhuang's sword dance targeted Liu Bang, took place at Lintong.","ja":"紀元前206年の鴻門の会は臨潼で開かれ、項荘の剣舞は劉邦を狙っていた"},{"k":"life","zh":"地方戲曲以木梆子伴奏，被視為許多梆子戲的源頭","en":"Its local opera, accompanied by wooden bangzi clappers, is the main source of other bangzi operas.","ja":"地元の劇は木の拍子木「梆子」で伴奏し、多くの梆子劇の源流とされる"},{"k":"legend","zh":"《史記》說始皇陵以水銀為江河，土壤檢測也發現汞含量異常","en":"Sima Qian wrote that rivers of mercury flowed in the First Emperor's tomb; soil tests found unusual mercury.","ja":"『史記』は始皇帝陵に水銀の川があると記し、土壌調査でも高い水銀濃度が見つかった"},{"k":"history","zh":"韓國派水工鄭國修渠想拖垮秦國，結果鄭國渠反而讓秦富強","en":"Han sent engineer Zheng Guo to drain Qin with a canal project, but the canal made Qin rich and strong.","ja":"韓は技師鄭国に運河を造らせて秦を疲弊させようとしたが、逆に秦を富ませた"},{"k":"history","zh":"756年安史之亂中，楊貴妃在興平的馬嵬驛被賜死","en":"In 756, during the An Lushan Rebellion, Yang Guifei was put to death at Mawei post station.","ja":"756年、安史の乱のさなか楊貴妃は興平の馬嵬駅で死を賜った"},{"k":"legend","zh":"相傳周幽王在驪山點烽火戲弄諸侯博褒姒一笑，最後亡國","en":"Legend says King You lit Mount Li's beacons to make Bao Si laugh, and later no lords came to save him.","ja":"周の幽王は褒姒を笑わせるため驪山で烽火を上げ、のちに誰も救援に来ず滅んだと伝わる"},{"k":"people","zh":"北宋張載住在郿縣橫渠鎮，名言是「為天地立心，為生民立命」","en":"Song thinker Zhang Zai, 'Master Hengqu', lived in Hengqu town here and founded the Guanxue school.","ja":"北宋の思想家・張載は横渠鎮に住んで「横渠先生」と呼ばれ、関学を開いた"},{"k":"origin","zh":"漢朝與漢族的「漢」，來自劉邦受封的漢中","en":"The 'Han' of the Han dynasty and the Han Chinese comes from Hanzhong, Liu Bang's fief here.","ja":"漢王朝と漢民族の「漢」は、劉邦が封じられたここの漢中に由来する"},{"k":"work","zh":"唐玄宗與楊貴妃在華清宮的故事，被白居易寫成《長恨歌》","en":"Emperor Xuanzong and Yang Guifei's romance at Huaqing Palace inspired Bai Juyi's 'Chang Hen Ge'.","ja":"唐の玄宗と楊貴妃の華清宮での物語は、白居易の『長恨歌』に詠まれた"},{"k":"people","zh":"1644年攻陷北京、終結明朝統治的李自成，出身這裡的北部","en":"Li Zicheng, the rebel who took Beijing in 1644 and ended Ming rule there, was born in the north of this province.","ja":"1644年に北京を陥落させ明の支配を終わらせた李自成は、この地の北部出身"},{"k":"record","zh":"藍田公王嶺出土的直立人頭骨，距今約160萬年","en":"The Homo erectus skull from Gongwangling, Lantian, is about 1.6 million years old.","ja":"藍田の公王嶺で見つかった原人の頭骨は約160万年前のもの"},{"k":"brand","zh":"閻良區以飛機製造為最重要的產業，還有試飛用的機場","en":"Yanliang district's leading industry is aircraft manufacturing, with a company airfield for test flights.","ja":"閻良区は航空機製造が最大の産業で、試験飛行用の飛行場もある"},{"k":"record","zh":"唐代大明宮遺址的面積約是北京故宮的3.5倍","en":"The Tang Daming Palace site is about 3.5 times larger than Beijing's Forbidden City.","ja":"唐の大明宮の遺跡は、北京の紫禁城の約3.5倍の広さ"}],
"CN-SX":[{"k":"origin","zh":"簡稱來自春秋時代在這裡受封的一個諸侯國","en":"Its one-character abbreviation comes from a Spring and Autumn state enfeoffed here.","ja":"略称は、春秋時代にここに封じられた諸侯国の名に由来する"},{"k":"work","zh":"遊戲《黑神話：悟空》公布的36個取景地中，有27個在這裡","en":"Of the 36 real locations listed for the game Black Myth: Wukong, 27 are here.","ja":"ゲーム『黒神話：悟空』で公表されたロケ地36か所のうち27か所がここ"},{"k":"work","zh":"王之渙「白日依山盡，黃河入海流」登的鸛雀樓，在這裡的永濟","en":"The Stork Tower of Wang Zhihuan's poem ('The white sun sets behind the hills…') is in Yongji here.","ja":"王之渙「白日山に依りて尽き」の鸛雀楼は、ここの永済にある"},{"k":"people","zh":"唐代名相、「神探」故事主角狄仁傑是這裡人","en":"Di Renjie, the Tang chancellor famed as a detective in later fiction, came from here.","ja":"唐の名宰相で、探偵物語の主人公でもある狄仁傑はここの出身"},{"k":"people","zh":"漢朝名將衛青是這裡的平陽人，也是霍去病的舅舅","en":"Han general Wei Qing, uncle of Huo Qubing, was from Pingyang here.","ja":"漢の名将・衛青はここの平陽の人で、霍去病の叔父"},{"k":"life","zh":"1960年代全國喊「農業學大寨」，大寨村就在這裡的昔陽縣","en":"Dazhai, the village of the 1960s slogan 'In agriculture, learn from Dazhai', is in Xiyang County here.","ja":"1960年代の「農業は大寨に学べ」の大寨村は、ここの昔陽県にある"},{"k":"record","zh":"全中國唯一完整保存唐朝到清朝各時期木結構古建築的省份","en":"The only province in China with surviving wooden buildings from every period from the Tang to the Qing.","ja":"唐から清まで各時代の木造古建築が揃って残る、中国唯一の省"},{"k":"life","zh":"明初大批移民從洪洞大槐樹下出發，許多華北人把那裡當成祖籍","en":"In the early Ming, waves of migrants set out from the Great Locust Tree in Hongtong; many northerners see it as their ancestral home.","ja":"明初、大勢の移民が洪洞の大槐樹の下から旅立ち、華北の多くの人がそこを祖先の地とする"},{"k":"history","zh":"前260年長平之戰，秦將白起處決趙軍降卒，據載趙軍死者逾45萬","en":"At Changping in 260 BC, Qin general Bai Qi's forces killed over 450,000 Zhao soldiers, per Sima Qian.","ja":"紀元前260年の長平の戦いで、秦の白起の軍は趙兵45万以上を死なせたと伝わる"},{"k":"life","zh":"成語「紙上談兵」，源自在高平長平之戰慘敗的趙括","en":"The idiom 'talking war on paper' comes from Zhao Kuo, routed at Changping near Gaoping.","ja":"成語「紙上談兵」は、高平の長平の戦いで大敗した趙括に由来する"},{"k":"history","zh":"前403年，這裡的大國被韓、趙、魏三家瓜分","en":"In 403 BC the great state here split into Han, Zhao and Wei.","ja":"紀元前403年、この地の大国が韓・趙・魏の三国に分かれた"},{"k":"history","zh":"唐朝從太原起家建國，當時這一帶稱為「河東」","en":"The Tang dynasty originated in Taiyuan; the region was then called Hedong.","ja":"唐王朝は太原から興り、当時この地は「河東」と呼ばれた"},{"k":"history","zh":"北魏在398到494年定都平城，就是今天的大同","en":"Datong, then called Pingcheng, was the Northern Wei capital from 398 to 494.","ja":"北魏は398〜494年、平城（今の大同）を都とした"},{"k":"people","zh":"女皇帝武則天，624年生於這裡","en":"Wu Zetian, China's famous female emperor, was born here in 624.","ja":"中国の女帝・武則天は624年にここで生まれた"},{"k":"people","zh":"人稱「詩佛」的唐代詩人王維，家族出身祁縣","en":"Tang poet Wang Wei, the 'Poet Buddha', came from a family of Qi County.","ja":"「詩仏」と呼ばれる唐の詩人・王維は祁県の家の出"},{"k":"people","zh":"唐宋八大家之一的柳宗元，生於今天的永濟","en":"Liu Zongyuan, one of the Eight Great Prose Masters of Tang and Song, was born in present-day Yongji.","ja":"唐宋八大家の一人・柳宗元は、今の永済で生まれた"},{"k":"people","zh":"長年統治本省的閻錫山生於五台，後任行政院長，葬在臺北陽明山","en":"Warlord Yan Xishan, born in Wutai, became ROC premier and is buried on Yangmingshan in Taipei.","ja":"長く当地を支配した閻錫山は五台生まれで、のちに行政院長となり台北の陽明山に眠る"},{"k":"people","zh":"曾任國民政府財政部長的孔祥熙，是太谷人","en":"H. H. Kung, the Nationalist government's finance minister, came from Taigu.","ja":"国民政府の財政部長を務めた孔祥熙は太谷の出身"},{"k":"history","zh":"980年宋將楊業在雁門關外大敗契丹，成為「楊家將」故事的源頭","en":"In 980 Song general Yang Ye beat the Khitans at Yanmen Pass, a source of the Yang Family Generals tales.","ja":"980年、宋の楊業が雁門関で契丹を破り、「楊家将」物語の題材となった"},{"k":"work","zh":"金庸《天龍八部》裡的關鍵場景雁門關，就在代縣","en":"Yanmen Pass in Dai County appears in Jin Yong's novel 'Demi-Gods and Semi-Devils'.","ja":"金庸『天龍八部』に登場する雁門関は代県にある"},{"k":"history","zh":"1937年平型關戰役，是共軍對日作戰的最大勝仗","en":"The 1937 Battle of Pingxingguan was the Communists' largest victory over Japanese forces.","ja":"1937年の平型関の戦いは、共産党軍が日本軍に挙げた最大の勝利とされる"},{"k":"nature","zh":"運城附近的解池是省內最大的天然湖，而且是座鹽湖","en":"Xiechi, a salt lake near Yuncheng, is the largest natural lake in the province.","ja":"運城近くの解池は省内最大の天然湖で、塩湖である"},{"k":"life","zh":"當地方言自成一支，是北方唯一不屬於官話的漢語","en":"Its local dialect group is the only major Sinitic variety in northern China outside Mandarin.","ja":"ここの方言は、華北で唯一官話に属さない独立した漢語とされる"},{"k":"brand","zh":"汾酒曾在1915年巴拿馬太平洋萬國博覽會獲獎","en":"Fenjiu liquor won a medal at the 1915 Panama–Pacific International Exposition.","ja":"汾酒は1915年のパナマ太平洋万国博覧会でメダルを受けた"},{"k":"food","zh":"「柳林碗托」是蒸在小碗裡的蕎麥麵食，拌蒜、辣椒和醋吃","en":"Liulin wantuan is buckwheat dough steamed in a small bowl, eaten with garlic, chili and vinegar.","ja":"「柳林碗托」は小鉢で蒸したそば粉の麺料理で、にんにく・唐辛子・酢で食べる"},{"k":"symbol","zh":"太原西南郊祠廟裡的「周柏」相傳植於西周，樹身向南傾斜約40度","en":"A temple cypress southwest of Taiyuan is said to date from the Western Zhou and leans about 40°.","ja":"太原南西郊の祠廟の「周柏」は西周に植えられたと伝わり、約40度傾いている"},{"k":"legend","zh":"傳說上古帝堯的都城在今天的臨汾，堯都區因此得名","en":"Legend puts the capital of the sage-king Yao at Linfen, hence its Yaodu District.","ja":"伝説の聖王・堯の都は臨汾にあったとされ、堯都区の名の由来となった"},{"k":"history","zh":"1949年4月共軍以1300門火砲攻打太原，22日完全控制全省","en":"In April 1949 the PLA shelled Taiyuan with 1,300 guns and controlled the whole province by 22 April.","ja":"1949年4月、人民解放軍は1300門の砲で太原を攻め、22日に省全体を掌握した"},{"k":"history","zh":"1900年慈禧西逃途中曾在此停留，當地官商出資相助","en":"Fleeing west after the Boxer Uprising in 1900, Empress Dowager Cixi stayed here, aided by local merchants.","ja":"1900年に西へ逃れた西太后はここに滞在し、地元の役人や商人が資金を援助した"},{"k":"history","zh":"五代十國的「十國」中，唯一位在北方的北漢就以此為根據地","en":"Northern Han, the only one of the Ten Kingdoms in northern China, was based here.","ja":"五代十国の十国のうち、唯一華北にあった北漢はここを本拠とした"}],
"CN-TJ":[{"k":"people","zh":"相聲演員、德雲社創辦人之一郭德綱出生在這裡","en":"Crosstalk comedian Guo Degang, a co-founder of Deyunshe, was born here.","ja":"中国漫才「相声」の芸人で、徳雲社の創設者の一人・郭徳綱はここ生まれ"},{"k":"people","zh":"為《送別》「長亭外，古道邊」填詞的弘一法師李叔同出生在這裡","en":"Li Shutong (Master Hongyi), who wrote the lyrics of 'Farewell' ('Beyond the pavilion, by the old road'), was born here.","ja":"『送別』（長亭の外、古道の辺）を作詞した李叔同（弘一法師）はここ生まれ"},{"k":"people","zh":"末代皇帝溥儀1929年搬進這裡的靜園，住到1931年","en":"Puyi, the last emperor, lived in the Jingyuan villa here from 1929 to 1931.","ja":"ラストエンペラー溥儀は1929〜1931年、ここの静園に住んだ"},{"k":"sport","zh":"這裡的女排俱樂部拿過16次全國聯賽冠軍，是中國最成功的女排隊","en":"Its women's volleyball club has won 16 national league titles, the most successful in China.","ja":"ここの女子バレーボールクラブは全国リーグ優勝16回、中国一の強豪"},{"k":"festival","zh":"農曆三月二十三媽祖誕辰時辦「皇會」，是國家級非物質文化遺產","en":"For Mazu's birthday on the 23rd of the 3rd lunar month it holds the 'Huanghui' fair, a national intangible heritage.","ja":"旧暦3月23日の媽祖の誕生日に「皇会」が開かれる。国家級無形文化遺産"},{"k":"life","zh":"國民自行車「飛鴿」的故鄉，鄧小平曾說繁榮就是「家家一輛飛鴿」","en":"Home of the Flying Pigeon bicycle; Deng Xiaoping defined prosperity as 'a Flying Pigeon in every household'.","ja":"国民的自転車「飛鴿」の故郷。鄧小平は豊かさを「どの家にも飛鴿を」と表現した"},{"k":"record","zh":"「瓷房子」用了超過7億片陶瓷片裝飾整棟洋樓","en":"Its 'Porcelain House' is decorated with over 700 million ceramic shards.","ja":"「瓷房子」は7億片以上の陶磁器のかけらで飾られた洋館"},{"k":"record","zh":"中國第一條時速350公里的高鐵，2008年從北京開到這裡","en":"China's first 350 km/h high-speed line opened in 2008, running from Beijing to here.","ja":"中国初の時速350kmの高速鉄道は2008年、北京からここまで開通した"},{"k":"origin","zh":"見於史籍的最早名稱叫「直沽」","en":"Its earliest recorded name was Zhigu.","ja":"史書に見える最も古い名は「直沽」"},{"k":"nature","zh":"許多河流在這裡匯入海河出海，素有「九河下梢」之稱","en":"Called the 'lower end of nine rivers', it is where many rivers merge into the Hai River.","ja":"多くの川が海河に合流して海に注ぐため「九河下梢」と呼ばれる"},{"k":"life","zh":"俗話說「先有天后宮，後有○○城」，天后宮始建於1326年","en":"A local saying: 'First the Tianhou Temple, then the city.' The temple dates to 1326.","ja":"「先に天后宮があり、後に○○の町ができた」と言われ、天后宮は1326年創建"},{"k":"record","zh":"城裡的天后宮與湄洲祖廟、北港朝天宮並稱世界三大媽祖廟","en":"Its Tianhou Temple ranks with Meizhou and Taiwan's Beigang Chaotian as the 3 great Mazu temples.","ja":"ここの天后宮は湄洲祖廟、台湾の北港朝天宮と並ぶ世界三大媽祖廟とされる"},{"k":"history","zh":"1858年清廷在此與英法等國簽約，被迫開放這裡通商","en":"An 1858 treaty named after this city forced it open to foreign trade.","ja":"1858年、この地の名を冠した条約により外国との通商に開放された"},{"k":"history","zh":"海河口的大沽砲台，1858到1860年間三度遭英法聯軍進攻","en":"The Taku Forts at the Hai River mouth were attacked by Anglo-French forces three times in 1858–60.","ja":"海河河口の大沽砲台は、1858〜1860年に英仏軍の攻撃を三度受けた"},{"k":"history","zh":"1870年這裡發生教案，包括十名法國修女在內的18名外國人遇害","en":"In 1870 a mob here killed 18 foreigners, including ten French nuns.","ja":"1870年の教案で、フランス人修道女10人を含む外国人18人が殺害された"},{"k":"history","zh":"1900年八國聯軍攻下此城，設臨時政府統治到1902年","en":"After the Eight-Nation Alliance took the city in 1900, a provisional government ran it until 1902.","ja":"1900年に八カ国連合軍が占領し、1902年まで臨時政府が統治した"},{"k":"record","zh":"1907年袁世凱在此主持縣議會選舉，被視為中國首次近代民主選舉","en":"In 1907 Yuan Shikai oversaw a county council election here, China's first modern democratic vote.","ja":"1907年、袁世凱の下で行われた県議会選挙は中国初の近代的民主選挙とされる"},{"k":"record","zh":"1906年通車的電車，是中國第一個全市性的電車系統","en":"Its 1906 tramway was China's first citywide tram system.","ja":"1906年開業の路面電車は、中国初の市内全域にわたる電車網だった"},{"k":"record","zh":"1976年10月通車的地下鐵道，是中國第二條建成的地鐵","en":"Opened in October 1976, its underground railway was the second metro built in China.","ja":"1976年10月開通の地下鉄は、中国で二番目に造られた地下鉄"},{"k":"record","zh":"茱莉亞音樂學院2015年在此設校，是它首次在美國以外全面辦學","en":"Juilliard's 2015 expansion here was its first full-scale venture outside the United States.","ja":"ジュリアード音楽院は2015年、米国外で初の本格的な拠点をここに設けた"},{"k":"life","zh":"濱海新區的圖書館入選《時代》雜誌2018年「世界百大最佳地點」","en":"Its Binhai Library made Time's list of the World's 100 Greatest Places of 2018.","ja":"濱海図書館はタイム誌の「2018年世界の最も素晴らしい場所100」に選ばれた"},{"k":"people","zh":"電影《火戰車》主角原型、奧運400公尺金牌李愛銳，1902年生於此","en":"Eric Liddell, the 1924 Olympic 400 m champion of 'Chariots of Fire', was born here in 1902.","ja":"映画『炎のランナー』の五輪400m金メダリスト、エリック・リデルは1902年ここで生まれた"},{"k":"sport","zh":"唯一在中國出生的大聯盟球員哈利・金曼，就出身這裡","en":"Harry Kingman, the only major league baseball player born in China, came from here.","ja":"中国生まれ唯一のメジャーリーガー、ハリー・キングマンはここの出身"},{"k":"people","zh":"人稱「中國氫彈之父」的物理學家于敏，是這裡人","en":"Physicist Yu Min, the 'father of China's hydrogen bomb', came from here.","ja":"「中国水爆の父」と呼ばれる物理学者・于敏はここの出身"},{"k":"brand","zh":"海鷗錶的前身1955年在此成立，同年做出中國第一支機械錶「五星」","en":"Seagull's forerunner, founded here in 1955, made China's first mechanical watch, the 'Five-Star'.","ja":"海鴎の前身は1955年にここで創業し、中国初の機械式時計「五星」を作った"},{"k":"brand","zh":"「魏記風箏」以能摺疊收成一小包而聞名","en":"Wei's kites are famous for folding down to a fraction of their full size.","ja":"「魏記」の凧は小さく折りたためることで知られる"},{"k":"food","zh":"1907年創立的西餐廳起士林，是這裡的老字號西餐名店","en":"Kiessling, a Western-style restaurant founded here in 1907, is a local culinary institution.","ja":"1907年創業の洋食店「起士林（キースリング）」はここの老舗"},{"k":"food","zh":"早餐常吃「鍋巴菜」：小米綠豆煎餅切條，淋上滷汁","en":"A local breakfast is guobacai: strips of millet and mung bean pancake in a savory sauce.","ja":"朝食の定番「鍋巴菜」は、粟と緑豆の薄焼きを細切りにしてたれをかける"},{"k":"sport","zh":"1995年世界桌球錦標賽在這裡舉行","en":"It hosted the 1995 World Table Tennis Championships.","ja":"1995年の世界卓球選手権はここで開かれた"},{"k":"history","zh":"2015年8月12日港區發生大爆炸，造成173人死亡","en":"On 12 August 2015, explosions at its port killed 173 people.","ja":"2015年8月12日、港湾地区の大爆発で173人が死亡した"},{"k":"brand","zh":"空中巴士A320的總裝線自2009年起在這裡運作","en":"An Airbus A320 final assembly line has operated here since 2009.","ja":"2009年からエアバスA320の最終組立ラインがここで稼働している"},{"k":"people","zh":"美國名將馬歇爾1920年代曾在美軍第15步兵團任副團長駐紮於此","en":"George C. Marshall served here in the 1920s as executive officer of the US 15th Infantry.","ja":"米国の名将マーシャルは1920年代、第15歩兵連隊の副官としてここに駐留した"}],
"CN-XJ":[{"k":"origin","zh":"1884年清朝在此建省，名稱有「新闢疆土」與「故土新歸」兩種解讀","en":"Made a province by the Qing in 1884; the name is read either as 'new frontier' or 'old land newly returned'.","ja":"1884年に清が省を設置。名は「新たに開いた辺境」とも「故地の帰還」とも解される"},{"k":"work","zh":"王洛賓改編的《達坂城的姑娘》，是中國第一首漢語譯配的維吾爾民歌","en":"'The Girl from Dabancheng', adapted by Wang Luobin, was the first Uyghur folk song set to Chinese lyrics.","ja":"王洛賓が編曲した『ダバンチョンの娘』は、中国語に訳詞された初のウイグル民謡"},{"k":"people","zh":"女星迪麗熱巴1992年出生在首府","en":"Actress Dilraba Dilmurat was born in its capital in 1992.","ja":"女優ディリラバは1992年に区都で生まれた"},{"k":"festival","zh":"維吾爾族的歌舞詩聚會「麥西來甫」，2010年列入急需保護的非遺名錄","en":"Meshrep, the Uyghur gathering of music, dance and poetry, joined UNESCO's urgent-safeguarding list in 2010.","ja":"ウイグル族の歌舞と詩の集い「メシュレプ」は2010年に緊急保護の無形遺産に登録"},{"k":"life","zh":"除了北京時間，當地還常用慢兩小時的地方時間（UTC+6）","en":"Besides Beijing Time, locals often use their own time, two hours behind (UTC+6).","ja":"北京時間のほか、2時間遅い独自の時間（UTC+6）もよく使われる"},{"k":"record","zh":"塔里木河全長2327公里，是中國最長的內流河","en":"The 2,327 km Tarim is China's longest inland river.","ja":"全長2327kmのタリム川は中国最長の内陸河川"},{"k":"sport","zh":"飛虎籃球隊在2016–17球季首度奪得CBA總冠軍","en":"The Flying Tigers basketball team here won their first CBA title in the 2016–17 season.","ja":"ここのバスケットボールチーム「飛虎」は2016–17シーズンにCBA初優勝"},{"k":"life","zh":"名玉「和田玉」產自這裡崑崙山北麓的和田一帶","en":"Hetian jade, China's famed nephrite, comes from the Hotan area at the foot of the Kunlun Mountains here.","ja":"名玉「ホータン玉」は、ここの崑崙山脈のふもと、ホータン一帯で産出する"},{"k":"people","zh":"譯出《金剛經》《法華經》的高僧鳩摩羅什，出生於這裡的龜茲（今庫車）","en":"Kumarajiva, translator of the Diamond and Lotus Sutras, was born in Kucha here.","ja":"『金剛経』『法華経』を訳した鳩摩羅什は、ここの亀茲（今の庫車）で生まれた"},{"k":"people","zh":"喀什噶里在 1070 年代編成第一部完整的突厥語詞典《突厥語大詞典》","en":"Mahmud al-Kashgari compiled the first comprehensive Turkic dictionary in the 1070s.","ja":"マフムード・カーシュガリーは1070年代に初の本格的なテュルク語辞典を編んだ"},{"k":"people","zh":"林則徐鴉片戰爭後被流放伊犁，帶人修出被稱為「林公渠」的水渠","en":"Exiled to Ili after the Opium War, Lin Zexu built a canal locals called the 'Lin Gong Canal'.","ja":"アヘン戦争後イリに流された林則徐は水路を築き、「林公渠」と呼ばれた"},{"k":"legend","zh":"傳說乾隆的香妃身體天生帶香，喀什的阿帕克和卓墓曾被誤傳為她的墓","en":"Legend says Qianlong's Fragrant Concubine smelled sweet by nature; a Kashgar tomb is claimed as hers.","ja":"乾隆帝の香妃は生まれつき体から香りがしたと伝わり、カシュガルの廟が彼女の墓とされた"},{"k":"legend","zh":"天山上的天池，被附會為傳說中西王母的「瑤池」","en":"Heavenly Lake in the Tian Shan is linked to the Jade Pool of the mythical Queen Mother of the West.","ja":"天山の天池は、伝説の西王母の「瑶池」になぞらえられている"},{"k":"history","zh":"成語「不入虎穴，焉得虎子」出自東漢班超在西域鄯善國擊殺匈奴使者的故事","en":"Ban Chao's line 'no entering the tiger's lair, no cubs' comes from his raid on Xiongnu envoys here.","ja":"「虎穴に入らずんば虎子を得ず」は、班超が西域の鄯善で匈奴の使者を討った故事から"},{"k":"history","zh":"西漢傅介子灌醉樓蘭王後將他刺殺，樓蘭從此被漢朝改名為鄯善","en":"Han envoy Fu Jiezi killed the drunk king of Loulan in 77 BC, and Loulan was renamed Shanshan.","ja":"前漢の傅介子は楼蘭王を酔わせて刺殺し、楼蘭は鄯善と改名させられた"},{"k":"history","zh":"玄奘西行經過高昌時，國王麴文泰與他結拜為兄弟","en":"When Xuanzang passed through Gaochang on his way west, King Qu Wentai swore brotherhood with him.","ja":"西へ向かう玄奘が高昌に立ち寄ると、国王麴文泰は彼と義兄弟の契りを結んだ"},{"k":"history","zh":"古國樓蘭約在西元 330 年因河流改道缺水而被廢棄","en":"The oasis city of Loulan was abandoned around 330 AD, probably after its river changed course.","ja":"楼蘭は西暦330年ごろ、川の流路が変わって水不足となり放棄された"},{"k":"history","zh":"塔里木盆地出土的「樓蘭美女」等乾屍，年代可追溯到約西元前 1800 年","en":"Tarim Basin mummies such as the Beauty of Loulan date back to about 1800 BC.","ja":"タリム盆地で見つかった「楼蘭の美女」などのミイラは紀元前1800年ごろにさかのぼる"},{"k":"record","zh":"中國第一顆原子彈 1964 年 10 月 16 日在羅布泊試爆成功","en":"China's first nuclear test was carried out at Lop Nur on 16 October 1964.","ja":"中国初の原爆実験は1964年10月16日、ロプノールで行われた"},{"k":"record","zh":"額爾齊斯河是中國唯一流入北冰洋水系的河流","en":"The Irtysh is the only river in China that drains to the Arctic Ocean.","ja":"エルティシ川は中国で唯一、北極海へ流れる川である"},{"k":"record","zh":"喀什的艾提尕爾清真寺可容納兩萬人禮拜，是中國最大的清真寺","en":"Kashgar's Id Kah Mosque holds 20,000 worshippers, making it the largest mosque in China.","ja":"カシュガルのエイティガール・モスクは2万人を収容する中国最大のモスク"},{"k":"record","zh":"喀什是中國最西端的城市，位在帕米爾高原與塔里木盆地交接處","en":"Kashgar here is the westernmost city of the People's Republic of China.","ja":"カシュガルは中国最西端の都市である"},{"k":"nature","zh":"吐魯番附近曾測得 52.2℃，是中國有紀錄以來的最高氣溫","en":"Near Turpan, a temperature of 52.2°C was recorded, China's all-time high.","ja":"トルファン近郊では52.2℃を記録し、中国の観測史上最高気温となった"},{"k":"nature","zh":"天山把這裡分成北邊的準噶爾盆地和南邊的塔里木盆地","en":"The Tian Shan splits this region into the Dzungarian Basin in the north and the Tarim Basin in the south.","ja":"天山山脈がここを北のジュンガル盆地と南のタリム盆地に分けている"},{"k":"origin","zh":"克拉瑪依在維吾爾語是「黑油」，得名於城外天然瀝青堆成的黑油山","en":"Karamay means 'black oil' in Uyghur, after nearby hills of natural asphalt.","ja":"カラマイはウイグル語で「黒い油」、近くの天然アスファルトの丘に由来する"},{"k":"origin","zh":"首府的名字源自衛拉特蒙古語「美麗的牧場」，清代曾叫「迪化」，1954 年改回","en":"The capital's name means 'beautiful pasture' in Oirat; called Dihua under the Qing, it was restored in 1954.","ja":"首府の名はオイラト語で「美しい牧場」。清代は「迪化」と呼ばれ、1954年に戻された"},{"k":"origin","zh":"「喀什噶爾」據說因當地玉石貿易發達，意為「玉城」","en":"Kashgar's name is said to mean 'jade city', reflecting its thriving jade trade.","ja":"カシュガルの名は玉の交易が盛んだったことから「玉の町」を意味するとされる"},{"k":"brand","zh":"1955 年克拉瑪依一號井噴出工業油流，荒漠裡從此長出一座石油城","en":"Karamay No. 1 Well struck oil in 1955, turning empty desert into an oil city.","ja":"1955年にカラマイ1号井から原油が出て、無人の荒野に石油の町が生まれた"},{"k":"festival","zh":"錫伯族每年農曆四月十八過「西遷節」，紀念 1764 年奉命從東北遷到伊犁戍邊","en":"The Xibe mark the 18th of the 4th lunar month, recalling their 1764 move to Ili to guard the frontier.","ja":"シベ族は旧暦4月18日に「西遷節」を祝い、1764年にイリへ移住した歴史をしのぶ"},{"k":"sport","zh":"阿勒泰發現描繪滑雪的古老岩畫，被認為是滑雪的發源地","en":"Altay, with ancient rock paintings of skiers, is considered a birthplace of skiing.","ja":"アルタイでは古いスキーの岩絵が見つかり、スキー発祥の地とされる"},{"k":"sport","zh":"維吾爾族的高空走鋼絲「達瓦孜」，2006 年列入國家級非遺","en":"Dawaz, the Uyghur art of high-wire walking, became national intangible heritage in 2006.","ja":"ウイグル族の綱渡り「ダワズ」は2006年に国家級無形文化遺産となった"},{"k":"symbol","zh":"野外一度滅絕的普氏野馬，1985 年起被引回這裡繁育、放歸","en":"Przewalski's horse, once extinct in the wild, has been bred and released here since 1985.","ja":"野生で一度絶滅したモウコノウマは、1985年からここで繁殖・再導入されている"},{"k":"work","zh":"電影《臥虎藏龍》中，玉嬌龍與羅小虎在○○的沙漠相遇相戀","en":"In Crouching Tiger, Hidden Dragon, Jen meets and falls for the bandit Lo in this region's desert.","ja":"『グリーン・デスティニー』で、玉嬌龍は○○の砂漠で盗賊の羅小虎と出会い恋に落ちる"},{"k":"work","zh":"1963 年電影《冰山上的來客》以帕米爾高原的塔吉克族為舞台，插曲是《花兒為什麼這樣紅》","en":"The 1963 film Visitors on the Icy Mountain is set among Tajiks of the Pamirs here.","ja":"1963年の映画『冰山上的来客』はパミール高原のタジク族を舞台にしている"},{"k":"work","zh":"木偶動畫《阿凡提的故事》，改編自流傳在○○的維吾爾民間故事","en":"The puppet animation The Story of Afanti adapts Nasreddin tales popular in this region.","ja":"人形アニメ『阿凡提的故事』は、○○に伝わるウイグルの民話をもとにしている"},{"k":"food","zh":"維吾爾族的饢放進名為「饢坑」（tunur）的深土爐裡烤","en":"Uyghur nan is baked in a deep clay oven called a tunur.","ja":"ウイグルのナンは「トヌル」と呼ぶ深い土窯で焼く"},{"k":"life","zh":"吐魯番用牆面鏤空、構造特殊的晾房把葡萄風乾成葡萄乾","en":"Turpan turns grapes into raisins in distinctive vented drying houses.","ja":"トルファンでは壁に穴の開いた独特の乾燥小屋でブドウを干しブドウにする"}],
"CN-XZ":[{"k":"origin","zh":"首府的名字在當地語言中意為「聖地」或「眾神之地」","en":"Its capital's name means 'holy place' or 'land of the gods' in the local language.","ja":"区都の名は現地の言葉で「聖地」「神々の地」の意"},{"k":"festival","zh":"「雪頓節」意為酸奶宴，要展大佛像、看傳統戲劇","en":"Its Shoton ('yogurt feast') Festival features the unveiling of giant Buddha images and traditional opera.","ja":"「ショトン祭」はヨーグルトの宴の意で、巨大仏画の開帳や伝統劇がある"},{"k":"record","zh":"世界海拔最高的大河流經這裡，平均海拔約4000公尺以上","en":"The world's highest major river flows through here, averaging over 4,000 m above sea level.","ja":"平均標高4000m超、世界で最も高所を流れる大河がここを流れる"},{"k":"life","zh":"人民幣50元鈔票背面印的宮殿就在這裡","en":"The palace on the back of China's 50-yuan banknote is here.","ja":"人民元50元札の裏に描かれた宮殿がここにある"},{"k":"sport","zh":"1960年中國登山隊從這裡的北坡，首次沿北稜登上世界最高峰","en":"In 1960 a Chinese team made the first ascent of the world's highest peak via the North Ridge, from here.","ja":"1960年、中国登山隊がここから北稜経由で世界最高峰に初登頂した"},{"k":"people","zh":"以情詩聞名、人稱「情僧」的六世達賴倉央嘉措","en":"Tsangyang Gyatso, the 6th Dalai Lama, nicknamed the 'romantic monk' for his love poems.","ja":"恋愛詩で知られ「情僧」と呼ばれたダライ・ラマ6世ツァンヤン・ギャツォ"},{"k":"record","zh":"羊八井地熱電站是目前中國最大的地熱發電站","en":"The Yangbajain geothermal plant here is China's largest geothermal power station.","ja":"羊八井地熱発電所は中国最大の地熱発電所"},{"k":"record","zh":"世界最高峰腳下海拔約5100公尺的絨布寺，是世界最高的寺院之一","en":"Rongbuk Monastery, about 5,100 m up at the foot of the world's highest peak, is among the highest monasteries on Earth.","ja":"世界最高峰の麓、標高約5100mのロンブク寺は世界有数の高所の寺"},{"k":"record","zh":"763年動工的桑耶寺，是這片高原上第一座佛教寺院","en":"Samye, begun in 763, was the first Buddhist monastery built in this region.","ja":"763年に建設が始まったサムイェー寺は、この地で最初の仏教寺院"},{"k":"history","zh":"8世紀末赤松德贊在桑耶寺舉行印度僧與漢地禪僧的辯論，印度一方勝出","en":"In the 790s King Trisong Detsen held the Samye debate between Indian Buddhism and Chinese Chan; India won.","ja":"790年代、ティソン・デツェン王はサムイェー寺でインド仏教と中国禅の論争を開き、インド側が勝った"},{"k":"history","zh":"阿里札達的古格王國約912年建立，1630年前後被拉達克攻滅","en":"The Guge kingdom in Zanda, Ngari, was founded around 912 and conquered by Ladakh about 1630.","ja":"ンガリ地区ツァンダの古格王国は912年ごろ建国、1630年ごろラダックに滅ぼされた"},{"k":"history","zh":"1624年葡萄牙傳教士安德拉德抵達古格，是最早到那裡的西方人","en":"In 1624 Jesuit António de Andrade reached Guge, the first Westerner to arrive there.","ja":"1624年、イエズス会士アンドラーデが古格に到達し、最初の西洋人となった"},{"k":"record","zh":"1416年創建的哲蚌寺曾有上萬名僧侶，被稱為世界最大的寺院","en":"Drepung, founded in 1416, once housed up to 10,000 monks and was called the world's largest monastery.","ja":"1416年創建のデプン寺には最大1万人の僧がおり、世界最大の僧院と呼ばれた"},{"k":"history","zh":"1904年江孜宗山守軍抵抗英軍，江孜因此有「英雄城」之稱","en":"Gyantse is called the 'Hero City' for its fort's resistance against British troops in 1904.","ja":"江孜は1904年に宗山の砦で英軍に抵抗したことから「英雄城」と呼ばれる"},{"k":"people","zh":"奧地利登山家哈勒1946年逃到首府，後來成為達賴喇嘛的英文與地理老師","en":"Austrian climber Heinrich Harrer reached the capital in 1946 and became the young Dalai Lama's tutor.","ja":"オーストリアの登山家ハラーは1946年に首府へ逃れ、ダライ・ラマの家庭教師となった"},{"k":"legend","zh":"雍布拉康相傳是這片高原的第一座建築，屬於從天而降的首位國王","en":"Yumbulagang is said to be the region's first building, palace of the legendary first king who came from the sky.","ja":"ユムブラカンはこの地最初の建物とされ、天から降りた伝説の初代王の宮殿"},{"k":"people","zh":"相傳吞彌·桑布扎奉松贊干布之命赴天竺學習，參照梵文創製當地文字","en":"Thonmi Sambhota is said to have studied in India and created the local script based on Sanskrit.","ja":"トンミ・サンボータはインドで学び、梵字をもとにこの地の文字を作ったと伝わる"},{"k":"record","zh":"2008年北京奧運聖火從這一側被帶上世界最高峰的峰頂","en":"In 2008 the Beijing Olympic flame was carried to the top of Everest from this side.","ja":"2008年、北京五輪の聖火がこちら側から世界最高峰の頂上へ運ばれた"},{"k":"legend","zh":"傳說當地民族是獼猴與羅剎女的後代，澤當的山上有那個猴洞","en":"Legend says the local people descend from a monkey and an ogress, from a cave above Tsetang.","ja":"地元の民族は猿と羅刹女の子孫とされ、ツェタンの山にその洞窟がある"},{"k":"people","zh":"聖者米拉日巴年輕時以咒術殺人，悔悟後被師父要求反覆蓋塔拆塔","en":"Saint Milarepa killed with sorcery as a youth, then repented; his teacher made him build and tear down towers.","ja":"聖者ミラレパは若い頃呪術で人を殺め、改心後は師に塔を建てては壊すよう命じられた"},{"k":"record","zh":"首府的羅布林卡意為「寶貝園林」，是歷代達賴喇嘛的夏宮","en":"Norbulingka, the 'Jeweled Park', was the summer residence of successive Dalai Lamas.","ja":"ノルブリンカは「宝の園」の意で、歴代ダライ・ラマの夏の離宮"},{"k":"record","zh":"江孜大佛塔高約35公尺，塔內有77間佛殿","en":"Gyantse's great Kumbum stupa stands 35 m tall with 77 chapels inside.","ja":"江孜のクンブム大仏塔は高さ約35mで、内部に77の仏殿がある"},{"k":"festival","zh":"宗喀巴1409年創立的傳昭大法會，在當地曆法的正月舉行","en":"The Monlam Great Prayer Festival, founded by Tsongkhapa in 1409, is held in the first month of the local calendar.","ja":"ツォンカパが1409年に始めた大祈願祭（モンラム）は、地元暦の正月に行われる"},{"k":"record","zh":"宗喀巴1409年創建甘丹寺，寺主「甘丹赤巴」是格魯派的領袖","en":"Tsongkhapa founded Ganden Monastery in 1409; its throne-holder, the Ganden Tripa, heads the Gelug school.","ja":"ツォンカパが1409年に創建したガンデン寺の座主ガンデン・ティパは、ゲルク派の長"},{"k":"history","zh":"岡仁波齊一帶曾有古王國象雄，與苯教關係密切，7世紀被吐蕃征服","en":"The ancient Zhangzhung kingdom, tied to the Bon religion, centered near Mount Kailash until the Tubo empire took it.","ja":"カイラス山周辺には苯教と結びつく古王国シャンシュンがあり、7世紀に吐蕃に征服された"},{"k":"nature","zh":"神山岡仁波齊旁的瑪旁雍錯，是印度教最神聖的聖湖之一","en":"Lake Manasarovar near Mount Kailash is among the most sacred sites of Hinduism.","ja":"カイラス山の近くのマナサロワール湖は、ヒンドゥー教で最も神聖な湖の一つ"},{"k":"life","zh":"因土地堅硬、木材稀少，盛行把遺體交給禿鷲的天葬，直貢梯寺是著名天葬台","en":"Sky burial, feeding the dead to vultures, suits the hard ground and scarce wood; Drigung is a famous site.","ja":"土地が硬く木材も乏しいため鳥葬が行われ、ディグン寺は有名な鳥葬場"},{"k":"record","zh":"傳統醫學經典《四部醫典》由宇妥·元丹貢布編成，至今仍是當地醫學的基礎","en":"The 'Four Tantras', compiled by Yuthok Yonten Gonpo, still underpin the traditional medicine here.","ja":"宇妥・元丹貢布が編んだ『四部医典』は、今もこの地の伝統医学の基礎"}],
"CN-YN":[{"k":"festival","zh":"傣族新年「潑水節」，大家互相潑水祝福","en":"At the Dai New Year 'Water-Splashing Festival', people drench each other to share blessings.","ja":"タイ族の新年「水かけ祭り」では、互いに水をかけ合って祝福する"},{"k":"people","zh":"國歌《義勇軍進行曲》作曲者聶耳出生在省會","en":"Nie Er, composer of China's national anthem 'March of the Volunteers', was born in its capital.","ja":"国歌『義勇軍行進曲』の作曲者・聶耳は省都の生まれ"},{"k":"work","zh":"金庸《天龍八部》主角段譽，是這裡大理國的王子","en":"Duan Yu, hero of Jin Yong's Demi-Gods and Semi-Devils, is a prince of the Dali Kingdom here.","ja":"金庸『天龍八部』の主人公・段誉は、ここにあった大理国の王子"},{"k":"record","zh":"約170萬年前的元謀人，是中國乃至亞洲已知最早的直立人","en":"Yuanmou Man, about 1.7 million years old, is the earliest known Homo erectus in China and all of Asia.","ja":"約170万年前の元謀原人は、中国・アジアで知られる最古の原人"},{"k":"record","zh":"中國種植的咖啡有98%來自這裡","en":"98% of the coffee grown in China comes from here.","ja":"中国産コーヒーの98%がここで栽培されている"},{"k":"life","zh":"治跌打損傷的名藥「○○白藥」，1902年在這裡創製","en":"The famous wound remedy '___ Baiyao' was created here in 1902.","ja":"打撲・外傷の名薬「○○白薬」は1902年にここで作られた"},{"k":"festival","zh":"1999年世界園藝博覽會在省會舉辦，吸引950萬人次","en":"The 1999 World Horticultural Exposition was held in its capital, drawing 9.5 million visitors.","ja":"1999年の世界園芸博覧会が省都で開かれ、950万人が訪れた"},{"k":"history","zh":"戰國楚將莊蹻來到滇池一帶自立為「滇王」，建立古滇國","en":"Chu general Zhuang Qiao made himself King of Dian around Lake Dian, founding the Dian Kingdom.","ja":"戦国時代の楚の将軍・荘蹻は滇池周辺で「滇王」を名乗り、古代滇国を築いた"},{"k":"history","zh":"1956年晉寧石寨山出土金印「滇王之印」，相傳是漢武帝所賜","en":"A gold 'Seal of the King of Dian', said to be a gift of Emperor Wu of Han, was unearthed at Shizhaishan in 1956.","ja":"1956年、晋寧の石寨山で漢の武帝が滇王に贈ったとされる金印「滇王之印」が出土した"},{"k":"history","zh":"唐代的南詔國以大理為都，738年皮邏閣獲唐朝冊封為王","en":"The Nanzhao kingdom, ruled from Dali, began when Piluoge was recognized as king by the Tang in 738.","ja":"唐代の南詔国は大理を都とし、738年に皮邏閣が唐から王に封じられた"},{"k":"nature","zh":"怒江、瀾滄江、金沙江三條大河在這裡平行奔流，形成「三江並流」","en":"The Salween, Mekong and Yangtze flow side by side here in the Three Parallel Rivers area.","ja":"怒江・瀾滄江・金沙江の3大河が並んで流れる「三江併流」がある"},{"k":"history","zh":"法國在1904至1909年修築鐵路，從越南河內經河口通到省會","en":"The French built the railway from Hanoi via Hekou to the provincial capital between 1904 and 1909.","ja":"フランスは1904〜1909年に、ハノイから河口を経て省都に至る鉄道を建設した"},{"k":"history","zh":"抗戰時從緬甸臘戍通到省會的公路，是中國的補給生命線","en":"In WWII the Burma Road ran from Lashio in Burma to the provincial capital, a vital lifeline for China.","ja":"抗日戦争中、ビルマのラーショーから省都に通じるビルマ公路は中国の補給の生命線だった"},{"k":"history","zh":"二戰時美國志願航空隊「飛虎隊」以這裡為基地","en":"During WWII the American 'Flying Tigers' used this province as their home base.","ja":"第二次世界大戦中、米国義勇航空隊「フライング・タイガース」はここを本拠地とした"},{"k":"history","zh":"抗戰時的西南聯合大學設在省會，楊振寧、李政道都在此求學","en":"Wartime Lianda university was based in the capital; Nobel laureates Yang Chen-Ning and T.D. Lee studied there.","ja":"抗日戦争中の西南聯合大学は省都に置かれ、楊振寧や李政道が学んだ"},{"k":"history","zh":"1915年蔡鍔在此宣布反對袁世凱稱帝，掀起護國戰爭","en":"In 1915 Cai E declared this province's opposition to Yuan Shikai's monarchy, launching the National Protection War.","ja":"1915年、蔡鍔がここで袁世凱の帝政に反対を宣言し、護国戦争が始まった"},{"k":"nature","zh":"玉溪的撫仙湖是中國第二深的湖泊","en":"Fuxian Lake in Yuxi is the second deepest lake in China.","ja":"玉渓の撫仙湖は中国で2番目に深い湖"},{"k":"record","zh":"澄江化石地保存約5.18億年前的寒武紀生物，2012年列入世界遺產","en":"The Chengjiang fossil site, about 518 million years old, shows the Cambrian explosion; UNESCO-listed in 2012.","ja":"澄江の化石産地は約5億1800万年前のカンブリア紀生物を残し、2012年に世界遺産となった"},{"k":"record","zh":"祿豐龍是中國第一具裝架展出的恐龍骨骼，1958年還成了世界首枚恐龍郵票","en":"Lufengosaurus was the first dinosaur skeleton mounted in China, and in 1958 the first dinosaur on a stamp.","ja":"禄豊竜は中国で初めて組み立て展示された恐竜骨格で、1958年に世界初の恐竜切手にもなった"},{"k":"origin","zh":"中甸縣在2001年依小說《消失的地平線》裡的樂土，改名為「香格里拉」","en":"Zhongdian County was renamed Shangri-La in 2001 after the paradise in James Hilton's novel 'Lost Horizon'.","ja":"中甸県は2001年、小説『失われた地平線』の理想郷にちなみ「シャングリラ」と改名した"},{"k":"nature","zh":"梅里雪山主峰卡瓦格博被視為神山，從未有人登頂，2001年起禁止攀登","en":"Kawagebo, sacred peak of the Meili range, has never been climbed; climbing was banned in 2001.","ja":"梅里雪山の主峰カワカブは聖山とされ未踏峰のまま、2001年から登山が禁止された"},{"k":"history","zh":"1991年京都大學登山隊挑戰梅里雪山，遭夜間雪崩17人全數罹難","en":"In January 1991 an avalanche on Meili's Kawagebo killed all 17 members of a Kyoto University expedition.","ja":"1991年、梅里雪山に挑んだ京都大学の登山隊17人全員が夜間の雪崩で亡くなった"},{"k":"work","zh":"1959年電影《五朵金花》以大理白族青年的愛情為主題，帶紅了蝴蝶泉","en":"The 1959 film 'Five Golden Flowers', a Bai love story set in Dali, made Butterfly Spring famous.","ja":"大理の白族の恋を描いた1959年の音楽映画が大ヒットし、胡蝶泉が観光名所になった"},{"k":"life","zh":"1985年以後，每年冬天都有成千上萬的紅嘴鷗飛到省會的湖泊越冬","en":"Since about 1985, thousands of black-headed gulls have wintered on the capital's lakes every year.","ja":"1985年ごろから、毎冬何千羽ものユリカモメが省都の湖で越冬するようになった"},{"k":"food","zh":"野生菌「見手青」沒煮熟就吃，可能會出現滿屋子小人的幻覺","en":"Undercooked 'jianshouqing' wild mushrooms can make diners see tiny people climbing the walls.","ja":"野生キノコ「見手青」は生焼けで食べると、小人が見える幻覚を起こすことがある"},{"k":"brand","zh":"紅塔山香菸出自玉溪的紅塔集團，前身是1953年的玉溪捲菸廠","en":"Hongtashan cigarettes come from Yuxi's Hongta Group, founded in 1953 as the Yuxi Cigarette Factory.","ja":"たばこ「紅塔山」は玉渓の紅塔集団の製品で、前身は1953年創業の玉渓巻煙廠"},{"k":"nature","zh":"省會旁的滇池是省內面積最大的高原淡水湖","en":"Lake Dian beside the capital is the province's largest plateau freshwater lake.","ja":"省都の隣の滇池は、省内最大の高原淡水湖"},{"k":"festival","zh":"大理白族的「三月街」在農曆三月十五開市，相傳源自觀音降臨","en":"Dali's Bai 'Third Month Fair' opens on the 15th day of the 3rd lunar month, said to honor Guanyin's visit.","ja":"大理の白族の「三月街」は旧暦3月15日に始まり、観音の来訪に由来すると伝わる"},{"k":"people","zh":"詩人聞一多1946年在省會發表演說後，遭國民黨特務暗殺","en":"Poet Wen Yiduo was assassinated by Kuomintang agents in the provincial capital in 1946.","ja":"詩人の聞一多は1946年、省都で国民党の特務に暗殺された"},{"k":"life","zh":"西雙版納的傣族用貝葉棕的葉片刻寫佛經，稱為「貝葉經」","en":"The Dai of Xishuangbanna inscribe Buddhist scriptures on palm leaves, known as pattra sutras.","ja":"西双版納のタイ族は、ヤシの葉に経典を刻んだ「貝葉経」を伝えている"}],
"CN-ZJ":[{"k":"origin","zh":"省名來自錢塘江的古稱，意指江流曲折","en":"Named after the old name of the Qiantang River, which refers to its winding course.","ja":"省名は銭塘江の古称に由来し、川の曲がりくねる様を表す"},{"k":"sport","zh":"2023年第十九屆亞運會在省會舉行","en":"Its capital hosted the 19th Asian Games in 2023.","ja":"2023年の第19回アジア競技大会は省都で開かれた"},{"k":"work","zh":"《白蛇傳》中法海鎮壓白娘子的雷峰塔，在這裡的西湖邊","en":"Leifeng Pagoda, where Fahai imprisons Lady White in the Legend of the White Snake, stands by West Lake here.","ja":"『白蛇伝』で法海が白娘子を封じた雷峰塔は、ここの西湖のほとり"},{"k":"people","zh":"武俠小說大師金庸出生在這裡的海寧","en":"Martial-arts novelist Jin Yong was born in Haining here.","ja":"武侠小説の大家・金庸はここの海寧の生まれ"},{"k":"festival","zh":"世界互聯網大會自2014年起永久落腳這裡的水鄉烏鎮","en":"The World Internet Conference has been permanently based in the water town of Wuzhen here since 2014.","ja":"世界インターネット大会は2014年から、ここの水郷・烏鎮で常設開催"},{"k":"record","zh":"1979年溫州發出中國第一本個體工商戶營業執照","en":"In 1979, Wenzhou here issued China's first business license for a self-employed trader.","ja":"1979年、ここの温州が中国初の個人事業者営業許可証を発行した"},{"k":"life","zh":"生女兒時把酒埋進土裡，等她出嫁再挖出來宴客，叫「女兒紅」","en":"When a daughter is born, a jar of wine is buried, then served at her wedding: 'Nü'erhong' (daughter's red).","ja":"娘が生まれると酒を土に埋め、嫁ぐ日に掘り出して振る舞う。「女児紅」という"},{"k":"record","zh":"寧波舟山港的貨物吞吐量是世界第一","en":"Ningbo-Zhoushan Port here is the world's busiest port by cargo tonnage.","ja":"寧波舟山港の貨物取扱量は世界一"},{"k":"legend","zh":"傳說錢塘江大潮的前潮是伍子胥所化，後潮則是文種","en":"Legend says the tidal bore's leading wave is the spirit of Wu Zixu, and the wave behind it is Wen Zhong.","ja":"銭塘江の大潮の先頭の波は伍子胥の化身、後ろの波は文種だと伝わる"},{"k":"life","zh":"警方常在觀潮人潮中抓到逃犯，網友因此戲稱大潮為「錢塘江同志」","en":"Police keep catching fugitives in the tide-watching crowds, so netizens joke about 'Comrade Qiantang River'.","ja":"観潮の人混みでよく逃亡犯が捕まり、ネットでは大潮を「銭塘江同志」と呼ぶ"},{"k":"record","zh":"寧波天一閣建於 1561 年，乾隆建《四庫全書》藏書樓時以它為範本","en":"Ningbo's Tianyi Pavilion (1561) was the model for the libraries that housed the Siku Quanshu.","ja":"寧波の天一閣（1561年）は、『四庫全書』を収める書庫の手本になった"},{"k":"people","zh":"吃肉喝酒的瘋和尚濟公是天台人，在靈隱寺出家","en":"Ji Gong, the meat-eating, wine-drinking 'mad monk', came from Tiantai and was ordained at Lingyin Temple.","ja":"肉を食べ酒を飲む破戒僧・済公は天台の人で、霊隠寺で出家した"},{"k":"history","zh":"「臥薪嘗膽」終滅吳國的越王勾踐，都城會稽就是今天的紹興","en":"King Goujian of Yue, who 'slept on brushwood and tasted gall' to defeat Wu, ruled from Kuaiji, today's Shaoxing.","ja":"臥薪嘗胆で呉を滅ぼした越王勾践の都・会稽は、今の紹興だ"},{"k":"people","zh":"四大美女之一的西施是諸暨人，相傳常在江邊浣紗","en":"Xi Shi, one of China's Four Beauties, came from Zhuji and is said to have washed silk by the river.","ja":"中国四大美女の一人・西施は諸暨の人で、川辺で紗を洗っていたという"},{"k":"history","zh":"南宋以省會為都城，稱為「臨安」，直到 1276 年被蒙古攻陷","en":"The Southern Song made the capital its seat under the name 'Lin'an' until the Mongols took it in 1276.","ja":"南宋は省都を「臨安」として都に定め、1276年にモンゴルに攻め落とされた"},{"k":"record","zh":"一般認為省會在 1180 到 1315 年間，是全世界最大的城市","en":"The capital is believed to have been the world's largest city from 1180 to 1315.","ja":"省都は1180〜1315年ごろ、世界最大の都市だったと考えられている"},{"k":"history","zh":"1921 年中共一大遭法租界巡捕搜查，代表們移到嘉興南湖的遊船上開完","en":"After police raided the CCP's 1921 founding congress, delegates finished it on a tour boat on Jiaxing's South Lake.","ja":"1921年の中共第一回大会は警察の捜索を受け、嘉興・南湖の遊覧船で続けられた"},{"k":"brand","zh":"吉利汽車 1986 年在台州起家時是做冰箱零件，2010 年買下 Volvo","en":"Geely started in Taizhou in 1986 making refrigerator parts, and bought Volvo Cars in 2010.","ja":"吉利は1986年に台州で冷蔵庫部品メーカーとして始まり、2010年にボルボを買収した"},{"k":"food","zh":"東陽有用男童尿水煮蛋的「童子蛋」，蛋黃會變成綠色","en":"Dongyang's 'virgin boy eggs' are boiled in young boys' urine, turning the yolks green.","ja":"東陽の「童子蛋」は男児の尿で卵を煮たもので、黄身が緑色になる"},{"k":"life","zh":"越劇 1906 年起源於嵊州，到 1930 年代變成全由女性演出","en":"Yue opera arose in Shengzhou in 1906 and had become an all-female art form by the 1930s.","ja":"越劇は1906年に嵊州で生まれ、1930年代には女性だけで演じる芸能になった"},{"k":"work","zh":"黃公望《富春山居圖》1650 年被燒成兩段，分藏臺北故宮與省博物館","en":"Dwelling in the Fuchun Mountains burned in two in 1650; its halves are in Taipei and the provincial museum.","ja":"黄公望の『富春山居図』は1650年に焼けて二つに分かれ、台北と省博物館に分蔵される"},{"k":"origin","zh":"日本「天台宗」的名字，來自這裡發源地的天台山","en":"Japan's Tendai Buddhism takes its name from Mount Tiantai here, where the Tiantai school was born.","ja":"日本の天台宗の名は、宗派発祥の地であるここの天台山に由来する"},{"k":"brand","zh":"龍泉青瓷燒製技藝 2009 年列入聯合國非遺，日本鎌倉海灘曾出土約 5 萬片","en":"Longquan celadon firing was UNESCO-listed in 2009; some 50,000 of its shards were found on a Kamakura beach.","ja":"龍泉青磁の焼成技術は2009年に無形遺産に登録、鎌倉の浜からは約5万片が出土した"},{"k":"life","zh":"西班牙的華人有八成以上來自省內的青田縣","en":"Over 80% of the Chinese community in Spain comes from Qingtian County here.","ja":"スペインの華人の8割以上が、ここの青田県の出身だ"},{"k":"people","zh":"倡導「知行合一」的王陽明是餘姚人，東鄉平八郎曾刻印「一生俯首拜陽明」","en":"Wang Yangming of Yuyao taught the unity of knowledge and action; Admiral Tōgō revered him all his life.","ja":"知行合一の王陽明は余姚の人で、東郷平八郎は「一生俯首拝陽明」の印を作った"},{"k":"history","zh":"自號「鑑湖女俠」的革命家秋瑾，1907 年在紹興被清廷斬首","en":"Revolutionary Qiu Jin, the 'Female Knight-Errant of Jian Lake', was beheaded by the Qing in Shaoxing in 1907.","ja":"「鑑湖女俠」と名乗った革命家・秋瑾は、1907年に紹興で処刑された"},{"k":"legend","zh":"莫干山的名字，來自傳說中在山上替吳王鑄劍的干將、莫邪","en":"Moganshan is named for Gan Jiang and Mo Ye, legendary swordsmiths who forged a blade for the King of Wu here.","ja":"莫干山の名は、ここで呉王のために剣を鍛えた干将・莫邪の伝説に由来する"},{"k":"life","zh":"1920 年代莫干山上有 150 多棟洋人的避暑別墅","en":"By the 1920s, Moganshan had over 150 Western-style summer villas, mostly owned by foreigners.","ja":"1920年代の莫干山には、外国人の避暑別荘が150棟以上あった"},{"k":"festival","zh":"中國旅遊日訂在 5 月 19 日，紀念《徐霞客遊記》開篇，第一卷寫的就是遊天台山","en":"China Tourism Day (May 19) marks the start of Xu Xiake's travel diaries, whose first volume covers Mount Tiantai here.","ja":"中国観光日の5月19日は『徐霞客遊記』の書き出しの日で、第一巻は天台山の旅だ"},{"k":"legend","zh":"傳說治水的大禹葬在紹興會稽山，山腳下有大禹陵","en":"Legend holds that Yu the Great, tamer of the floods, is buried at Mount Kuaiji in Shaoxing.","ja":"治水の英雄・禹は紹興の会稽山に葬られたと伝わり、麓に大禹陵がある"},{"k":"people","zh":"蔣介石出生在奉化溪口，元配毛福梅 1939 年死於日軍對溪口的轟炸","en":"Chiang Kai-shek was born in Xikou, Fenghua; his first wife was killed there in a 1939 Japanese bombing.","ja":"蒋介石は奉化渓口の生まれで、最初の妻・毛福梅は1939年の日本軍の爆撃で亡くなった"}]};
